window.EXAM_PAPERS=window.EXAM_PAPERS||{};window.EXAM_PAPERS["1756567004"]={"id":"1756567004","title":"【判断推理】定义判断刷题题库","group":"专项练习","items":[{"id":"1718789647753","type":"single","material":"","stem":"绿色消费，也称可持续消费，是指一种以适度节制消费，避免或减少对环境的破坏，崇尚自然和保护生态等为特征的新型消费行为和过程。<br>根据上述定义，以下不属于绿色消费的是：","options":[{"label":"A","content":"尽量购买简装物品，减少包装浪费"},{"label":"B","content":"抵制一次性筷子，保护木材资源"},{"label":"C","content":"吃原生态珍稀野味，减少加工成本"},{"label":"D","content":"购买低耗能的电器，减少用电开支"}],"answer":"C","explanation":"绿色消费定义的关键信息：适度节制消费，避免或减少对环境的破坏，崇尚自然和保护生态。<br>A项，尽量购买简装物品，减少包装浪费，体现了避免或减少对环境的破坏，符合定义。<br>B项，抵制一次性筷子，保护木材资源，体现了避免或减少对环境的破坏，符合定义。C项，吃原生态珍稀野味，不是崇尚自然和保护生态，不符合定义。<br>D项，购买低耗能电器，体现了避免或减少对环境的破坏，符合定义。","no":1},{"id":"1718789647754","type":"single","material":"","stem":"侵犯行为简称侵犯，有时也可以称之为攻击行为，它是指个体违反了社会主流规范的、有动机的、伤害他人的行为。<br>根据上述定义，以下属于侵犯行为的是：","options":[{"label":"A","content":"加州某大学一名博士生闯入办公室，用枪击伤自己的导师"},{"label":"B","content":"某中学语文教师批评没有按时完成暑假作业的学生"},{"label":"C","content":"在一场冰球比赛中，甲方队员在抢球过程中不小心撞伤乙方队员"},{"label":"D","content":"在经过李某同意的情况下，王某将李某病中照片发到微信朋友圈"}],"answer":"A","explanation":"侵犯行为定义的关键信息：违反社会主流规范的、有动机的、伤害他人的行为。<br>A项，某博士生闯入办公室，用枪击伤了导师，是违反社会主流规范的、故意伤害他人的行为，符合定义。<br>B项，语文老师批评没有按时完成暑假作业的学生，并没有违反社会主流规范，批评也并不是伤害他人的行为，不符合定义。<br>C项，甲方队员在抢球过程中不小心撞伤乙方队员，不小心说明不是有动机地伤害他人，不符合定义。<br>D项，经过李某同意后，王某将李某病中照片发到朋友圈，经过同意，说明没有违反社会主流规范，发照片到朋友圈也并未伤害李某，不符合定义。","no":2},{"id":"1718789647755","type":"single","material":"","stem":"伦理信用是指人们交往中由一定的预先约定、契约、承诺、誓言等引发的一种伦理关系，其蕴涵的合理秩序则凝结为遵守诺言、履行约定的道德准则，人们基于对信用伦理关系合理秩序的理解和规则的践行便形成了相应的道德品行。<br>根据上述定义，下列涉及伦理信用的是：","options":[{"label":"A","content":"陈某看到一群人在围殴邻居的孩子，他一边报警，一边跑上前去喝止"},{"label":"B","content":"王某父亲曾借给张某10万元，王父去世后，王某要求张某还钱"},{"label":"C","content":"李某家乡发生洪涝灾害，不少农民颗粒无收，父亲要求他发动其公司员工和微信朋友捐钱捐物"},{"label":"D","content":"赵某答应了丈夫的临终请求，在丈夫去世后，对丈夫前妻留下的两个孩子视如己出，将他们抚养成人"}],"answer":"D","explanation":"伦理信用的产生需要人们预先约定，并且还要履行约定。<br>A项，陈某报警并喝止围殴孩子的人，属于突发事件，不存在预先约定、契约、承诺、誓言等，不符合定义。<br>B项，由于不知道张某是否还钱，所以不涉及道德准则，不符合定义。<br>C项，李某父亲要求李某发动其公司员工和微信朋友捐钱捐物，但没有预先约定，不符合定义。<br>D项，赵某答应丈夫临终请求，属于预先约定，赵某将孩子抚养成人，践行了约定，符合定义。","no":3},{"id":"1718789647756","type":"single","material":"","stem":"异质型人力资本是指某个特定历史阶段中具有边际收益递增生产力形态的人力资本，表现为拥有者所具有的独特能力，这些能力主要包括：综合协调能力、判断决策能力、学习创新能力和承担风险能力等。根据上述定义，下列不涉及异质型人力资本的是：","options":[{"label":"A","content":"某厂长期亏损，李某担任厂长后施行了大刀阔斧的改革，很快使工厂扭亏为盈"},{"label":"B","content":"技术员陈某潜心钻研技术，他将人们认为不太可能整合的两种技术巧妙结合在一起，大大降低了生产成本"},{"label":"C","content":"某包装厂效益平平，设计师王某应聘到该厂后，由于他的设计新颖、风格清新，一下子使该厂的包装产品畅销起来"},{"label":"D","content":"某厂聘请某院士担任技术顾问，一大批风险投资公司慕名而来，一些高学历人才也陆续加盟"}],"answer":"D","explanation":"根据题干定义，异质型人力资本描述的是一个人所具有的独特能力，而这种能力主要包括综合协调能力、判断决策能力、学习创新能力和承担风险能力等。<br>A项，李某大刀阔斧改革体现了判断决策能力，符合定义关键信息。<br>B项，陈某将两种技术结合在一起体现了学习创新能力，符合定义关键信息。<br>C项，王某设计的包装风格清新体现了学习创新能力，符合定义关键信息。<br>D项，某院士加盟只是吸引来了资金和人才，并没有体现出独特的能力，不符合定义关键信息。","no":4},{"id":"1718789647757","type":"single","material":"","stem":"在人际交往中，如果双方关系良好，一方就更容易接受另一方的某些观点、立场，甚至对对方提出的难为情的要求，也不太容易拒绝。这一现象在心理学上称为“自己人效应”。<br>根据上述定义，下列没有体现“自己人效应”的是：","options":[{"label":"A","content":"某作家在演讲时介绍了自己与听众相似的情况和经历，使听众形成“认同感”,演讲很受欢迎，他的观点很快被听众所接受"},{"label":"B","content":"小李是一名优秀的运动员，可是比赛时他发挥失常，很是沮丧。队友纷纷前来安慰，他表示自己并不在意，但其实他的心情一直很低落"},{"label":"C","content":"王老师发现中学生小明早恋，他和小明聊天时谈到自己年轻时的类似经历，小明觉得老师亲切可信，于是很乐意听从老师的建议"},{"label":"D","content":"某位将军和士兵同甘共苦，并且非常关心自己的士兵。士兵们觉得将军没有架子，乐于听从他的指挥"}],"answer":"B","explanation":"“自己人效应”定义的关键信息：因双方关系良好，而一方更容易接受另一方的某些观点、立场。<br>A项，听众因为作家有与自己相似的情况和经历而更容易接受作家的观点，符合定义。<br>B项，小李在听了队友的安慰后，实际上心情还是很低落，并没有接受“自己人”的观点，不符合定义。<br>C项，小明觉得老师曾经有与自己类似的经历，于是很乐意听从老师的建议，接受老师的观点，符合定义。<br>D项，士兵们觉得将军没有架子，是“自己人”,所以乐于听从他的指挥，接受他的观点，符合定义。","no":5},{"id":"1718789647758","type":"single","material":"","stem":"比德是指将自然物的某些特征比附于人们的某种道德情操，使自然物的自然属性人格化，人的道德品性客观化，其实质是认为自然美美在它所比附的道德伦理品格。<br>根据上述定义，下列没有包含“比德”自然审美观的是：","options":[{"label":"A","content":"作者在小说中称赞生性淡泊、安分守己的少妇“宛如冬梅，风知素韵，霜晓寒姿”"},{"label":"B","content":"人们总是把风儿比作叹息，那么秋天一定是多愁善感、小性恼人的姑娘，不可捉摸，难以讨好"},{"label":"C","content":"知者达于事理而周流无碍，有似于水，故知者乐水；仁者安于义理而厚重不迁，有似于山，故仁者乐山"},{"label":"D","content":"郑板桥以“咬定青山不放松，立根原在破岩中。千磨万击还坚劲，任尔东南西北风”赞美岩竹的坚韧顽强，隐喻自己藐视俗见的刚劲风骨"}],"answer":"B","explanation":"比德的定义要点：①将自然物的某些特征比附于人们的某种道德情操；②认为自然美美在它所比附的道德伦理品格。<br>A项，将冬梅的风韵姿态比作生性淡泊、安分守己的少妇，符合定义。<br>B项，将风儿比作叹息，将秋天比作多愁善感、小性恼人的姑娘，但叹息和多愁善感、小性恼人并非某种道德情操，不符合定义。<br>C项，将山水分别赋予了知者和仁者的道德情操，符合定义。<br>D项，将岩竹的坚韧顽强比作郑板桥藐视俗见的刚劲风骨，符合定义。","no":6},{"id":"1718789647759","type":"single","material":"","stem":"生物识别技术，即通过计算机与光学、声学、生物传感器和生物统计学原理等高科技手段密切结合，利用人体固有的生理特性(如静脉、人脸、虹膜、指纹等)和行为特征(如笔迹、声音、步态等)来进行个人身份的鉴定。<br>根据上述定义，下列最可能运用了生物识别技术的是：","options":[{"label":"A","content":"受害者在旁听了嫌疑人的数码电话录音后，确定他就是当时的袭击者"},{"label":"B","content":"某公司为考核员工出勤情况，引进了指纹打卡机，员工上班时必须输入指纹签到"},{"label":"C","content":"警方在犯罪现场找到一张外卖送货小票，通过查询网上外卖系统信息，锁定了几个犯罪嫌疑人"},{"label":"D","content":"某涉密场所设置了严格的门禁，人们只有在密码输入正确且在电阻屏上手写出具有进入权限的工作人员姓名后才能进入"}],"answer":"B","explanation":"生物识别技术的定义要点：①计算机与高科技手段密切结合；②利用人体固有的生理特性和行为特征来进行个人身份的鉴定。<br>A项，受害者是根据自己对声音的记忆来辨别嫌疑人的，并没有利用高科技手段，不符合要点①。<br>B项，“指纹打卡机”是计算机与高科技手段密切结合，符合要点①;指纹属于人体固有的生理特性，符合要点②。<br>C项，“通过查询网上外卖系统信息”锁定嫌疑人，并没有利用人体固有的生理特性和行为特征，不符合要点②。<br>D项，输入密码没有体现人体固有的生理特性，且手写名字并不涉及笔迹这一行为特征，不符合要点②。","no":7},{"id":"1718789647760","type":"single","material":"","stem":"形象联想记忆法是把所需要记忆的材料同某些具体的事物、数字、字母、汉字或几何图形等联系起来，借助形象思维加以记忆。形象联想既有利于激发兴趣，调动学习积极性，又有利于加深记忆。<br>根据上述定义，下列没有运用形象联想记忆法的是：","options":[{"label":"A","content":"号称“时尚女鞋之国”的意大利，它的地图轮廓就像一只高跟靴子"},{"label":"B","content":"海参长得像黄瓜(cucumber),又长在海里(sea),所以它叫“seacucumber”"},{"label":"C","content":"新疆的地形特征“三山夹两盆”可与“疆”的右半部分联系起来：“三横”表示三山，“两田”表示两大盆地"},{"label":"D","content":"篮球界的迈克尔·乔丹、音乐界的迈克尔·杰克逊、赛车界的迈克尔·舒马赫……记住，这些牛人都叫“迈克尔”"}],"answer":"D","explanation":"形象联想记忆法定义的关键信息：把所需要记忆的材料同某些具体事物、数字、字母、汉字或几何图形等联系起来。<br>A项，将“时尚女鞋之国”意大利的地图轮廓与高跟靴子这一具体的几何图形联系起来，运用了形象联想记忆法。<br>B项，将海参的英文单词与黄瓜和海等具体事物的英文单词联系起来，运用了形象联想记忆法。<br>C项，将新疆的地形特征“三山夹两盆”与“疆”这个具体的汉字联系起来，运用了形象联想记忆法。<br>D项，将几个名字中相同的一部分进行记忆，并没有“同某些具体事物、数字、字母、汉字或几何图形等联系起来”,没有运用形象联想记忆法。","no":8},{"id":"1718789647761","type":"single","material":"","stem":"微商，一般是指以个人为单位的、利用web3.0时代所衍生的载体渠道，将传统方式与互联网结合，不存在区域限制，且可移动地实现销售渠道新突破的小型个体行为。<br>根据上述定义，以下属于微商的是：","options":[{"label":"A","content":"某大型化妆品公司在微信账号上销售商品，吸引了一大批消费者"},{"label":"B","content":"某眼镜店通过大力宣传吸引了许多年轻消费者进店购买"},{"label":"C","content":"李某开的饭店为周边居民提供电话预定、上门送外卖的服务"},{"label":"D","content":"张某在市中心的服装店生意不错，他在微信上卖出的更多"}],"answer":"D","explanation":"微商的定义要点：①以个人为单位；②利用web3.0时代所衍生的载体渠道，将传统行业与网络销售平台结合；③不存在区域限制。<br>A项，某大型化妆品公司不是以个人为单位，不符合要点①。<br>B项，某眼镜店不是以个人为单位，不符合要点①;大力宣传没有体现利用web3.0时代所衍生的载体渠道，不符合要点②。<br>C项，该饭店电话订餐并非使用网络销售平台，不符合要点②;上门送外卖会受到区域的限制，不符合要点③。<br>D项，张某利用微信卖出服装，符合定义。","no":9},{"id":"1718789647762","type":"single","material":"","stem":"电信诈骗，是指犯罪分子通过电话、网络和短信方式，发布虚假信息，设置骗局，对受害人实施远程、非接触式诈骗，诱使受害人给犯罪分子打款或转账，进行非法侵占他人财物的犯罪行为。<br>根据上述定义，以下不属于电信诈骗的是：","options":[{"label":"A","content":"王某在网上发起新房团购，承诺一千元定金可抵五万元房款，顾客缴纳定金之后才发现该楼盘已售罄，王某也消失了"},{"label":"B","content":"李某盗用正在出差的张先生的微信头像，冒充张先生给张太太发微信说遇到事故，骗走两万元"},{"label":"C","content":"张某谎称自己患上不治之症，伪造诊断书、编造假故事放在网上，通过众筹募集到三万元医药费"},{"label":"D","content":"李老太太打电话找保洁，家政公司派来的保洁员王某忽悠李老太太从王某丈夫的店里购买了数千元保健品"}],"answer":"D","explanation":"电信诈骗定义的关键信息：通过电话、网络和短信等方式实施远程、非接触式诈骗。<br>A项，王某在网上发起新房团购，属于通过网络诈骗，符合定义。<br>B项，李某盗用微信头像使用微信诈骗，属于通过网络诈骗，符合定义。<br>C项，张某编造故事放到网上，属于通过网络诈骗，符合定义。<br>D项，李老太太只是通过打电话找保洁，但是王某忽悠李老太太购买保健品，不是通过电话、网络和短信的方式，是面对面的接触式诈骗，不符合定义。","no":10},{"id":"1718789647763","type":"single","material":"","stem":"沉锚效应，指的是人们在对某人某事做出判断时，易受第一印象或第一信息支配，就像沉入海底的锚一样把人们的思想固定在某处。<br>根据上述定义，以下不符合沉锚效应的是：","options":[{"label":"A","content":"小高在面试时西装革履，侃侃而谈，不卑不亢，主管对他很满意。但在实习期，主管发现小高做事虎头蛇尾，对他很失望，最终没有录取他"},{"label":"B","content":"小刘开了一家饰品店，他有意将饰品价格标注得略高于可接受的价格，然后主动给顾客打折，顾客认为这家店的饰品都很实惠"},{"label":"C","content":"张老师第一次上课时内容充实，言语幽默，学生对他评价很好，第二次上课时张老师讲课单调乏味，学生觉得张老师今天状态不好，影响了发挥"},{"label":"D","content":"一家皮具制造商只在机场和高端百货商店建立专卖店，且有意与世界名牌店比邻，虽然其商品比其他同类国产商品价格略高，但近年来销量一直保持增长趋势"}],"answer":"A","explanation":"沉锚效应定义的关键信息：对某人某事做出判断易受第一印象或第一信息的支配。<br>A项，主管对小高的第一印象是满意的，但是实习期间发现了小高的问题而改变了看法，没有录取他，显然没有受到第一印象的支配，不符合定义。<br>B项，饰品店给顾客的第一印象是价格高，然后主动打折，通过对比给顾客留下实惠的印象，符合定义。<br>C项，张老师给学生们的第一印象是好的，所以第二次上课学生判断张老师讲课只是状态不好，是根据第一次上课时的印象，符合定义。<br>D项，皮具制造商把专卖店设在卖高端百货的地方，给人的第一印象是其产品是大品牌，销量增长也是受第一印象的影响，符合定义。","no":11},{"id":"1718789647764","type":"single","material":"","stem":"环境移民，是指人类生存的自然环境和人居环境受到突发或渐进式的不利影响而产生的各种人口迁移行为，包括自愿的、非自愿的，事后被迫的、预先计划的，暂时的、永久性的，个体和家庭自发的、政府主导的移民类型。<br>根据上述定义，以下不属于环境移民的是：","options":[{"label":"A","content":"切尔诺贝利核污染区域居民集体撤离家园"},{"label":"B","content":"为了保护三江源地区而限制放牧后的生态移民"},{"label":"C","content":"安史之乱时期中原人民大量南迁"},{"label":"D","content":"元朝定都大都之后大量牧民南迁"}],"answer":"D","explanation":"环境移民定义的关键信息：生存的自然环境和人居环境受到突发或渐进式的不利影响。<br>A项，切尔诺贝利核泄漏造成严重污染，因核污染撤离家园，属于生存的自然环境受到突发式的不利影响，符合定义。<br>B项，为了保护三江源地区而限制放牧，因限制放牧而移民，属于生存的人居环境受到渐进式的不利影响，符合定义。<br>C项，安史之乱导致人民生活于水深火热之中，因战乱中原人南迁，属于生存的人居环境受到渐进式的不利影响，符合定义。<br>D项，元朝定都大都之后大量牧民南迁，不是因为受到环境的不利影响，主要是受政治因素影响，而且是为了更好的环境，不符合定义。","no":12},{"id":"1718789647765","type":"single","material":"","stem":"自我知识是关于某人自己的心智状态的知识，包括关于某人自己当下的经验、思想、信念或愿望的知识。<br>根据上述定义，下列不属于自我知识的是：","options":[{"label":"A","content":"甲通过听电台的天气报道而得知某地正在下雨"},{"label":"B","content":"乙查看自己工资后决定换一个工作"},{"label":"C","content":"丙意识到如果不加强锻炼，会影响自身健康"},{"label":"D","content":"丁相信自己通过努力一定会成功"}],"answer":"A","explanation":"自我知识定义的关键信息：关于某人自己的心智状态的知识。A项，甲获取的是关于天气的信息，并非关于自己的心智状态，不符合定义。<br>B项，查看自己工资后决定换一个工作，属于思想，符合定义。<br>C项，意识到如果不加强锻炼，会影响自身健康，属于经验，符合定义。<br>D项，相信自己通过努力一定会成功，属于信念，符合定义。","no":13},{"id":"1718789647766","type":"single","material":"","stem":"文化焦虑，指在全球化和现代化进程中，基于传统文化受到外来文化的挤压而产生的迷惘、焦躁、失望、不自信等心理状态。<br>下列不属于文化焦虑的是：","options":[{"label":"A","content":"为应对西方文化的入侵，有些家长建议教育部门尽快制定相关政策，让包括四书五经在内的传统经典进入中小学课堂"},{"label":"B","content":"全国各地大大小小的城市中，随处可见“罗马广场”“加州小镇”之类的包含外国地名的广场、小区和公园"},{"label":"C","content":"圣诞节、情人节、复活节现在越来越流行，不少传统节日却受到年轻人的冷落，部分学者呼吁尽快采取措施严格限制洋节日"},{"label":"D","content":"许多历史文化遗产及人文景观随着如火如荼的旧城改造而不断消失，越来越多的有识之士对此深感忧虑"}],"answer":"B","explanation":"文化焦虑的定义要点：①基于传统文化受到外来文化的挤压；②产生迷惘、焦躁、失望、不自信等心理状态。<br>A项，为应对西方文化入侵，家长们建议教育部尽快将传统经典引进中小学课堂，体现了面对外来文化而产生焦躁的状态，符合定义。<br>B项，所述现象体现了外来文化的入侵，但并未体现产生了迷惘、焦躁、失望、不自信等心理状态，不符合定义。<br>C项，部分学者面对外来节日对传统节日的冲击，要求采取严格限制洋节的做法，体现了不自信的心态，符合定义。<br>D项，受外来文化的影响，旧城改造使许多历史文化遗产和人文景观消失，有识之士产生忧虑，符合定义。","no":14},{"id":"1718789647767","type":"single","material":"","stem":"亲情经济指商家利用人们对亲情关系的重视，在传统节日期间举行商业让利促销活动。<br>下列属于亲情经济的是：","options":[{"label":"A","content":"某影楼在店庆3周年之际推出户外全家福拍摄优惠活动"},{"label":"B","content":"某食品企业中秋节期间适当调高了礼盒装月饼的销售价格"},{"label":"C","content":"某商场在儿童节前夕推出少儿服装、玩具对折优惠活动"},{"label":"D","content":"重阳节期间许多商场的按摩椅、保健品都有不同程度的优惠"}],"answer":"D","explanation":"亲情经济的定义要点：①传统节日期间；②让利促销活动。<br>A项，影楼在店庆3周年推出优惠，并不确定是否处于传统节日期间，不符合要点①。<br>B项，食品企业提高了销售价格，不符合要点②。<br>C项，商场在儿童节推出了打折优惠活动，儿童节不属于传统节日，不符合要点①。<br>D项，商家在重阳节推出不同程度的优惠，符合定义。","no":15},{"id":"1718789647768","type":"single","material":"","stem":"主动补偿，指企业针对自己有瑕疵的产品或服务，主动向消费者做出经济补偿的行为。<br>下列属于主动补偿的是：","options":[{"label":"A","content":"小王和几个同事在某火锅店消费时发现菜盘里有一只死苍蝇，就去找老板讨要说法，经过半个多小时的协商，老板终于同意免单并道歉"},{"label":"B","content":"某高校食堂收到了学生关于饭菜质次量少、价格偏高的投诉，立即着手整改。三天后，食堂的饭菜质量有了明显提高，价格也有所下降"},{"label":"C","content":"某公司发现，新近推出的一款手机在充电时发生爆炸，很快向社会公开承诺：用户可在30天内免费更换手机电池，邮寄费、路费等均由公司承担"},{"label":"D","content":"老张上星期买了一辆摩托车，骑起来感觉很好。两天前，厂家突然通知他带着原始发票到指定修理厂更换电路控制器，还送给他200元加油卡"}],"answer":"D","explanation":"主动补偿的定义要点：①企业针对自己有瑕疵的产品或服务；②主动；③做出经济补偿。<br>A项，小王和同事主动找老板讨说法，并非老板主动，不符合要点②。<br>B项，学生主动投诉价格高，并非食堂主动降价，食堂也没有做出经济补偿，不符合要点②③。<br>C项，公司主动免费更换电池，并且承担费用，但并未做出经济补偿，不符合要点③。<br>D项，厂家主动通知老张到修理厂更换电路控制器，并送了200元加油卡作为补偿，符合定义。","no":16},{"id":"1718789647769","type":"single","material":"","stem":"人才逆流动，指原本在知名大城市工作的专业人士，主动选择到中小城市工作的人才流动现象。<br>下列属于人才逆流动的是：","options":[{"label":"A","content":"小赵家乡的县城近年来经济发展迅猛，正在到处招聘有大城市工作背景的专业人才，反复考虑之后，小赵辞去北京某研究部门的工作回乡应聘成功"},{"label":"B","content":"高中毕业的小韩在深圳打拼多年，深感这里的工作机遇虽多，年收入也很可观，但竞争压力太大，有时力不从心，春节后他决定留在家乡创业"},{"label":"C","content":"小黄在天津某大学桥梁设计专业取得硕士学位后，来到女友所在的小城市找了一份不错的工作，他和女友都很开心"},{"label":"D","content":"80后白领小李在上海的一家金融机构总部任职，几天前决定跳槽到附近的一家保险公司，意外发现自己的这一决定与不少同事的选择不谋而合"}],"answer":"A","explanation":"人才逆流动的定义要点：①原本在知名大城市工作的专业人士；<br>②主动选择到中小城市工作。<br>A项，小赵原本是大城市的专业人才，主动回到了县城，符合定义。<br>B项，并未提及小韩是否是专业人士，不符合要点①。<br>C项，小黄刚取得硕士学位，没有工作过，不符合要点①。<br>D项，小李跳槽到附近的一家公司，依然在上海，不符合要点②。","no":17},{"id":"1718789647770","type":"single","material":"","stem":"语言智能，指利用计算机程序实现人和机器之间的语言交流，或让机器自主完成与语言有关的工作。<br>下列属于语言智能的是：","options":[{"label":"A","content":"人工智能“阿尔法狗”在历时数月的人机大战中以绝对优势战胜多名世界级的围棋高手"},{"label":"B","content":"为拓展国外市场，某公司新产品设置了语言切换按钮，借助这些按钮，用户可以实现多语种操作系统的切换"},{"label":"C","content":"在某诗歌比赛中，根据评委说出的关键词，机器人“小薇”当场写出了几首辞藻华美、意境清新的作品"},{"label":"D","content":"高铁、动车、地铁上都配备了可以自动播报沿途站名、当前时速、实时气温的汉英双语语音系统"}],"answer":"C","explanation":"语音智能的定义要点：①利用计算机程序实现人与机器之间的语言交流；②机器自主完成与语言有关的工作。<br>A项，“阿尔法狗”并不涉及语言，不符合要点①②。<br>B项，产品设置语言切换按钮，但没有体现人与机器人的语言交流或自主完成相关工作，不符合要点①②。<br>C项，机器人“小薇”根据评委的关键词，写出和语言相关的作品，符合定义。<br>D项，自动播报站名、当前时速、实时气温的语音体系，没有体现人与机器人的语言交流或机器自主完成与语言有关的工作，不符合要点①②。","no":18},{"id":"1718789647771","type":"single","material":"","stem":"定向销售，指商家出于特定目的，以低于市场同类商品的价格向特定客户出售商品的营销方式。<br>下列属于定向销售的是：","options":[{"label":"A","content":"为打响知名度，吸引购车者，某汽车城决定开业当日给予医生、教师2万元的优惠，比许多4S店便宜了不少"},{"label":"B","content":"为庆祝公司成立十周年，某公司董事会决定给员工发放纪念品。经过与某皮具厂家协商，以优惠价格购买了一批时尚、高档的真皮包"},{"label":"C","content":"为了避免浪费，某生鲜店规定：每天晚上8点后，所有非冰冻类的鲜鱼、鲜肉产品一律五折出售"},{"label":"D","content":"某食品生产企业为了实现一季度销售业绩开门红，以行业底价线上线下同时开展促销活动，销售量大幅上升"}],"answer":"A","explanation":"定向销售的定义要点：①商家出于特定目的；②以低于市场同类商品的价格；③向特定客户出售商品。<br>A项，汽车城为打响知名度，向特定的人群优惠出售汽车，符合定义。<br>B项，公司向员工发放纪念品，和员工没有买卖关系，不属于商家，不符合要点①②③。<br>C项，生鲜店为避免浪费，生鲜都一律五折出售，未体现向特定客户出售，不符合要点③。<br>D项，食品企业为实现开门红，以行业底价开展促销活动，未体现低于市场同类商品价格和向特定客户出售，不符合要点②③。","no":19},{"id":"1718789647772","type":"single","material":"","stem":"语音融合，指在完全不自觉的情况下，频繁交流的两人口音逐渐趋同的现象。<br>下列属于语音融合的是：","options":[{"label":"A","content":"楼先生移居海外多年，很少使用中文，更不用说家乡话了。一次晚宴上遇到了一个老乡，一句“烂糊糊”勾起了差不多早已忘光的乡音，两人用家乡话整整聊了一夜"},{"label":"B","content":"老张夫妇结婚十多年了，家里的饮食习惯已经分不清南北，就连张先生的东北腔也几乎失去了原先的味道，妻子的广东话听起来也变得怪怪的，女儿经常取笑他们是真正的“夫唱妇随”"},{"label":"C","content":"朱女士的汉语口语课深受留学生喜爱，不仅发音标准、语调柔美，还时不时地在课堂上讲一些有趣的小段子。不到半年时间，大多数学员都能学着她的腔调进行日常会话"},{"label":"D","content":"小黄来到南方某海滨小城工作后，每天坚持收看当地的方言电视节目，模仿播音员的发音。半年之后，她的语调、语气、用词，听起来就像一个土生土长的当地居民"}],"answer":"B","explanation":"语音融合的定义要点：①在完全不自觉的情况下；②频繁交流的两人口音逐渐趋同。<br>A项，楼先生因一句家乡话勾起了乡音，就开始用家乡话聊了一夜，没有逐渐变化的过程，不符合要点②。<br>B项，老张夫妇两人十多年的相处中，因对方不自觉的交流使得家乡话逐渐失去原来的味道，符合定义。<br>C项，学员们因为喜爱朱女士的口音，有意学习进行日常对话，不符合要点①。<br>D项，小黄是有意识地模仿播音员的发音，不符合要点①。","no":20},{"id":"1718789647773","type":"single","material":"","stem":"个人独资企业是指依照《中华人民共和国个人独资企业法》在中国境内设立，由一个自然人投资，财产为投资人个人所有，投资人以其个人财产对企业债务承担无限责任的经营实体。<br>根据上述定义，以下对个人独资企业理解正确的是：","options":[{"label":"A","content":"个人独资企业解散后，即免除了对债权人的责任"},{"label":"B","content":"个人独资企业所获利润，投资人需要缴纳企业所得税"},{"label":"C","content":"个人独资企业的财产归投资人个人所有，投资人对企业事务拥有控制与支配权"},{"label":"D","content":"一人有限责任公司可以投资设立个人独资企业"}],"answer":"C","explanation":"个人独资企业的定义要点：①自然人投资；②财产为投资人个人所有；③投资人以其个人财产对企业债务承担无限责任的经营实体。<br>A项，即免除了对债权人的责任，不符合要点③。<br>B项，个人独资企业所获利润，投资人不需要缴纳企业所得税，只需缴纳个人所得税，不符合要点②。<br>C项，个人独资企业的财产归投资人个人所有，投资人对企业事务拥有控制与支配权，符合定义。<br>D项，一人有限责任公司并不是自然人，不符合要点①。","no":21},{"id":"1718789647774","type":"single","material":"","stem":"技术标准是指对工农业产品和工程建设的质量、规格和检验方法，以及对技术文件上常用的图形、符号等所作的技术规定。是从事生产、建设的一种共同依据。<br>根据上述定义，以下属于技术标准的是：","options":[{"label":"A","content":"国家关于婴幼儿奶粉质量标准的规定"},{"label":"B","content":"国家关于评定卫生城市的标准细则"},{"label":"C","content":"国家关于缺陷产品召回的管理规定"},{"label":"D","content":"工业局对冶金机械厂区设备烟尘排放量的检测标准"}],"answer":"A","explanation":"技术标准的定义要点：①对工农业产品和工程建设的质量、规格和检验方法；②对技术文件上常用的图形、符号等所作的技术规定；③是从事生产、建设的一种共同依据。<br>A项，婴幼儿奶粉属于工农业产品，符合定义。<br>B项，评定卫生城市不属于工农业产品，不符合要点①。<br>C项，缺陷产品召回是已经生产过的产品，不符合要点③。<br>D项，烟尘排放量的检测标准不属于工农业产品，不符合要点①。","no":22},{"id":"1718789647775","type":"single","material":"","stem":"货币政策是指中央银行为实施既定的经济目标而采取的各种控制、调节货币供应量和信用总量的方针、政策、措施的总称。<br>根据上述定义，以下属于中国人民银行运用货币政策工具的是：","options":[{"label":"A","content":"中国人民银行为了刺激消费，大幅下调存款利率"},{"label":"B","content":"商业银行依法按照一定比例向中国人民银行交足存款准备金"},{"label":"C","content":"中国人民银行经理国库业务"},{"label":"D","content":"中国人民银行在商业银行资金短缺时，对其提供贷款"}],"answer":"A","explanation":"货币政策的定义要点：①中央银行为实施既定经济目标；②控制、调节货币供应量和信用总量的方针、政策和措施。<br>A项，刺激消费(既定经济目标),调存款利率(调节货币供应量),符合定义。<br>B项，商业银行不等同于中央银行，不符合要点①。<br>C项，经理国库业务不是既定的经济目标，不符合要点①。<br>D项，对商业银行提供贷款不是既定的经济目标，不符合要点①。","no":23},{"id":"1718789647776","type":"single","material":"","stem":"近因效应是指新出现的具有对立意义的刺激能够把人们心目中已有的印象反转为对立的印象。<br>根据上述定义，下列情形符合近因效应的是：","options":[{"label":"A","content":"自从老王到养老院做志愿者后，同事们就对他刮目相看"},{"label":"B","content":"小林的学习成绩不太好，但是羽毛球水平很高，同学们很羡慕他"},{"label":"C","content":"一家口碑良好的企业偷税漏税的丑闻被曝光后，公众指责其为“无良企业”"},{"label":"D","content":"医疗事故发生后，医院诚恳地向患者家属道歉并减免了医药费，家属表示愿意谅解"}],"answer":"C","explanation":"近因效应定义的关键信息：新出现的具有对立意义的刺激能够反转原来的印象。<br>A项，同事们对老王只是刮目相看，并没有涉及反转原来的印象，不符合定义。<br>B项，同学们羡慕小林，并没有体现反转原来的印象，不符合定义。<br>C项，偷税漏税(新出现的刺激)使原来的好印象(口碑良好)转变为坏印象(无良企业),符合定义。<br>D项，医疗事故发生后，家属表示谅解，没有涉及反转原来的印象，不符合定义。","no":24},{"id":"1718789647777","type":"single","material":"","stem":"布雷斯悖论现象是指在一个交通网络上增加一条路段不仅没有减少交通延滞，反而使整个交通网络上所有出行者的出行时间都增加的现象。<br>根据上述定义，下列属于布雷斯悖论现象的是：","options":[{"label":"A","content":"H市在拆除了一条6车道高速路，修建成一个方圆8千米的公园后，很多道路专家惊讶地发现，城市环境改善了，交通状况也没有恶化"},{"label":"B","content":"为缓解交通拥堵，G市将市内与主干道相连的几条单行线改为双向通行，结果交通事故明显增多，堵车情况进一步恶化"},{"label":"C","content":"N市在城区主干道下方又修建了一条地下隧道，由于入口处和出口处交通汇集，隧道建成后交通反较之前更为拥堵"},{"label":"D","content":"W市新建了两条贯通城市东一西、南—北的双向4车道柏油马路后，市内交通不再像以前那么拥堵了"}],"answer":"C","explanation":"布雷斯悖论现象定义的关键信息：交通网络中增加一条路段反而使整个交通网络更拥堵。<br>A项没有增加路段且交通状况没有恶化，不符合定义。<br>B项只是改造路线并没有增加路段，不符合定义。<br>C项增加了一条地下隧道后交通更为拥堵，符合定义。<br>D项交通网络并没有更拥堵，而是变得比以前通畅了，不符合定义。","no":25},{"id":"1718789647778","type":"single","material":"","stem":"过度合理化效应是指给人们报酬让他们做自己喜欢的事会让他们将其行为归因于报酬，这样就会削弱他们的自我知觉——因为兴趣而去做。<br>根据上述定义，下列情形属于过度合理化效应的是：","options":[{"label":"A","content":"小李抢救落水儿童，被见义勇为基金会奖励1万元"},{"label":"B","content":"某收视率低的电视节目以大奖吸引观众，冲着大奖而来的观众越来越多"},{"label":"C","content":"随着公司效益的提高，员工因奖金没有相应提高而多有怨言"},{"label":"D","content":"妈妈为鼓励爱画画的小明，画一幅画奖励他10元钱，小明画得更多却有些潦草了"}],"answer":"D","explanation":"过度合理化效应定义的关键信息：给做自己喜欢做的事的人报酬，会削弱其因兴趣而去做事的知觉。<br>A项，1万元的奖励是小李抢救落水儿童之后给的，而不是在抢救儿童之前，不符合定义。<br>B项，观众是冲着大奖观看电视，并非自己喜欢这个电视节目，不符合定义。<br>C项，员工并没有得到额外的报酬，不符合定义。<br>D项，小明爱画画(自己喜欢做的事),每一幅画都得到金钱奖励(报酬),反而他的画变得潦草了(自我知觉削弱),符合定义。","no":26},{"id":"1718789647779","type":"single","material":"","stem":"防御中的攻势行动是指在有利的时机和态势下，防御部队采取的进攻性行动。<br>根据上述定义，下列军事行动不属于防御中的攻势行动的是：","options":[{"label":"A","content":"对突入阵地之敌实施冲击，消灭突入之敌，改善或恢复防御态势"},{"label":"B","content":"防御的军队对小股进攻之敌实施主动攻击，击退敌人的进攻"},{"label":"C","content":"直接抗击敌人冲击的分队，对冲击受挫滞留于阵地前沿之敌实施主动攻击，以出击消灭敌人，稳定防御态势"},{"label":"D","content":"被包围的部队组织精干小分队，跳出包围圈，插到敌人侧后袭扰敌人，钳制围攻之敌"}],"answer":"D","explanation":"防御中的攻势行动定义的关键信息：防御部队的进攻性行动。<br>A项，消灭突入阵地之敌，改善或恢复防御态势，符合定义。<br>B项，防御的军队对小股进攻之敌实施主动攻击，符合定义。<br>C项，主动攻击滞留于阵地前沿之敌，稳定防御态势，符合定义。<br>D项，被包围的部队跳出包围圈，钳制围攻之敌，并未体现进攻性行动，不属于防御中的攻势行动。","no":27},{"id":"1718789647780","type":"single","material":"","stem":"体验式教学是指通过创造实际的情景和机会，呈现或再现、还原教学内容，使学生在亲历的过程中理解并建构知识、发展能力、产生情感、生成意义的教学观和教学形式。<br>根据上述定义，下列不属于体验式教学的是：","options":[{"label":"A","content":"在详细讲解了相关的知识要领和操作程序后，教练坐到了副驾驶的位置，换小李坐上驾驶位，开车上路"},{"label":"B","content":"教授《股票原理》课程的赵教授要求每位学生以3000元本金开设一个股票账户，学期结束时以交易的次数和账户余额评定成绩"},{"label":"C","content":"某大学策划了“重走长征路，祖国在我心”爱国主义教育活动，分批组织学生重走当年红军长征时爬过的雪山、走过的草地"},{"label":"D","content":"为了帮助学生摆脱“哑巴式英语”的困境，王老师用心搜集了大量原汁原味反映英国人日常生活交际的视频供学生观摩"}],"answer":"D","explanation":"体验式教学的定义要点：①创造实际的情境和机会，呈现或再现、还原教学内容；②学生有亲历过程。<br>A项，小李坐上驾驶位，开车上路，有实际的情境且学生亲自经历了，符合要点①和②。<br>B项，每位学生以3000元本金开设一个股票账户进行实际交易，符合要点①和②。<br>C项，组织学生重走当年红军长征时爬过的雪山、走过的草地，让学生亲身经历长征的过程，符合要点①和②。<br>D项，让学生观摩视频既没有实际的情境，学生也没有亲历过程，不符合要点①和②。","no":28},{"id":"1718789647781","type":"single","material":"","stem":"迭代开发就是由于市场的不确定性高，在需求没被完全确定之前，开发就迅速启动，每次循环不求完美，但求不断发现新问题，获取和积累新知识，并自适应地控制过程，在一次迭代中完成系统的部分功能，然后将未成熟的产品交付给领先用户，通过他们的反馈来进一步细化需求，从而进入下一轮的迭代，不断获取用户需求、完善产品。<br>根据上述定义，下列不属于迭代开发的一项是：","options":[{"label":"A","content":"甲公司先向市场推出极简的原型产品，以最小的成本和有效方式验证产品是否符合用户需求，然后再结合需求，迅速添加组件"},{"label":"B","content":"乙公司开发产品时，遵循预先计划的需求、分析、设计、编码、测试的步骤顺序进行，成功开发出新产品"},{"label":"C","content":"丙公司的某产品在推出5年之后才撤掉之前的测试版字样，成为稳定的产品"},{"label":"D","content":"丁公司在其开发的软件上采用了开源软件的模式，与用户联合升级软件"}],"answer":"B","explanation":"迭代开发的定义要点：①需求没有被完全确定；②不求完美但求不断发现新问题；③通过客户的不断反馈来完善产品。<br>A项，先推出原型产品，再结合需求添加组件，说明是根据客户需求不断完善产品，符合定义。<br>B项，遵循预先计划的需求、分析、设计、编码、测试的步骤顺序进行，成功开发出新产品，是直接将产品做到完善，不符合定义。<br>C项，产品推出5年之后才由测试版变为稳定的产品，说明5年间一直在不断改进、完善，符合定义。<br>D项，采用了开源软件的模板，与用户联合升级，说明是根据用户需求不断完善产品，符合定义。","no":29},{"id":"1718789647782","type":"single","material":"","stem":"惭愧是指一个人在日常生活中，由于对好的行为和圣贤的深入了解，内心产生一种以圣贤为榜样，以好的行为为准绳，并且拒绝不符合圣贤和好的言行的心理品格；当这种心理品格植根后，个人如果出现行为上的背离，内心就会产生一种良心自责感。<br>根据上述定义，下列属于惭愧的一项是：","options":[{"label":"A","content":"甲在寒冬季节将水洒在楼道，后来担心水冻成冰后给他人带来伤害，内心非常歉疚"},{"label":"B","content":"乙考试作弊，一直担心事情暴露后会遭到大家的谴责和批评，内心忐忑不安"},{"label":"C","content":"丙在背后说同学坏话，事后想起书中关于“真、善、美”的种种阐释，内心觉得很不安"},{"label":"D","content":"丁偶然听了某道德楷模的讲座，内心对该道德楷模产生了一种敬佩的感觉"}],"answer":"C","explanation":"惭愧的定义要点：①内心以圣贤为榜样，以好的行为为准绳；②如果出现行为上的背离内心会产生一种良心自责感。<br>A项，甲内心感到歉疚是担心给他人带来伤害，而不是背离了圣贤和好的言行，不符合定义。<br>B项，乙内心忐忑不安是因为怕事情暴露，而不是因为自己的行为违背以圣贤为榜样的准则产生了自责感，不符合定义。<br>C项，丙觉得自己在背后说同学坏话的行为，违背了“真、善、美”的阐释而感到不安，是因为自己的行为违背以圣贤为榜样的准则而产生良心自责感，符合定义。<br>D项，丁听了讲座后产生了敬佩的感觉，不涉及违背以圣贤为榜样的行为，不符合定义。","no":30},{"id":"1718789647783","type":"single","material":"","stem":"加害给付是指在履行合同的过程中，合同关系中的债务人所作出的履行行为不符合合同的规定，并且这种不适当履行行为造成了对债权人的履行利益以外的损害，这一损害包括人身损害或给付标的以外的其他财产损害。<br>根据上述定义，下列没有反映加害给付的是：","options":[{"label":"A","content":"甲公司与乙宾馆协议，约定在该宾馆举办答谢酒宴，结果在酒席中部分客人食用海鲜后出现了食物中毒的情况"},{"label":"B","content":"甲与乙一直有合作协议，2018年年初，甲将患有传染病的家禽卖给农场主乙，致使乙农场的其他家禽染病死亡"},{"label":"C","content":"甲电子商城与供货商乙签订采购协议，乙将有问题的充电宝供货给甲，一名消费者购买了甲商场的充电宝，使用时发生爆炸，一只手受伤"},{"label":"D","content":"甲水果店欲采购水果，于是与乙供货商签订合同，后发现乙送来的水果中部分已经腐烂，无法销售"}],"answer":"D","explanation":"加害给付的定义要点：①履行合同过程中；②债务人作出不符合合同规定的行为；③造成履行利益以外的损害。<br>A项，在酒席中部分客人食用海鲜后食物中毒，符合定义。<br>B项，甲将患有传染病的家禽卖乙，导致乙的其他家禽染病死亡，符合定义。<br>C项，乙将有问题的充电宝供货给甲，导致甲的消费者手受伤，符合定义。<br>D项，乙供货给甲部分腐烂的水果，是造成该产品本身无法销售，不涉及履行利益以外的损害，不符合要点③。","no":31},{"id":"1718789647784","type":"single","material":"","stem":"墙面色彩的确定，首先要考虑房间的朝向。南向和东向的房间，光照充足，墙面宜采用浅蓝、浅绿等冷色调；北向房间，墙面应以奶黄等暖色调为主。墙面的色彩对于家具起背景衬托作用，所以宜用浅色调。另外，宽敞的房间采用暖色装修，可以避免给人以空旷感；面积小的房间采用冷色装修，在视觉上让人感觉房间大一些。<br>下列最符合上述室内色彩设计基本原则的是：","options":[{"label":"A","content":"东向的小书房，墙面使用浅绿色"},{"label":"B","content":"西向的大客厅，墙面使用深蓝色"},{"label":"C","content":"南向的大餐厅，墙面使用浅蓝色"},{"label":"D","content":"北向的小卧室，墙面使用浅蓝色"}],"answer":"A","explanation":"室内色彩设计的基本原则：①东向和南向的房间宜采用浅蓝、浅绿等冷色调；②北向房间应以奶黄等暖色调为主；③宽敞的房间宜采用暖色调；④面积小的房间宜采用冷色调。<br>A项，东向的小书房，墙面使用浅绿色，符合原则①和④。<br>B项，西向的大客厅，墙面使用深蓝色，不符合原则③。<br>C项，南向的大餐厅，墙面使用浅蓝色，不符合原则③。<br>D项，北向的小卧室，墙面使用浅蓝色，不符合原则②。","no":32},{"id":"1718789647785","type":"single","material":"","stem":"众包是指公司或者机构把原来由员工执行的工作任务，以自愿的形式外包给非特定大众网络的一种合作模式。<br>根据上述定义，下列属于众包的是：","options":[{"label":"A","content":"以系统研发为核心竞争力的软件公司M,雇用了另一家网站开发实力较强的H公司，为自己公司进行网站架构"},{"label":"B","content":"美国芝加哥的某T恤公司拥有一个庞大的T恤爱好者网络社区，每天都会收到不同爱好者发来的大量交流信息"},{"label":"C","content":"某公司面向网络平台上的广大汽车爱好者募集合作者，专门为公司研发的一款新型概念车进行功能定义和命名"},{"label":"D","content":"高校教师小王为了参加一场业余模特大赛，通过微信联系了高中同学小丽，请她帮忙设计了一套漂亮的参赛服装"}],"answer":"C","explanation":"众包的定义要点：①公司或者机构；②原来由员工执行的工作任务；③自愿的形式外包给非特定大众网络。<br>A项，软件公司M雇用了H公司，不符合要点③。<br>B项，某T恤公司每天收到的交流信息，不符合要点②③。<br>C项，某公司(公司或机构)在网络平台上募集合作者(自愿的形式外包给非特定大众网络),为公司研发的概念车进行功能定义和命名(原来由员工执行的工作任务)。符合定义。<br>D项，高校教师小王，不符合要点①。","no":33},{"id":"1718789647786","type":"single","material":"","stem":"人为环境异常是指一定地域范围内，因人类行为造成自然环境的某个或多个环境要素发生显著变化，破坏生态系统的相对平衡关系的现象。<br>根据上述定义，下列属于人为环境异常的是：","options":[{"label":"A","content":"某地沿河工业园区近来订单大量增加，废水排放量也随之激增，结果造成河流下游的鱼虾大量死亡，沿岸庄稼成片枯死"},{"label":"B","content":"某地火山爆发喷出的有毒元素散落到地表，改变了土壤中原有化学成分，形成了高氟、高汞的土壤，影响了作物的生长"},{"label":"C","content":"某地地下贮藏着丰富的石油资源，近日附近村庄的井水变得浑浊，并伴有刺鼻气味，经检测含有大量重金属，不宜饮用"},{"label":"D","content":"某地因地震出现地表下陷，暴雨过后，部分区域严重积水，致使这些区域农田里的农作物、果园里的果树发生烂根枯萎"}],"answer":"A","explanation":"人为环境异常定义的关键信息：因人类行为造成自然环境显著变化。<br>A项，工业园区废水排放(人类行为),造成鱼虾死亡和庄稼枯死(自然环境显著变化),符合定义。<br>B项，火山喷发不属于人类行为，不符合定义。<br>C项，石油让水不宜饮用，不属于人类行为，不符合定义。<br>D项，地震不属于人类行为，不符合定义。","no":34},{"id":"1718789647787","type":"single","material":"","stem":"轻率概括，是指在没有积累足以进行概括的材料的情况下，只依据少数个例就草率地作出普遍性结论的一种逻辑错误。<br>根据上述定义，下列不属于轻率概括的是：","options":[{"label":"A","content":"做微商都很容易赚钱!我的一个亲戚，年初开始做微商，现在已经买车了"},{"label":"B","content":"为了与2000万精英作共同的选择，请赶快来购买我们的在线付费课程吧"},{"label":"C","content":"我的朋友说她的哲学课很难，我的哲学课也很难，可见哲学课必定都很难"},{"label":"D","content":"我几乎每天都吃汉堡，但是我的体重却没有变，所以吃汉堡不会导致肥胖"}],"answer":"B","explanation":"轻率概括定义的关键信息：只依据少数个例草率地作出普遍性结论。<br>A项，只根据一个亲戚的情况得出结论，符合定义。<br>B项，“与2000万精英作共同的选择”并不是只依据少数个例作出普遍性结论，不符合定义。<br>C项，只根据“我”和“我的朋友”两个人的情况做出结论，符合定义。<br>D项，只根据“我”做出结论，符合定义。","no":35},{"id":"1718789647788","type":"single","material":"","stem":"股权众筹是指创新创业者或小微企业通过股权众筹融资中介机构互联网平台(互联网网站或其他类似的电子媒介)公开募集股本的活动。<br>根据上述定义，下列属于股权众筹活动的是：","options":[{"label":"A","content":"做生意的杨某以1.5亿元入股邻居的创业项目，创立了一个网购平台"},{"label":"B","content":"某公司在地方股权交易市场挂牌后，宣布公司定向发行原始股，融资2亿元"},{"label":"C","content":"孔某通过自己制作的网站宣传推广某项目，成功吸引40余人投资，融资200余万元"},{"label":"D","content":"赵某通过熟人介绍在某网络创投平台出资20万元，获得创业企业5%的股权，成为该企业的股东"}],"answer":"D","explanation":"股权众筹定义的关键信息：创新创业者或小微企业通过众筹融资互联网平台公开募集股本。<br>A项，杨某入股邻居的创业项目，但未体现出邻居是否是通过互联网平台进行公开募集股本的，不符合定义。<br>B项，某公司在地方股权交易市场挂牌，并非通过互联网平台进行融资，不符合定义。<br>C项，孔某在自己的网站上宣传推广某项目，不属于通过众筹融资中介机构互联网平台，不符合定义。<br>D项，赵某通过某网络创投平台投资，获得创业企业的股本。对于创业企业来说，在网络创投平台公开募集股本属于股权众筹，符合定义。","no":36},{"id":"1718789647789","type":"single","material":"","stem":"无偿合同是指当事人一方只享有合同权利而不偿付任何代价的合同。换言之，该合同中的一方当事人向对方给予某种利益，而对方取得该利益时无须支付任何代价。<br>根据上述定义，下列不属于无偿合同的是：","options":[{"label":"A","content":"老王膝下无儿女，他将自己名下的一套房产赠予一直照顾自己的侄子，并与对方签订了赠予合同"},{"label":"B","content":"何某邀请李某来自己的公司任职，并与李某签订合同，承诺如果李某在公司工作满5年，将获得公司10%的股份"},{"label":"C","content":"黎某要出国学习半年，不愿将装修一新的住宅对外出租，遂与好友王某协商一致，将其住宅交与王某代为看管"},{"label":"D","content":"黄某将自己的车借给同事郑某使用，并与郑某签订协议，约定借给其使用一年，不需缴纳使用费，但要如期归还"}],"answer":"B","explanation":"无偿合同定义的关键信息：当事人一方只享有合同权利而不偿付任何代价的合同。<br>A项，老王签订了合同，将房产赠予侄子，侄子获得房子时无须支付任何代价，符合定。<br>B项，李某正常工作，公司是给予工资作为报酬的，要求满5年才能给获得10%的股份，李某在获得10%股份时需要付出工作满5年的代价，不符合定义。<br>C项，黎某与王某协商，事实上是一种口头的协议，交给王某看管事实上王某无偿获。得了居住等利益，符合定义。<br>D项，黄某与郑某签订协议，将自己的车借给郑某使用一年，郑某在获得车的使用权时无须支付任何代价，符合定义。","no":37},{"id":"1718789647790","type":"single","material":"","stem":"诉诸无知是指以对某个命题的无知为根据，从而断言该命题是真或者是假的一种谬误，其公式是：因为尚未证明A假，所以A是真的；或者因为尚未证明A真，所以A是假的。<br>根据上述定义，下列论证中犯了诉诸无知错误的是：","options":[{"label":"A","content":"既然圣经上说上帝是存在的，那么你就不能说上帝是不存在的"},{"label":"B","content":"既然现在没有充分的证据证明甲是有罪的，那么甲就可能是无罪的"},{"label":"C","content":"既然当时的绝大多数人都相信托勒密的地心说，那么托勒密的地心说就是正确的"},{"label":"D","content":"既然古代典籍未提到元明时期该地附近有寺院，那么就说明当时该地附近没有寺院"}],"answer":"D","explanation":"诉诸无知定义的关键信息：以对某个命题的无知为根据，断言该命题是真或者是假的一种谬误。<br>A项，圣经上说上帝是存在的，说明有证据证明上帝是存在的，不符合关键信息“命题的无知”,不符合定义。<br>B项，没有充分的证据证明甲有罪，符合“尚未证明A真”,但“甲可能是无罪的”,说明甲可能有罪也可能无罪，无法断定真假，不符合关键信息“断言该命题是真或假”,不符合定义。<br>C项，大多数人都相信地心说，是一种肯定的状态，不符合关键信息“以对某个命题的无知为根据”,不符合定义。<br>D项，“古代典籍未提到元明时期该地附近有寺院”符合“因为尚未证明A真”,“那么就说明当时该地附近没有寺院”也符合“所以A是假的”,符合定义。","no":38},{"id":"1718789647791","type":"single","material":"","stem":"心理学家马斯洛将人的需求像阶梯一样从低到高按层次分为五种，分别是：生理需求、安全需求、爱和归属需求、尊重需求和自我实现需求。其中，尊重需求属于较高层次的需求，表现为希望获得成就、名声、地位、晋升机会或获得他人对自己的认可与尊重等。<br>根据上述定义，下列行为中最能体现尊重需求的是：","options":[{"label":"A","content":"小王在工作之余和关系好的同事一起打羽毛球"},{"label":"B","content":"小张为了能养家糊口每天拼命地努力工作赚钱"},{"label":"C","content":"小李为自己和家人都购买了人身意外伤害保险"},{"label":"D","content":"小刘对自己被评为年度优秀员工感到非常开心"}],"answer":"D","explanation":"尊重需求定义的关键信息：属于较高层次的需求，希望获得成就、名声、地位、晋升机会或获得他人对自己的认可与尊重等。<br>A项，与关系好的同事一起打羽毛球，不属于较高层次的需求，不符合尊重需求定义。<br>B项，为养家糊口拼命赚钱，不属于较高层次的需求，不符合尊重需求定义。<br>C项，为自己和家人都购买了人身意外伤害保险，是对安全的需求，不符合尊重需求定义。<br>D项，被评为年度优秀员工是一种荣誉，符合尊重需求定义。","no":39},{"id":"1718789647792","type":"single","material":"","stem":"自由落体运动是指物体只在重力作用下从静止开始下落的运动，这种运动只有在真空条件下才能发生，在有空气时，如果空气的阻力作用比较小，可以忽略不计，则物体的下落可以近似看作自由落体运动。<br>根据上述定义，下列可以近似看作自由落体运动的是：","options":[{"label":"A","content":"熟透了的苹果从树上被风吹落"},{"label":"B","content":"飞行中的飞机被导弹击中坠落"},{"label":"C","content":"抛过来的皮球没被接住，掉在地上"},{"label":"D","content":"冬日中午，冰凌融化后从屋檐掉下"}],"answer":"D","explanation":"自由落体运动定义的关键信息：只在重力作用下从静止开始下落。<br>A项，苹果从树上被风吹落，说明不只受到了重力，还有风对苹果的作用力，不符合定义。<br>B项，飞行中的飞机，说明飞机并不是静止的，不符合定义。<br>C项，抛过来的皮球，说明不只受到了重力，不符合定义。<br>D项，冰凌在静止状态下仅受到重力掉下，符合定义。","no":40},{"id":"1718789647793","type":"single","material":"","stem":"沉默行为是指面对管理制度或生产活动等方面的隐患，为了避免人际冲突、害怕遭受打击报复或维护自身脸面等原因而有意保留自己想法的行为。<br>根据上述定义，下列属于沉默行为的是：","options":[{"label":"A","content":"小王看到同事小赵的计划书有个明显的错误而没有指出来，在接下来与小赵的评比中小王的计划方案获得通过"},{"label":"B","content":"小刘尽管在新产品开发报告会上有想法，但考虑到该想法尚不成熟，贸然提出可能会影响工作进度，因此在会上也就没有发表意见"},{"label":"C","content":"尽管小马就如何提高顾客对公司服务的满意度有见解，但由于前面发言的同事已经基本谈到了该问题，所以，小马也就没再接着说"},{"label":"D","content":"老张意识到小明最近老是上班时间唱歌已经影响到了别人工作，但考虑到他是自己的徒弟，老张不但不向领导报告，还和其他抱怨的同事争辩"}],"answer":"B","explanation":"沉默行为的定义要点：①面对管理制度或生产活动等方面的隐患；<br>②为避免人际冲突，害怕打击报复，维护自身脸面等；③有意保留自己想法。<br>A项，不指出问题是为了自己获胜，不符合要点②。<br>B项，贸然提出可能会影响工作进度，是出于避免人际冲突，害怕遭受打击报复或维护自身脸面的目的，符合定义。<br>C项，不提出见解是因为有同事已经说过，不符合要点②。<br>D项，上班时间唱歌不属于管理制度或生产活动方面的隐患，且老张为自己的徒弟和其他同事争辩，没有保留自己的想法，不符合要点①③。","no":41},{"id":"1718789647794","type":"single","material":"","stem":"逆向激励是指政策设计初衷与实际执行效果呈现“事与愿违”的现象，逆向激励效应一旦被激发，不仅会导致现状恶化，损害政策制定者的信用，还将进一步强化相关负面后果，最终造成恶性循环。<br>根据上述定义，下列不属于逆向激励的是：","options":[{"label":"A","content":"为了扭转治安问题，20世纪美国颁布了禁酒令，然而酒的销量不跌反升，而且由此又引发了新的犯罪问题"},{"label":"B","content":"宋神宗为了整肃吏治、严明司法审判，下令凡是能找到错判事实的官员官升一级，结果这项举措却成了新旧官员相互攻讦的武器"},{"label":"C","content":"为了更有利孩子成长而提供优裕的物质条件，却让孩子养成了好逸恶劳的恶习"},{"label":"D","content":"老师在课堂上通过对害羞学生有意地提问而帮助其克服容易紧张的问题"}],"answer":"D","explanation":"逆向激励的定义要点：①政策设计初衷与实际执行效果呈现“事与愿违”的现象；②会导致现状恶化，损害政策制定者的信用，还将进一步强化相关负面后果，最终造成恶性循环。<br>A项，颁布禁酒令，初衷是减少酒的销量，提高治安，结果酒的销量增加，引发新犯罪，符合定义。<br>B项，下令找错的初衷是整肃吏治，严明司法审判，结果却导致官员间相互攻讦，符合定义。<br>C项，提供优裕的物质条件，初衷是帮助孩子成长，结果却养成了好逸恶劳的恶习，符合定义。<br>D项，老师帮助学生克服容易紧张的问题，没有提到学生的结果，不符合要点②。","no":42},{"id":"1718789647795","type":"single","material":"","stem":"感情管理是指管理者通过自身的形象、行为、情感来调动职工积极性的一种管理方法。<br>根据上述定义，下列不属于感情管理的是：","options":[{"label":"A","content":"车间主任从来不回避脏活、累活，总是带头干"},{"label":"B","content":"尽管李经理喜欢抽烟，但他从不在员工面前抽"},{"label":"C","content":"每逢节假日，公司领导都会给员工发放节日慰问品"},{"label":"D","content":"部门经理与员工一起聊天、吃饭，让大家畅所欲言"}],"answer":"B","explanation":"感情管理定义的关键信息：管理者通过自身形象、行为、情感来调动职工积极性。<br>A项，车间主任带头干脏活累活是通过自身行为来调动职工积极性，符合定义。<br>B项，李经理从不在员工面前抽烟，只是为了维护自身的形象，没有涉及调动职工积极性，不符合定义。<br>C项，领导发放慰问品是通过情感来调动职工积极性，符合定义。<br>D项，部门经理经常与员工一起聊天吃饭是通过情感来调动职工积极性，符合定义。","no":43},{"id":"1718789647796","type":"single","material":"","stem":"“城乡污染转移”是指在经济发展过程中，组织或个人将造成环境污染的设备、工艺、技术、产品以及其他有形或无形的污染物质，由城市转移至农村的行为。“城乡污染转移”已成为农村环境形势日益严峻的主要原因之一。<br>根据上述定义，下列不属于“城乡污染转移”的是：","options":[{"label":"A","content":"某市水泥厂每年有10万吨未经处理的工业废水流经附近乡村的河流"},{"label":"B","content":"某镇的耕地受城区搬迁过来的工厂产生的重金属残渣污染达20公顷"},{"label":"C","content":"为打造绿色文明城市形象，某城市将重污染的钢铁厂迁至附近的乡镇"},{"label":"D","content":"某市为保证城区用水修建水库，致使下游许多村庄农田灌溉用水不足"}],"answer":"D","explanation":"城乡污染转移的定义要点：①组织或个人将造成环境污染的设备、工艺、技术、产品以及其他有形或无形的污染物质，由城市转移至农村的行为；②成为农村环境形势日益严峻的主要原因之一。<br>A项，某市水泥厂10万吨未经处理的工业废水流经附近乡村的河流，符合定义。<br>B项，某镇受城区搬迁过来的工厂产生的重金属残渣污染的耕地达20公顷，符合定义。<br>C项，某城市将重污染的钢铁厂迁至附近的乡镇，符合定义。<br>D项，修建水库导致下游许多村庄农田灌溉用水不足，并没有涉及环境污染，不符合要点①②。","no":44},{"id":"1718789647797","type":"single","material":"","stem":"人类增强就是利用生物医学技术、智能技术、神经科学技术、信息技术和纳米技术等高新技术手段使健康人类的机体功能或能力超出其正常范围，从而使人类的体貌、寿命、人格、认知和行为等能力发生根本性变化并具有全新能力的一种技术手段，其目的是显著提高人类生活的质量。<br>根据上述定义，下列选项不属于人类增强的是：","options":[{"label":"A","content":"演员赵某用药剂延缓衰老"},{"label":"B","content":"医生建议老张去做心脏搭桥手术"},{"label":"C","content":"医生将传感器植入老陈大脑提高其记忆力"},{"label":"D","content":"小王为了增加自己的身高服用类增高药物"}],"answer":"B","explanation":"人类增强的定义要点：①利用生物医学技术、智能技术、神经科学技术、信息技术和纳米技术等高新技术手段使健康人类的机体功能或能力超出其正常范围；②人类的体貌、寿命、人格、认知和行为等能力发生根本性变化并具有全新能力；③目的是显著提高人类生活的质量。<br>A项，延缓衰老是使寿命发生变化，符合定义。<br>B项，医生建议老张去做心脏搭桥手术，说明老张原本身体不健康，手术后也不会超出机体功能正常范围，不符合要点①。<br>C项，提高记忆力是使认知能力发生变化，符合定义。<br>D项，增加身高是使体貌发生变化，符合定义。","no":45},{"id":"1718789647798","type":"single","material":"","stem":"共享经济是指借助网络第三方平台，基于闲置资源使用权的暂时性转移，实现生产要素的社会化，提高存量资产的使用效率以创造更多价值，促进社会经济的可持续发展。<br>根据上述定义，下列经济活动不属于共享经济的是：","options":[{"label":"A","content":"王某从某网络平台订车去飞机场，方便快捷"},{"label":"B","content":"李某从某网络平台贷款炒股，获得了预期收益"},{"label":"C","content":"马某旅行前从某网络平台预订民宿，抵达后入住"},{"label":"D","content":"张某从某网络平台购买外卖美食，在家享受美味"}],"answer":"D","explanation":"共享经济的定义要点：①借助网络第三方平台；②闲置资源使用权暂时转移；③提高使用效率。<br>A项，网上订车，车辆的使用权只是暂时转移给王某，属于基于闲置资源使用权的暂时性转移，符合定义。<br>B项，网上贷款炒股，所使用炒股资金是借贷而来，李某只是暂时拥有使用权，属于基于闲置资源使用权的暂时性转移，符合定义。<br>C项，网上预订民宿，所订房间的使用权只是暂时转移给马某，属于基于闲置资源使用权的暂时性转移，符合定义。<br>D项，网上购买外卖，美食不是闲置资源，也不是暂时性拥有使用权，不符合要点②。","no":46},{"id":"1718789647799","type":"single","material":"","stem":"随着科学技术的发展，人机交流已经成为现实，这其中的关键是脑机接口技术。所谓脑机接口，就是连接大脑与计算机之间的信息系统，可让大脑直接和计算机沟通。脑机接口可以从大脑传递信息到计算机，又可以从计算机传递信息进入大脑。<br>根据上述定义，下列应用不属于脑机接口技术的是：","options":[{"label":"A","content":"某游戏玩家的大脑植入一部装置，通过该装置用意念控制机械手，端起杯子喝茶"},{"label":"B","content":"某游戏玩家佩戴一套义肢设备，经过多次练习，凭着坚强意志力，实现独立行走"},{"label":"C","content":"某游戏玩家佩戴一种脸部饰品，饰品根据佩戴者的情绪变化做出相应的指示<br>运作"},{"label":"D","content":"某游戏玩家戴上一套高科技耳机，集中注意力，通过精神控制小球飞越各种障碍"}],"answer":"B","explanation":"脑机接口技术定义的关键信息：让大脑直接和计算机沟通。<br>A项，用意念控制机械手，端起杯子喝茶，属于大脑直接和计算机沟通，符合定义。B项，佩戴义肢设备实现行走，不涉及大脑直接和计算机沟通，不符合定义。<br>C项，饰品根据佩戴者情绪变化作出相应动作，属于大脑直接和计算机沟通，符合定义。<br>D项，通过精神控制小球躲避障碍，属于大脑直接和计算机沟通，符合定义。","no":47},{"id":"1718789647800","type":"single","material":"","stem":"非爱行为，指以爱的名义，对自己亲近的人进行非爱性的掠夺，即违背他人主观意愿，在精神与行为方面强制控制，迫使对方按照施控者的意愿去行为做事，这一行为往往发生在夫妻、恋人、父母与子女等最亲近的人之间。<br>根据上述定义，下列属于非爱行为的是：","options":[{"label":"A","content":"张某按照医嘱，要求女儿每三个小时做一次牵引，以消除疼痛"},{"label":"B","content":"林某强迫儿子每天练琴3小时，争取在钢琴大赛中取得好成绩"},{"label":"C","content":"陈某为防止患精神病的女儿逃逸，将其关在地下室禁止其出入"},{"label":"D","content":"李某按照轮流陪护协议，要求妻子前往医院陪护患重病的母亲"}],"answer":"B","explanation":"非爱行为的定义要点：①违背他人主观意愿；②在精神与行为方面强制控制，迫使对方按照施控者的意愿去行为做事。<br>A项，医嘱不是“施控者的意愿”,且要求女儿做牵引消除疼痛不是进行非爱性的掠夺，不符合要点②。<br>B项，林某强迫儿子每天练琴3小时，违背了儿子的意愿，按照自己的意愿让儿子去做某事，符合定义。<br>C项，患精神病的女儿意愿不明显，无法判断是否违背了她的意愿，不符合要点①。<br>D项，李某按照协议要求妻子，不属于违背妻子主观意愿，不符合要点①。","no":48},{"id":"1718789647801","type":"single","material":"","stem":"谶纬之学即对未来的一种政治预言，谶纬之学本身并不是科学的，但受现实条件的局限，常被人们利用。<br>根据上述定义，下列利用了谶纬之学的是：","options":[{"label":"A","content":"大泽乡起义前，吴广在深夜模仿狐狸的声音大喊“大楚兴，陈胜王”"},{"label":"B","content":"汉武帝在位期间拓西域，逼匈奴，史学家们将“武”字巧妙地诠释为“止戈为武”,以此来称赞他为华夏赢得平稳发展时间的历史功绩"},{"label":"C","content":"国外一些不法分子编写预言某时某地将发生地质灾难的藏头诗并发布在网络，以达到扰乱民心的效果"},{"label":"D","content":"某位老人在家中财物被盗之后将自己的遭遇告诉了老李，老李看了老人手相后表示他还有大难，需要破财才能化解"}],"answer":"A","explanation":"谶纬之学的定义要点：①一种不是科学的政治预言；②常被人们利用。<br>A项，吴广在深夜模仿狐狸的声音大喊“大楚兴，陈胜王”,属于对未来的政治预言，这句话由“狐狸”喊出是不科学的，但受当时现实条件的局限，被陈胜、吴广所利用，符合定义。<br>B项，史学家对汉武帝历史功绩的称赞，并不是政治预言，不符合要点①。<br>C项，不法分子的散播灾害谣言，不是政治预言，不符合要点①。<br>D项，老李看了老人手相后表示他还有大难，需要破财才能化解，属于算命，不是政治预言，不符合要点①。","no":49},{"id":"1718789647802","type":"single","material":"","stem":"反串是指中国传统戏曲中演员演出与自身本工行当不同的戏的情形。<br>根据上述定义，下列属于反串的是：","options":[{"label":"A","content":"“魔音王子”石头同时用男声和女声表演对唱歌曲《纤夫的爱》"},{"label":"B","content":"《星光大道》中李玉刚男扮女装演唱《新贵妃醉酒》"},{"label":"C","content":"成龙在电影《双龙会》中同时分演玩命和马友两个角色"},{"label":"D","content":"旦行演员梅兰芳在《辕门射戟》一剧中演生角吕布"}],"answer":"D","explanation":"反串的定义要点：①中国传统戏曲；②演出与自身本工行当不同的戏。<br>A项，对唱歌曲《纤夫的爱》不是中国戏曲，不符合要点①。<br>B项，《新贵妃醉酒》是歌曲，不是中国戏曲，不符合要点①。<br>C项，电影《双龙会》不是中国戏曲，不符合要点①。<br>D项，原来是旦行的梅兰芳在京剧《辕门射戟》中演生角，属于反串。","no":50},{"id":"1718789647803","type":"single","material":"","stem":"具有上位心理的人因处在比别人高的层次而有某种优势感，具有下位心理的人因处在比别人低的层次而有某种自卑感，这种情况被称为位差效应。<br>根据上述定义，下列情形属于位差效应的是：","options":[{"label":"A","content":"小明考试作弊被发现，在老师面前羞愧得抬不起头"},{"label":"B","content":"小赵每次向领导汇报工作时都提心吊胆，以致言不由衷"},{"label":"C","content":"某公司老总喜欢“听喜不听忧”,公司里“报喜”的人多被提拔"},{"label":"D","content":"连长命令士兵在大雨中跑十圈，不跑完不准吃饭"}],"answer":"B","explanation":"位差效应的定义要点：①高位者有优越感；②低位者有自卑感。A项，小明作弊被发现，与地位无关，不符合要点①②。<br>B项，小赵因处在比领导低的层次而有自卑感，使得汇报时言不由衷，符合定义。<br>C项，公司里“报喜”的人多被提拔，没有体现出优越感或者自卑感，不符合要点<br>①②。<br>D项，连长命令士兵在大雨中跑十圈，没有体现出优越感或者自卑感，不符合要点①②。","no":51},{"id":"1718789647804","type":"single","material":"","stem":"比量是指以已有的经验或知识为参照而进行逻辑推理得出的认识结果。由于其作为参照基础的知识或是经验和逻辑推理都具有无误性，所以这样的认识结果也就真实可靠。<br>根据以上定义，下列不属于比量的是：","options":[{"label":"A","content":"甲游玩到山林深处，看到一名僧人在山涧边挑水，身后是茫茫的丛林，从而知道林中有寺庙"},{"label":"B","content":"乙看到远处露天的舞台上冒烟，而知道舞台上起火了"},{"label":"C","content":"丙早上起来，透过窗户看见空旷平地上草木摇动，而知道外面在刮风"},{"label":"D","content":"丁看到一户人家生了一个男孩，非常开心，但是他知道，这孩子将来是要死的"}],"answer":"D","explanation":"比量的定义要点：①以已有的经验或知识为参照；②进行逻辑推理得出的认识结果。<br>A项，通过看到僧人挑水，推理出林中有寺庙，符合定义。<br>B项，通过看到舞台冒烟，推理出舞台上起火，符合定义。<br>C项，通过看到草木摇动，推理出外面在刮风，符合定义。<br>D项，丁知道这孩子将来是要死的，是因为人都会死，不需进行推理即可知道，不符合要点②。","no":52},{"id":"1718789647805","type":"single","material":"","stem":"内卷化效应，指的是个体长期从事一项相同的工作，并且保持在一定的层面上，只是进行自我重复，没有任何变化和改观。<br>根据上述定义，以下符合内卷化效应的是：","options":[{"label":"A","content":"小李大学毕业后三年换了五份工作，每次刚熟悉工作就离职，下次重新开始"},{"label":"B","content":"钱老师在图书馆工作十几年，虽然经常有研究成果发表，但一直没有升职"},{"label":"C","content":"老杨已经在城里打工二十余年，长期在某公司做保安，一直没有什么改变"},{"label":"D","content":"刘阿姨说丈夫张先生性格固执，一起经过了几十年，张先生都没有什么改善"}],"answer":"C","explanation":"内卷化效应的定义要点：①长期从事一项相同的工作；②保持在一定的层面上；③只进行自我重复；④没有任何变化和改观。<br>A项，“三年换了五份工作”并非长期从事一项相同的工作，不符合要点①。<br>B项，“经常有研究成果发表”说明并非止步不前、自我重复，不符合要点②③。<br>C项，二十余年一直做保安，没有变化，符合定义。<br>D项，说的是性格方面，没有提到工作，不符合要点①。","no":53},{"id":"1718789647806","type":"single","material":"","stem":"互动式教学，就是通过营造多边互动的教学环境，在教学双方平等交流探讨的过程中，达到不同观点碰撞交融，进而激发教学双方的主动性和探索性，从而提高教学效果的一种教学方式。<br>根据上述定义，以下属于互动式教学的是：","options":[{"label":"A","content":"某学院通过文化讲座向外国留学生介绍儒家思想"},{"label":"B","content":"王老师带领教育专业的学生进行课堂教学模拟实验"},{"label":"C","content":"小王觉得自己英语不好，报名参加课外一对一辅导"},{"label":"D","content":"学生和老师就某一个问题展开课堂辩论"}],"answer":"D","explanation":"互动式教学定义的关键信息：教学双方平等交流探讨的过程。<br>A项，讲座属于单方面介绍，并非教学双方互相探讨，不符合定义。<br>B项，进行课堂教学模拟实验，并未体现双方平等交流探讨，不符合定义。<br>C项，报名一对一辅导，显然是学习的过程，并不存在双方平等交流探讨，不符合定义。<br>D项，学生和老师展开课堂辩论，体现了教学双方平等交流探讨，符合定义。","no":54},{"id":"1718789647807","type":"single","material":"","stem":"闪光灯效应是心理学的一个术语，也称闪光灯记忆，是指个人对令人震撼的事件容易留下深刻而准确的记忆，并且记忆的准确性不随时间的推移而减弱的现象。闪光灯记忆所记之事件，多半是与个人有关的重要事件。<br>根据上述定义，以下属于闪光灯效应的是：","options":[{"label":"A","content":"冯雨在心情愉快时阅读课文，对课文内容印象格外深刻"},{"label":"B","content":"经历汶川地震而幸存的小王，八年之后，对当时的情景仍记忆犹新"},{"label":"C","content":"高阳小时候上学走过的路，在时隔40年之后返乡之时仍能准确辨认"},{"label":"D","content":"失联30年的战友重新团聚，许多当年的生活琐事还历历在目"}],"answer":"B","explanation":"闪光灯效应的定义要点：①令人震撼的事件；②与个人有关的重要事件。<br>A项，心情愉快时阅读课文印象深刻，并不是令人震撼的事件，不符合要点①。<br>B项，汶川地震是令人震撼的事件，也是与小王有关的重要事件，符合定义。<br>C项，小时候上学走过的路，并不是令人震撼的事件，不符合要点①。<br>D项，当年的生活琐事，不符合要点①②。","no":55},{"id":"1718789647808","type":"single","material":"","stem":"艺术衍生品，是艺术作品衍生而来的艺术与商品的结合体，具备一定的艺术附加值。其包括经艺术家亲笔签名且限量发行的专供收藏和欣赏的书籍等，印有艺术家代表作品的文具、生活用品、服装服饰以及与艺术元素相结合的具有收藏价值的产品等。<br>根据上述定义，以下不属于艺术衍生品的是：","options":[{"label":"A","content":"著名绘画大师齐白石绘画作品集"},{"label":"B","content":"著名钢琴演奏家郎朗签名的CD"},{"label":"C","content":"冰心先生生前写作使用的钢笔"},{"label":"D","content":"以徐悲鸿著名画作为图案的金银纪念币"}],"answer":"C","explanation":"艺术衍生品定义的关键信息：由艺术作品衍生而来的艺术与商品的结合体。<br>A项，齐白石绘画作品集，是艺术与商品的结合体，属于艺术衍生品，排除。<br>B项，郎朗签名的CD,是经艺术家亲笔签名且限量发行的专供收藏和欣赏的产品，属于艺术衍生品，排除。<br>C项，冰心先生生前使用的钢笔本身一开始就不属于艺术品，也就不是由艺术品衍生而来的，因此不会成为艺术衍生品，不符合定义。<br>D项，以徐悲鸿著名画作为图案的纪念币，是印有艺术家代表作品的具有收藏价值的产品，属于艺术衍生品，排除。","no":56},{"id":"1718789647809","type":"single","material":"","stem":"短命政策指地方政府制定的事关群众权益却无法得到社会公众认可或受到普遍反对，一出台很快就被迫终止的政策措施。<br>根据上述定义，下列不属于短命政策的是：","options":[{"label":"A","content":"某市交管部门出台“闯黄灯视为违反交通规则，记6分政策”,在社会上引起了强烈反响，5天后该部门举行发布会宣布“不予执行”"},{"label":"B","content":"某市推出购房新政策：毕业未满5年的高中毕业生在市区购房实行“零首付”,因为不符合有关政策，几天后就被上级叫停"},{"label":"C","content":"南方某市推出在市区范围内的“禁摩令”后，大批人员集体离职，摩的司机纷纷上访，很快，这一政策被宣布“暂停执行”"},{"label":"D","content":"北方某市交通局宣布某风景优美的县级公路设卡收费，消息传出后，舆论一片哗然，没到月底，这一收费政策就寿终正寝"}],"answer":"B","explanation":"短命政策的定义要点：①无法得到社会公众认可或受到普遍反对；②一出台很快被终止。<br>A项，某市交管部门出台的这一规定无法得到社会公众认可，5天后宣布“不予执行”,即很快被终止。符合题干定义，排除。<br>B项，被叫停是因为不符合有关政策，并没有体现公众不认可或反对，不符合要点①。<br>C项，某市出台的规定受到公众普遍反对，并很快被终止。符合题干定义，排除。<br>D项，某市交通局出台的规定无法得到社会公众的认可，受到普遍反对，不到一个月就寿终正寝，即很快被终止。符合题干定义，排除。","no":57},{"id":"1718789647810","type":"single","material":"","stem":"斜杠青年指不满足于从事单一职业，追求拥有多重职业身份及多元生活方式的年轻人。他们在自我介绍时往往喜欢用斜杠来区分自己的不同身份，如：张三，金牌律师/企划师/专栏作家。<br>根据上述定义，下列属于斜杠青年的是：","options":[{"label":"A","content":"最近两三年，80后导演黄某某先后出演了10多次男配角，去年在一个著名的国际电影节上斩获了最佳男配角奖"},{"label":"B","content":"小丁在国外获得博士学位后，任职于国内一所著名高校，因科研成就突出，被破格聘为教授，并入选省“双百”人才计划"},{"label":"C","content":"某公司程序员小陈爱好广泛，性格温和，人际关系融洽，节假日常邀上三五个好友一起登山、打球、游泳"},{"label":"D","content":"李总做过保安，送过快递，当过安装工，开过小杂货店，他经常自豪地向员工讲述自己30多年来丰富的职业经历"}],"answer":"A","explanation":"斜杠青年定义的关键信息：追求拥有多重职业身份及多元生活方式。<br>A项，黄某某拥有导演和演员的双重身份，符合定义。<br>B项，小丁的身份是教授，“双百”人才计划并不是职业身份，不符合“拥有多重职业身份”这一关键信息，排除。<br>C项，小陈的身份是程序员，并没有“拥有多重身份”,爱好广泛也并非“多元生活方式”,不符合定义，排除。<br>D项，李总只是有许多职业经历，现在只有老总这一个身份，不符合“拥有多重职业身份”这一关键信息，排除。","no":58},{"id":"1718789647811","type":"single","material":"","stem":"权力暗示指基于职务地位、业务能力、人格魅力而产生的对组织机构外部成员的影响力。<br>根据上述定义，下列不属于权力暗示的是：","options":[{"label":"A","content":"张教授是微电子领域的专家，不少企业遇到相关问题，都会向他请教解决的方法"},{"label":"B","content":"五年级的小聪，电子游戏玩得特别顺溜，学校组织参加各级比赛时总请他协助指导"},{"label":"C","content":"退伍军人老赵处事公平，街坊邻居遇到大小纠纷，首先想到的就是请他上来主持公道"},{"label":"D","content":"教育局李主任长期研究教师的专业发展，亲友们常常向他求教孩子的教育问题"}],"answer":"B","explanation":"权力暗示定义的关键信息：对组织外部成员的影响力。<br>A项，张教授基于业务能力对企业有影响力，企业对于张教授所在的学校而言是组织机构外部成员，属于权力暗示，排除。<br>B项，学校组织参赛请小聪协助指导，学校对于小聪而言并非组织机构外部成员，不符合定义。<br>C项，老赵基于人格魅力对街坊邻居有影响力，街坊邻居对于军人而言是组织机构外部成员，属于权力暗示，排除。<br>D项，李主任基于职务地位对亲友们有影响力，亲友们对于李主任所在的教育局而言是组织机构外部成员，属于权力暗示，排除。","no":59},{"id":"1718789647812","type":"single","material":"","stem":"渐进式退休指员工到了法定退休年龄，用人单位根据实际工作需要对部分人员灵活确定退休时间。<br>根据上述定义，下列属于渐进式退休的是：","options":[{"label":"A","content":"马教授临近退休年龄，因为他是国内最具影响力的学者之一，对学科发展做出了重大贡献，学校决定聘任他为终身教授"},{"label":"B","content":"赵先生已经到了退休年龄，但是他主持的重大攻关项目还没有结题，他所在的研究所决定聘用他继续工作，直到项目完成"},{"label":"C","content":"近年来，李工程师的身体状况越来越糟糕，还患上了轻度的抑郁症，无法坚持工作，公司领导经过研究，决定让他提前退休"},{"label":"D","content":"某研究机构决定，从下半年开始，本单位申请提前退休的职工，初级、中级职称不低于54岁，高级职称不低于58岁"}],"answer":"B","explanation":"渐进式退休的定义要点：①到了法定退休年龄；②根据工作需要灵活确定退休时间。<br>A项，马教授临近退休年龄，说明并没有到法定退休年龄，不符合要点①;被聘为终身教授，指的是聘期可以延续到退休，没有被解聘的压力，并非灵活确定退休时间，不符合要点②。<br>B项，赵先生已经到了退休年龄，符合要点①;研究所根据工作需要继续聘用他直到项目完成，符合要点②。<br>C项，李工程师提前退休，说明并没有到法定退休年龄，不符合要点①。<br>D项，说的是单位中申请提前退休的年龄要求，不符合定义。","no":60},{"id":"1718789647813","type":"single","material":"","stem":"创伤后成长指一个人在经历重大的生活挫折之后发生的积极性改变。<br>根据上述定义，下列属于创伤后成长的是：","options":[{"label":"A","content":"一名车祸幸存者说，事故之后她能更主动地掌控自己的生活"},{"label":"B","content":"在多次丢失手机以后，小张照看自己的随身物品比以前细心多了"},{"label":"C","content":"在同事突然撒手人寰后，小刘深感生命脆弱，开始坚持健身锻炼"},{"label":"D","content":"赴震区考察归来后，王工程师对建筑物防震设计有了更深刻的认识"}],"answer":"A","explanation":"创伤后成长的定义要点：①经历重大生活挫折；②积极性的改变。<br>A项，发生车祸事故，是经历重大生活挫折，符合要点①;事故后更主动地掌控生活，是积极性的改变，符合要点②。<br>B项，丢手机并非重大生活挫折，不符合要点①。<br>C项，同事突然撒手人寰，并非小刘自己经受重大生活挫折，不符合要点①。<br>D项，赴震区考察并非重大生活挫折，不符合要点①。","no":61},{"id":"1718789647814","type":"single","material":"","stem":"劳动碰瓷指个别劳动者利用企业的管理漏洞，促使企业发生违法行为，进而索要双倍工资或经济补偿等经济利益。<br>根据上述定义，下列属于劳动碰瓷的是：","options":[{"label":"A","content":"林某应聘到某公司后，以种种借口未与公司签订劳动合同。三个月后，林某以公司拒绝与他订立劳动合同为由向劳动仲裁部门提出申请，要求公司赔偿未签订合同期间的双倍工资"},{"label":"B","content":"工作满一年后，丁女士发现公司没有为她交纳养老保险，经过多次交涉都没有得到满意的结果，她向劳动仲裁部门提出申请，要求公司为她补交养老保险"},{"label":"C","content":"洪女士生下二胎后，厂里把她怀孕期间的工资扣掉了一半，并劝她辞职，洪女士最终决定告上法庭，要求厂里补足她的工资奖金，并给予赔偿"},{"label":"D","content":"某公司招聘的10余名工人均未签订书面劳动合同，因为不断要求增加工资被集体辞退，几天后，他们以公司拒签劳动合同，过错在先为由申请劳动仲裁，要求同意他们回公司继续工作"}],"answer":"A","explanation":"劳动碰瓷的定义要点：①利用企业的管理漏洞；②促使企业发生违法行为；③索要双倍工资或经济补偿等经济利益。<br>A项，找借口不与公司签订劳动合同，促使企业发生违法行为，并要求公司赔偿未签订合同期间的双倍工资，符合定义。<br>B项，公司没有为员工交纳养老保险，是公司本身的违法行为，并非员工利用企业管<br>理漏洞促使企业发生违法行为，不符合要点①②。<br>C项，公司扣掉员工怀孕期间的一半工资，是公司本身的违法行为，并非员工利用企业管理漏洞促使企业发生违法行为，不符合要点①②。<br>D项，公司与招聘的工人未签订书面劳动合同，是公司本身的违法行为，并非员工利用企业管理漏洞，不符合要点①②;工人申请仲裁要求回公司继续工作，而非索要经济利益，不符合要点③。","no":62},{"id":"1718789647815","type":"single","material":"","stem":"错峰就业指大学毕业生在求职高峰时，主动选择短时间游学、实习、创业考察或志愿服务，推迟个人就业，以寻找更合适的就业岗位。<br>根据上述定义，下列属于错峰就业的是：","options":[{"label":"A","content":"小林大学毕业时正碰上“史上最难的就业季”,他没有急着找工作，而是到多个非营利性社团、咖啡厅体验生活。半年后与两个志同道合的朋友创办了一家科技咨询公司"},{"label":"B","content":"小高毕业后一直没有找到合适工作，每次有人问起工作的事情，他一点也不着急，心里盘算着再过几年，自己设法开个网店，照样能够过上舒舒服服的小日子"},{"label":"C","content":"虽然已被推荐保研，但考虑到家中久病的父亲和尚在读书的弟弟，小李还是到人才市场投递了简历。在等待消息的过程中，她又到老家附近的餐馆找了一份零工"},{"label":"D","content":"又到毕业季，与忙着投简历的其他同学不同，小金大二时就创办了一家共享办公租赁服务公司，只等一毕业，就可以全身心地投入到公司的经营管理上"}],"answer":"A","explanation":"错峰就业的定义要点：①主动选择短时间游学、实习等，推迟个人就业；②寻找更合适的就业岗位。<br>A项，大学毕业时没有急着找工作，选择体验生活推迟就业，半年后与朋友创办公司，符合定义。<br>B项，小高并没有选择短时间游学、实习等来推迟个人就业，不符合要点①;也没有寻找更适合的就业岗位，不符合要点②。<br>C项，小李并没有推迟个人就业以寻找更合适的就业岗位，不符合要点①②。<br>D项，小金并没有推迟个人就业以寻找更合适的就业岗位，不符合要点①②。","no":63},{"id":"1718789647816","type":"single","material":"","stem":"新乡贤指长期扎根农村，利用自己的知识、技术、财富为村民热心服务并做出突出贡献，在当地社会生活及民众心目中具有较高威望和影响力的乡村人士。<br>根据上述定义，下列属于新乡贤的是：","options":[{"label":"A","content":"10多年来，老李虽然一直在外经商，但他时时惦念着家乡，每年都会捐出大量资金为家乡修桥铺路，资助家乡的特困大学生完成学业，乡亲们经常千里迢迢地跑来看望他"},{"label":"B","content":"小张复员后回到家乡，两三年就成了远近闻名的“养殖大王”,为了带动乡亲们共同致富，他开办了多期培训班，免费传授实用养殖技术和经验，受到了大家的称赞"},{"label":"C","content":"20多年来，某市商会会长孙先生利用自己长期积累的丰富经验，为经营各种农副产品的家乡村民牵线搭桥，指导他们寻找商机，被乡亲们誉为贴心的“诸葛亮”"},{"label":"D","content":"某乡村小学校长程某退休后，利用自己学生多、关系广的优势，为挖掘家乡历史文化资源、发展乡村文化旅游业积极谋划、东奔西走，被乡亲们传为佳话"}],"answer":"D","explanation":"新乡贤的定义要点：①长期扎根农村；②做出突出贡献；③乡村人士。<br>A项，老李一直在外经商，并非长期扎根农村的乡村人士，不符合要点①③。<br>B项，小张复员才两三年，并非长期扎根农村，不符合要点①。<br>C项，孙先生是某市商会会长，并非长期扎根农村的乡村人士，不符合要点①③。<br>D项，程某从乡村小学校长的位置上退休，说明他是长期扎根农村的乡村人士，符合要点①③;他为家乡的发展东奔西走，做出突出贡献，符合要点②。","no":64},{"id":"1718789647817","type":"single","material":"","stem":"咕咚效应，指由于谣言传播而导致的集体无意识恐慌蔓延的现象，源自童话《咕咚来了》,讲述木瓜落进湖中后响起的“咕咚”声在动物中以讹传讹引发恐慌的故事。<br>根据上述定义，下列属于咕咚效应的是：","options":[{"label":"A","content":"某市去年房价暴涨，老李看到自己辛苦上班多年还不如别人买一套房一转手赚得多，担心房价继续飙涨，对自己的资产贬值感到恐慌，认为买房可以增值保值，于是忍不住加入抢房的行列"},{"label":"B","content":"英国脱欧公投结果出来后，由于担心一旦脱欧后在英国的金融机构会无法再获得欧盟的“单一护照”,在伦敦设立欧洲总部的银行纷纷计划撤离，不少外资银行开始准备迁往巴黎、法兰克福、柏林等地"},{"label":"C","content":"某网络大V杜撰《来自自来水的避孕药》博文，声称由于药物滥用，自来水中的避孕药含量过高，且无法通过常规的净化装置过滤，弄得人心惶惶，许多家庭担心饮水安全，纷纷抢购瓶装水"},{"label":"D","content":"网上疯传一则《硅油可致脱发并易致癌》的文章，披露市面上的洗发水九成含有硅油，微商小郑借机在朋友圈推销自制的天然皂角手工皂和茶籽洗发水，受到了推崇健康生活、回归自然者的追捧"}],"answer":"C","explanation":"咕咚效应定义的关键信息：由于谣言传播而导致的集体无意识恐慌蔓延的现象。<br>A项，房价暴涨不是谣言，且只说老李感到恐慌，没有体现集体无意识的恐慌，不符合定义。<br>B项，英国脱欧不是谣言，且银行的行为并非无意识的，不符合定义。<br>C项，自来水中的避孕药含量过高的谣言弄得人心惶惶，导致集体无意识恐慌蔓延，许多家庭纷纷抢购瓶装水，符合定义。<br>D项，说的是小郑自制的天然皂角手工皂和茶籽洗发水受到推崇健康生活、回归自然者的追捧，没有体现集体无意识的恐慌，不符合定义。","no":65},{"id":"1718789647818","type":"single","material":"","stem":"<p>公地悲剧是指享用者都从自己私利出发，争取从中获取更多收益而付出的代价由大家负担。</p><p>根据上述定义，下列不属于公地悲剧的是：</p>","options":[{"label":"A","content":"军备竞赛的双方都面临着一个困境，一方面军事力量不断增加，另一方面国家安全却受到越来越多的威胁"},{"label":"B","content":"博弈游戏中，任何“赢”的一方都是背离游戏的，任何“输”的一方也都是背离游戏的"},{"label":"C","content":"一群牧民一同在一块公共草场放牧。不少牧民都想多养羊增加个人收益，结果草场持续退化，直至无法养羊，最终导致所有牧民破产"},{"label":"D","content":"有的企业把下水道污物、化学物质、放射性污染物和高温废弃物等排放到水体中，将有毒废气排放到大气中"}],"answer":"B","explanation":"公地悲剧的定义要点：①享用者都从自己私利出发；②争取从中获取更多收益而付出的代价由大家负担。A项，军备竞赛的双方都从自己私利出发，不断增加军事力量，但国家安全却受到越来越多的威胁，即付出的代价由大家负担，符合定义。B项，博弈游戏中“赢”的一方和“输”的一方都是背离游戏的，但由此并未体现付出的代价由大家负担，不符合定义。C项，不少牧民都想多养羊增加个人收益，体现了他们都从自己私利出发，结果草场持续退化，直至无法养羊，导致所有牧民破产，体现了付出的代价由大家负担，符合定义。D项，有的企业把未经处理的污染物排放到水体和大气中，体现了从自己私利出发，但由此造成的水体污染和大气污染是由大家共同负担的，体现了付出的代价由大家负担，符合定义。","no":66},{"id":"1718789647819","type":"single","material":"","stem":"演绎作品是指在已有作品的基础上，经过改编、翻译、注释、整理等创造性劳动而产生的作品。<br>根据上述定义，下列不属于演绎作品的是：","options":[{"label":"A","content":"《基度山伯爵》电影剧本"},{"label":"B","content":"《飘》中英文对照版"},{"label":"C","content":"《<唐诗三百首〉经典诗句评析》"},{"label":"D","content":"《〈离骚〉难点词汇释义》"}],"answer":"C","explanation":"演绎作品是指在已有作品的基础上，经过改编、翻译、注释、整理等而产生的作品。<br>A项，电影剧本是在《基度山伯爵》的基础上经过改编产生的，符合定义。<br>B项，中英文对照版是在《飘》的基础上经过翻译产生的，符合定义。<br>C项，实际上是对《唐诗三百首》的评析，是以唐诗为材料的原创性作品，不能说是在《唐诗三百首》的基础上经过改编、翻译、注释、整理产生的，不符合定义。<br>D项，难点词汇释义是在《离骚》的基础上经过注释产生的，符合定义。","no":67},{"id":"1718789647820","type":"single","material":"","stem":"劳动争议是指在劳动者和劳动力使用者之间因劳动权利与义务发生分歧而引起的争议。<br>根据上述定义，下列属于劳动争议的是：","options":[{"label":"A","content":"职工小周因工作调动问题与当地劳动部门发生争执"},{"label":"B","content":"某企业职工小张和小李因工作上意见不合而产生矛盾"},{"label":"C","content":"两个单位之间因职工小刘的借调问题而产生矛盾"},{"label":"D","content":"职工老王因工伤未能获得保险赔偿而与工厂争执"}],"answer":"D","explanation":"劳动争议的定义要点：①劳动者和劳动力使用者之间；②劳动权利与义务有争议。<br>A项，职工小周与当地劳动部门发生争执，并非劳动者和劳动力使用者之间，不符合要点①。<br>B项，职工小张和小李产生矛盾，并非劳动者和劳动力使用者之间，不符合要点①。C项，两个单位之间产生矛盾，并非劳动者和劳动力使用者之间，不符合要点①。<br>D项，职工老王和工厂之间争执，符合劳动力和劳动力使用者之间；争执的是因工伤未能获得保险赔偿的问题，符合劳动权利与义务有争议。","no":68},{"id":"1718789647821","type":"single","material":"","stem":"流动偏好是指人们以货币的形式保持一部分资产的愿望和偏爱，它是一种心理动机，目的是应付日常开支、意外开支和在适当时机投机牟利。<br>根据上述定义，下列不属于流动偏好的是：","options":[{"label":"A","content":"为了购买住宅商品房，小王参加工作后就开始为买房存钱"},{"label":"B","content":"最近一段时间股市行情一直不好，许多股民纷纷退出股市"},{"label":"C","content":"银行一再降息，全国的储蓄率仍然很高"},{"label":"D","content":"老刘平时节俭不乱花钱是怕突如其来的下岗后的拮据"}],"answer":"B","explanation":"流动偏好的定义要点：①以货币形式保持一部分资产的愿望和偏爱；②应付日常开支、意外开支和在适当时机投机牟利。<br>A项，为了购买住宅商品房而存钱，属于应付日常开支，符合定义。<br>B项，股民退出股市是因为行情不好，为了规避风险，而不是为了应付日常开支、意外开支和在适当时机投机牟利等，不符合定义。<br>C项，储蓄率很高体现了人们以货币形式保持一部分资产的愿望和偏爱，符合定义。<br>D项，平时节俭不乱花钱以防下岗后的拮据，体现了以货币形式保持一部分资产以应付意外开支，符合定义。","no":69},{"id":"1718789647822","type":"single","material":"","stem":"“第三人效果”理论是指人们在判断大众传媒影响力之际存在着一种普遍的感知定式，即倾向于认为大众媒介的信息对“我”或“你”未必产生多大影响，<br>然而对“他者”产生不可估量的影响。<br>根据上述定义，下列不涉及“第三人效果”理论的是：","options":[{"label":"A","content":"人们认为有关新药的广告或者吸烟有害健康这样的信息对其他人的影响要大过对自己的影响"},{"label":"B","content":"微信的朋友圈中经常会有人分享很多所谓身体“健康”的信息"},{"label":"C","content":"支持限制暴力电影的人，他们支持并不是因为电影会影响到自己，而是认为他们会影响到其他人"},{"label":"D","content":"人们想象他人心目中自己的形象，想象他人对自己的评价，由此而产生自我感"}],"answer":"D","explanation":"“第三人效果”理论的定义要点：①认为大众媒介的信息对“我”或“你”未必产生多大影响；②对“他者”产生不可估量的影响。<br>A项，认为新药的广告或者吸烟有害健康这样的信息对其他人的影响要大过对自己的影响，符合定义。<br>B项，在微信朋友圈分享身体“健康”的信息给他人看，认为对其他人的影响要大过对自己的影响，符合定义。<br>C项，支持限制暴力电影的人，认为电影对其他人的影响要大过对自己的影响，符合定义。<br>D项，别人对自己的评价不属于大众媒介的信息，不符合要点①。","no":70},{"id":"1718789647823","type":"single","material":"","stem":"认知失调又名认知不和谐，是指一个人的行为与自己先前一贯的对自我的认知(而且通常是正面的、积极的自我)产生分歧，从一个认知推断出另一个对立的认知时而产生的不舒适感、不愉快的情绪。<br>根据上述定义，下列不属于认知失调的是：","options":[{"label":"A","content":"甲喜欢吸烟，读了吸烟可能致癌的文章后，心里很不舒服"},{"label":"B","content":"乙正在减肥，本应少吃高热量食品，但有一天实在无法控制自己的欲望，吃了一个甜甜圈，事后觉得很难过"},{"label":"C","content":"丙看到与自己干同样工作的同事拿到的工资远远高于自己，心里觉得很不舒服"},{"label":"D","content":"丁很不喜欢夸夸其谈的上司，仍不得不恭维他，为此，丁感到痛苦"}],"answer":"C","explanation":"认知失调的定义要点：①一个人的行为与自己先前一贯的对自我的认知(而且通常是正面的、积极的自我)产生分歧；②从一个认知推断出另一个对立的认知时而产生的不舒适感、不愉快的情绪。<br>A项，甲喜欢吸烟，读了吸烟可能致癌的文章后，心里很不舒服，说明自己的行为和原来的认识产生分歧，符合定义。<br>B项，乙正在减肥，本应少吃高热量食品，但吃了一个甜甜圈，事后觉得很难过，说明自己的行为和原来的认识产生分歧，符合定义。<br>C项，别人的行为(公司同工不同酬)与自己的认知(同工同酬)产生分歧，不符合要点①②。<br>D项，丁很不喜欢夸夸其谈的上司，仍不得不恭维他，丁感到痛苦，说明自己的行为和原来的认识产生分歧，符合定义。","no":71},{"id":"1718789647824","type":"single","material":"","stem":"危险犯，指行为人实施的危害行为造成法律规定的危险状态作为既遂标志的犯罪。这类犯罪不是以造成物质性的和有形的犯罪结果为标准，而以法定的客观危险状态的具备为标志。<br>根据上述定义，下列属于危险犯的是：","options":[{"label":"A","content":"猥亵儿童"},{"label":"B","content":"商业诈骗"},{"label":"C","content":"诬告陷害"},{"label":"D","content":"醉酒驾驶"}],"answer":"D","explanation":"危险犯的定义要点：①不是以造成物质性的和有形的犯罪结果为<br>标准；②以法定的客观危险状态的具备为标志。<br>A项，猥亵儿童是以造成物质性的和有形的犯罪结果为标准的，不属于危险犯。<br>B项，商业诈骗是以造成物质性的和有形的犯罪结果为标准的，不属于危险犯。<br>C项，诬告陷害也是以造成物质性的和有形的犯罪结果为标准的，不属于危险犯。<br>D项，醉酒驾驶不是以造成物质性的和有形的犯罪结果为准，并不需要造成实际危害，而是以醉酒驾驶这种行为属于客观危险状态为标志，符合危险犯的定义。","no":72},{"id":"1718789647825","type":"single","material":"","stem":"产品责任，是指产品在使用过程中因其缺陷(包括设计缺陷、制造缺陷和警示说明缺陷)而造成用户、消费者或公众的人身伤亡或财产损失时，依法应当由产品供给方(包括制造者、销售者、修理者等)承担的民事损害赔偿责任。<br>根据上述定义，以下情况明确属于产品供给方承担产品责任的是：","options":[{"label":"A","content":"某高架桥因使用不达标准的钢筋导致坍塌造成行人受伤"},{"label":"B","content":"未经过敏皮试的患者在注射青霉素之后死亡"},{"label":"C","content":"市民购买酸奶后未冷藏，饮用后生病住院"},{"label":"D","content":"某婴儿误食成人维生素导致急性中毒"}],"answer":"A","explanation":"产品责任定义的关键信息：产品在使用过程中因其缺陷而造成人身伤亡或财产损失。<br>A项，桥梁是因为制造缺陷所以坍塌造成行人受伤，符合产品责任的定义。<br>B项，青霉素本身不存在设计缺陷，是因为使用者使用不当造成了患者死亡，不属于产品责任。<br>C项，是酸奶未冷藏造成市民生病住院，不属于产品责任。<br>D项，是婴儿误食成人维生素，维生素本身不存在缺陷，不符合产品责任的定义。","no":73},{"id":"1718789647826","type":"single","material":"","stem":"睡眠者效应指的是信源可信性的传播效果会随时间推移而发生改变的现象。也就是说，传播结束一段时间后，高可信性信源带来的正效果在下降，而低可信性信源带来的负效果却朝向正效果转化。<br>根据上述定义，以下哪项属于睡眠者效应?","options":[{"label":"A","content":"名人广告只能带来短期内销售额的增加，时间一长，产品的销售额就迅速下降了"},{"label":"B","content":"某产品由于名称容易使人产生不好的联想，尽管质量上乘，但是一直打不开市场"},{"label":"C","content":"小李前一天晚上看中的一件非常满意的商品，第二天早上一看，觉得不过如此，她迅速取消了订单"},{"label":"D","content":"爱看武侠小说的李某年轻时常常有打抱不平的冲动，40岁之后的他变得谨慎持重了"}],"answer":"A","explanation":"睡眠者效应定义的关键信息：信源可信性的传播效果会随时间推移而发生改变。<br>A项，名人的广告效果随着时间推移而降低，符合睡眠者效应的定义。<br>B项，是因为名称的原因导致打不开市场，与时间无关，不符合定义。<br>C项，只是小李的想法的改变，不涉及信源的可信性，不符合定义。<br>D项，李某随着年龄的增长性格改变没有体现信源可信性的传播，不符合定义。","no":74},{"id":"1718789647827","type":"single","material":"","stem":"消费文化是指在一定的历史阶段中，人们在物质生产、精神生产、社会生活以及消费活动中所表现出来的消费理念、消费方式、消费行为和消费环境的总和。<br>根据上述定义，下列不属于消费文化的是：","options":[{"label":"A","content":"“十一”黄金周假期，促进了居民参与国内外旅游的休闲消费"},{"label":"B","content":"年轻人更乐于通过网上购物的方式来购买自己需要的物品"},{"label":"C","content":"中老年人，特别是老年人，喜欢在购物环境比较安静和舒适的地方进行消费"},{"label":"D","content":"随着互联网的发展，许多年轻人开办了自己的网店"}],"answer":"D","explanation":"消费文化的定义要点：①在物质生产、精神生产、社会生活以及消费活动中；②消费理念、消费方式、消费行为和消费环境的总和。<br>A项，黄金周假期国内外旅游属于社会生活，休闲消费属于消费理念，符合定义。<br>B项，网上购物属于消费活动，购买自己需要的物品属于消费行为，符合定义。<br>C项，老年人购物属于消费活动，在比较安静和舒适的地方进行消费属于消费环境，符合定义。<br>D项，开网店不属于消费，不符合定义。","no":75},{"id":"1718789647828","type":"single","material":"","stem":"情感激励法是指通过良好的情感关系，激发被管理者的积极性，从而达到提高工作效率的一种管理激励方法。<br>根据上述定义，下列属于情感激励法的是：","options":[{"label":"A","content":"一名员工由于在大会上指责经理，被人讽刺、打击、报复，感到很无奈"},{"label":"B","content":"一名员工被怀疑私自收取顾客好处费而被责令待岗反省，他很伤心"},{"label":"C","content":"职工的思想和行动得到领导赞许，产生了继续坚持下去的情绪"},{"label":"D","content":"经理办公室决定，以后不允许职工在公司内谈论家常事"}],"answer":"C","explanation":"情感激励法的定义要点：①通过良好的情感关系，激发被管理者的<br>积极性；②提高工作效率。<br>A项，员工感到无奈，不是积极性的表现，不符合要点①。<br>B项，员工感到伤心，不是积极性的表现，不符合要点①。<br>C项，员工得到赞许，产生了继续坚持下去的情绪，符合定义。<br>D项，不允许职工在公司内谈论家常事，不涉及情感关系，不符合要点①。","no":76},{"id":"1718789647829","type":"single","material":"","stem":"工业产权是指法律规定对应用于生产和流通中的创造发明和显著标记等智力成果在一定期限和地区内享有的专有权。<br>根据上述定义，下列属于工业产权的是：","options":[{"label":"A","content":"某国有企业车间、厂房等不动产的所有权"},{"label":"B","content":"某企业近期购买的国外先进流水线生产设备的所有权"},{"label":"C","content":"某化工厂的高新技术研究所的产权"},{"label":"D","content":"某电器生产企业对经多年打拼创下的品牌享有的权利"}],"answer":"D","explanation":"工业产权的定义要点：①应用于生产和流通中；②创造发明和显著标记等智力成果在一定期限和地区内享有的专有权。<br>A项，国有企业车间、厂房等不动产的所有权，不属于在一定期限和地区内享有的专有权，不符合要点②。<br>B项，企业购买生产设备的所有权，不属于创造发明和显著标记等智力成果，不符合要点②。<br>C项，高新技术研究所的产权，不是应用于生产和流通中，不符合要点①。<br>D项，电器生产企业属于生产和流通中，打拼创下的品牌享有的权利属于智力成果且有一定期限，符合定义。","no":77},{"id":"1718789647830","type":"single","material":"","stem":"出口补贴(出口津贴)是指一国政府为降低出口商品的价格，加强其在国外市场上的竞争能力，在出口某种商品时给予出口厂商的现金补贴或财政上的优惠待遇。<br>根据上述定义，下列不属于出口补贴行为的是：","options":[{"label":"A","content":"某公司生产的自行车出口享受税收优惠政策"},{"label":"B","content":"某出口公司税款被减免"},{"label":"C","content":"某彩电出口到非洲时降价销售"},{"label":"D","content":"镇政府资助某出口水产集团"}],"answer":"C","explanation":"出口补贴的定义要点：①政府为降低出口商品的价格，加强其在国外市场上的竞争能力；②出口某种商品时给予出口厂商的现金补贴或财政上的优惠待遇。<br>A项，自行车出口享受税收优惠政策，属于政府给予出口厂商的现金补贴或财政上的优惠待遇，符合定义。<br>B项，某出口公司税款被减免，属于政府给予出口厂商的现金补贴或财政上的优惠待遇，符合定义。<br>C项，彩电出口到非洲，没有涉及政府，不符合要点①。<br>D项，镇政府资助某出口水产集团，属于政府给予出口厂商的现金补贴或财政上的优惠待遇，符合定义。","no":78},{"id":"1718789647831","type":"single","material":"","stem":"文饰，是指无意识地通过似乎有理而实际上站不住脚的理由来为自己难以接受的情感、行为或动机辩护，以使其可以接受。\n<img src=\"assets/img/1497669c7c15a7.png\" alt=\"图片_rId2\">根据上述定义，下列现象不属于文饰的是：","options":[{"label":"A","content":"将个人高考的失败，完全归于家庭环境的影响"},{"label":"B","content":"当得不到葡萄而只有柠檬时，就说柠檬是甜的"},{"label":"C","content":"对于自己得不到的东西，就说它一定是不好的"},{"label":"D","content":"把自己恋爱的成功，简单归因于自己长得帅气"}],"answer":"D","explanation":"文饰定义的关键信息：用站不住脚的理由来为自己难以接受的情感、行为或动机辩护，以使其可以接受。<br>A项，用家庭环境的影响这一理由来为自己的高考失败辩护，符合定义。<br>B项，用柠檬是甜的这一明显站不住脚的理由来为得不到葡萄辩护，符合定义。<br>C项，用得不到的东西一定是不好的这一理由来为自己得不到东西辩护，符合定义。<br>D项，恋爱成功属于已经得到，不属于难以接受的情感、行为或动机，不符合定义。","no":79},{"id":"1718789647832","type":"single","material":"","stem":"不可抗力，是指不能预见、不能避免并不能克服的客观情况。因不可抗力不能履行合同或者造成他人损害的，不承担民事责任，法律另有规定的除外。<br>根据上述定义，下列情况不属于不可抗力的是：","options":[{"label":"A","content":"因天气原因不能起飞而导致的航班延误"},{"label":"B","content":"因地震致房屋倒塌，使租赁合同不能履行"},{"label":"C","content":"因出口国发生战争而导致的货物延期交付"},{"label":"D","content":"因卖方工厂倒闭而导致的不能交付货物"}],"answer":"D","explanation":"不可抗力强调不能预见、不能避免、不能克服的客观情况。A项，天气原因是不能避免、不能克服的客观情况，属于不可抗力，排除。<br>B项，地震是不能避免、不能克服的客观情况，属于不可抗力，排除。<br>C项，出口国战争是不能预见、不能克服的客观情况，属于不可抗力，排除。<br>D项，工厂倒闭是有先兆的，属于可预见和可避免的，不符合不可抗力的定义。","no":80},{"id":"1718789647833","type":"single","material":"","stem":"机械表演，是指对作品的表演使用机械设备予以公开播放的行为，不包括公开放映电影和通过广播传播作品的行为。<br>根据上述定义，下列行为属于机械表演行为的是：","options":[{"label":"A","content":"甲超市使用电视机公开播放存在电脑里的歌曲"},{"label":"B","content":"丙美术馆公开展览一大批书法作品和摄影作品"},{"label":"C","content":"丁商场通过幻灯机公开再现存在电脑里的电影"},{"label":"D","content":"乙电台在广播节目播出同时，在网上同步播出"}],"answer":"A","explanation":"机械表演的定义要点：①使用机械设备公开播放作品；②不包括公开放映电影和通过广播传播作品。<br>A项，使用电视机播放歌曲，且并没有出现题干提及的两种不包括的情况，符合定义。<br>B项，公开展览书法和摄影作品，并没有使用机械设备公开播放，不符合要点①,排除。<br>C项，公开放映电影，属于题干提及的两种不包括的情况之一，不符合要点②,排除。<br>D项，通过广播传播作品，属于题干提及的两种不包括的情况之一，不符合要点②,排除。","no":81},{"id":"1718789647834","type":"single","material":"","stem":"破窗效应是犯罪学的一个理论，该理论认为环境中的不良现象如果被放任存在，会诱使人们仿效，甚至变本加厉。<br>根据上述定义，下列体现了破窗效应的是：","options":[{"label":"A","content":"千里之堤，溃于蚁穴"},{"label":"B","content":"一屋不扫，何以扫天下"},{"label":"C","content":"一条街道有些许纸屑，人们最终会理所当然地将垃圾随处丢弃"},{"label":"D","content":"小孩打破了窗户，必将导致主人更换玻璃，从而推动社会就业"}],"answer":"C","explanation":"破窗效应定义的关键信息：环境中的不良现象被放任，会诱使人们效仿，变本加厉。<br>A项，比喻小事不慎将酿成大祸，并非放任不良现象存在，不符合定义。<br>B项，指从一点一滴的小事开始积累，才能做成一番大事业，不符合定义。<br>C项，有纸屑放任不管，导致人们变本加厉，都不注重保护环境而乱扔垃圾，符合定义。<br>D项，打破窗户更换玻璃，推动社会就业，并未体现放任不良现象存在，不符合定义。","no":82},{"id":"1718789647835","type":"single","material":"","stem":"圆雕是指不附着在任何背景上、可以从各个角度欣赏的立体的雕塑。其手法与形式多种多样，有写实性的与装饰性的，也有具体的与抽象的，着色的与非着色的等。<br>根据上述定义，下图所示雕塑作品中，属于圆雕的是：","options":[{"label":"A","content":"<img src=\"assets/img/5a149a06f709a6.png\" alt=\"图片_rId3\">"},{"label":"B","content":"<img src=\"assets/img/5680771b5fc672.png\" alt=\"图片_rId4\">"},{"label":"C","content":"<img src=\"assets/img/420349f9e43994.png\" alt=\"图片_rId5\">"},{"label":"D","content":"<img src=\"assets/img/638c044cbc8764.png\" alt=\"图片_rId6\">\n<div class=\"image-block\"><img src=\"assets/img/b8918f9669c2ae.png\" alt=\"图片_rId7\"></div>"}],"answer":"A","explanation":"圆雕定义的关键信息：不附着在任何背景上。<br>A项，符合圆雕的定义。<br>B项，附着在墙壁上，不符合定义。<br>C项，是附着在画纸上的画，不符合定义。<br>D项，是附着在屏风上的画，不符合定义。","no":83},{"id":"1718789647836","type":"single","material":"","stem":"单位犯罪，指公司、企业、事业单位、机关、团体实施的危害社会的、依照法律规定应受惩罚的行为。<br>根据上述定义，下列属于单位犯罪的是：","options":[{"label":"A","content":"某医院的院长利用职务之便收受贿赂"},{"label":"B","content":"某事业单位一名员工因对领导不敬，因此被降职"},{"label":"C","content":"某班级的学生认为教师甲的教学能力差，因此集体向学校领导提出开除该老师的建议"},{"label":"D","content":"某公司派一名员工去另一对手公司偷窃商业机密文件以用于自己公司的发展"}],"answer":"D","explanation":"单位犯罪的定义要点：①单位团体实施；②行为危害社会，依法应受惩罚。<br>A项，某医院院长个人受贿，不符合要点①。<br>B项，员工个人对领导不敬而被降职，不符合要点①②。<br>C项，学生集体提议开除教学能力差的老师，不符合要点②。<br>D项，公司派人偷窃对手商业机密文件，符合定义要点。","no":84},{"id":"1718789647837","type":"single","material":"","stem":"服务型公关是指组织以提供各种实惠服务为主，通过实际行动获取社会公众的了解和好评，从而建立组织良好形象的公共关系活动。<br>根据上述定义，下列属于服务型公关的是：","options":[{"label":"A","content":"某热水器厂家定期向用户发送热水器使用注意事项，每年为用户免费更换滤网"},{"label":"B","content":"某环保公司通过某电视节目宣布向灾区一次性提供价值5亿元的救助物资"},{"label":"C","content":"某酒厂在电视黄金时段投放大量广告宣传其新产品"},{"label":"D","content":"某制药公司董事长就生产的某批次药品不合格一事向消费者公开道歉，并辞去相关职务"}],"answer":"A","explanation":"服务型公关的定义要点：①组织以提供各种优惠服务为主；②通过实际行动获取社会公众的了解和好评。<br>A项，为用户发送使用注意事项和免费更换滤网属于提供优惠服务，并通过实际行动获取社会公众的了解和好评，符合定义要点。<br>B项，提供救助物资不属于优惠服务，不符合要点①。<br>C项，投放大量广告不属于优惠服务，不符合要点①。<br>D项，董事长向消费者公开道歉并辞去职务不属于提供优惠服务，不符合要点①。","no":85},{"id":"1718789647838","type":"single","material":"","stem":"消费痛点指消费者在使用或希望使用某商品时，认为存在特别令人不满意或令人感到麻烦的地方。<br>根据上述定义，下列不属于消费痛点的是：","options":[{"label":"A","content":"江女士特别注重美容，购买了某品牌护肤品，但她发现使用起来很不方便"},{"label":"B","content":"老马为了养生特地购买了海参，但他发现发制和烹煮特别耗费时间和精力"},{"label":"C","content":"小林家使用的抽油烟机效果很好，但清洗太复杂，每次都需专业人员登门"},{"label":"D","content":"谢女士买了一条心仪已久的裙子，但是穿上后周围的朋友都说不适合她，她感到很沮丧"}],"answer":"D","explanation":"消费痛点的定义要点：①消费者在使用或希望使用某商品时；②存在特别令人不满意或令人感到麻烦的地方。<br>A项，使用起来不方便，符合定义。<br>B项，耗费时间和精力，符合定义。<br>C项，清洗复杂需要专业人员，符合定义。<br>D项，谢女士因朋友说裙子不适合她而感到沮丧，不符合要点②,因此不属于消费痛点。","no":86},{"id":"1718789647839","type":"single","material":"","stem":"无卡支付指付款人借助互联网、移动互联网、无线局域网等渠道进行的，不需要通过受理设备读取物理卡片，即可向收款人转移可以接受的货币债权。<br>根据上述定义，下列不属于无卡支付的是：","options":[{"label":"A","content":"小王是个网购达人，为方便购物，他开通了支付宝的“快捷支付”功能，输入卖家支付宝账号即可付款完成交易"},{"label":"B","content":"某高校开通了“校园一卡通”服务，该卡既可以当门禁卡、借书证使用，也可以用它在餐厅、超市消费，方便了广大师生"},{"label":"C","content":"小钱是资深的游戏玩家，经常在游戏平台用网银购买大量游戏装备"},{"label":"D","content":"餐馆老板老吴开通了微信支付，顾客买单时只需用手机扫描账单上的二维码，即可用微信支付相应的费用"}],"answer":"B","explanation":"无卡支付定义的关键信息：不需要读取物理卡片。<br>A项，支付宝付款不需要读取物理卡片，符合定义。<br>B项，“校园一卡通”属于物理卡片，不符合定义。<br>C项，网银购买不需要读取物理卡片，符合定义。<br>D项，微信支付不需要读取物理卡片，符合定义。","no":87},{"id":"1718789647840","type":"single","material":"","stem":"超率累进税率是指以征税对象数额的相对率(如产值利润率、资金利润率、销售利润率、成本利润率等)划分征税级距，分别规定相应的差别税率，相对率每超过一个级距的，对超过的部分就按高一级的税率计算征税。<br>根据上述定义，下列各项中按照超率累进税率征税的是：","options":[{"label":"A","content":"我国法律规定，土地增值额未超过扣除项目金额50%的部分，土地增值税税率为30%;超过扣除项目金额50%、未超过100%的部分，税率为40%"},{"label":"B","content":"新中国建国初期征收工商所得税税率分为21级，所得额未满300元的税率为5.75%;所得额在万元以上的税率为34.5%"},{"label":"C","content":"我国企业所得税的税率为25%。符合条件的小型微利企业，按20%的税率征收企业所得税；国家需要重点扶持的高新技术企业，按15%的税率征收企业所得税"},{"label":"D","content":"我国法律规定，白酒消费税税率为240元/吨，黄酒消费税税率为250元/吨，啤酒消费税税率为220元/吨"}],"answer":"A","explanation":"超率累进税率定义的关键信息：相对率每超过一个级距的就对超<br>过的部分按高一级的税率计算征税。<br>A项，对未超过扣除项目金额50%的部分和超过50%、未超过100%的部分采取不同的税率，符合定义。<br>B项，根据所得额的不同设置不同税率，没有体现对超出部分按不同税率征税，不符合定义。<br>C项，针对不同条件的企业设置不同税率，没有体现对超出部分按不同税率征税，不符合定义。<br>D项，针对不同种类的产品设置不同税率，没有体现对超出部分按不同税率征税，不符合定义。","no":88},{"id":"1718789647841","type":"single","material":"","stem":"异称词是指不同的社会群体、不同的地区或不同的时代对同一事物的不同称呼。<br>根据上述定义，下列不属于异称词的是：","options":[{"label":"A","content":"老一辈的人仍习惯把火柴称作“洋火”"},{"label":"B","content":"现在售货员很多时候会称女顾客为“美女”"},{"label":"C","content":"明代时人们一般把蛤蟆称为癞施或田鸡"},{"label":"D","content":"四川人说的红苕其实就是河南人说的红薯"}],"answer":"B","explanation":"异称词的定义要点：①不同的社会群体、不同的地区或不同的时代；②对同一事物不同的称呼。<br>A项，“老一辈”代表与现在属于不同的时代，“洋火”和“火柴”属于异称词。<br>B项，“美女”只是一种称呼，未体现对同一事物不同的称呼，不符合异称词的定义。C项，明代也属于不同的时代，“蛤蟆”和“田鸡”属于异称词。<br>D项，四川人和河南人属于不同的地区，“红苕”和“红薯”属于异称词。","no":89},{"id":"1718789647842","type":"single","material":"","stem":"无意注意是指没有预定目的，无需意志努力，不由自主地对一定事物所发生的注意。无意注意时，心理活动对一定事物的指向和集中是由一些主观和客观条件所引起的。<br>根据上述定义，下列不属于无意注意的是：","options":[{"label":"A","content":"上课时学生突然被窗外飞进来的蝴蝶所吸引"},{"label":"B","content":"肚子饿的小明一进房间就看见了桌上的面包"},{"label":"C","content":"小红埋头完成家庭作业，不知不觉过了很久"},{"label":"D","content":"人们在绿油油的草地上一眼就看到了小红花"}],"answer":"C","explanation":"无意注意定义的关键信息：不由自主地对一定事物所发生的注意。A项，不由自主地被突然飞进来的蝴蝶吸引，属于无意注意。<br>B项，一眼就看见面包，符合无意注意的定义。<br>C项，埋头完成作业是有预定目的、需意志努力的，只是对时间并没有注意，不符合定义。<br>D项，在绿油油的草地上看到小红花，也无需意志努力，属于无意注意。","no":90},{"id":"1718789647843","type":"single","material":"","stem":"棘轮效应是指人的消费习惯形成之后有不可逆性，即易于向上调整，而难于向下调整。<br>根据上述定义，下列符合棘轮效应的是：","options":[{"label":"A","content":"赵老板生意失败，变卖了公司资产和名下房产后，还欠银行20多万元，但为了出行方便，他没有用自己的高档汽车抵债"},{"label":"B","content":"李某买彩票中了500万大奖后没有告诉任何人，偷偷把钱存到银行，还和从前一样正常上班、下班，而且工作更积极了"},{"label":"C","content":"一夜暴富的老朱频繁出入高档消费场所，过着挥金如土的生活，很快就入不敷出，回到了之前的生活状态，旁人都唏嘘不已，他自己倒安之若素"},{"label":"D","content":"王老汉从农村来城里带孙子，因心疼电费舍不得用空调，借口说不习惯空调吹出的冷风，让儿子买了一台和老家一样的落地电扇用来降温消暑"}],"answer":"A","explanation":"棘轮效应的定义要点：①消费习惯形成后不可逆；②易于向上调整，难于向下调整。<br>A项，即使破产了也不愿改变之前的出行习惯，难于向下调整，符合定义。<br>B项，消费习惯没有发生改变，不符合要点②。<br>C项，回到之前的生活状态也安之若素，不符合要点①②。<br>D项，不舍得用空调而用风扇，不符合要点②。","no":91},{"id":"1718789647844","type":"single","material":"","stem":"合成字是合体字中一个比较特殊的门类。它原本是汉语中一个常用的词语、词组，但由于这些词语、词组在方言中使用的频率很高，就把这些词语在讲究字形美观的前提下原封不动地组合成一个独有的汉字。<br>根据上述定义，下列汉字根据其意思不属于合成字的是：","options":[{"label":"A","content":"曼，读作jiào,方言，“只要”的意思"},{"label":"B","content":"水，读作nì,古同“溺”,沉没，沉溺"},{"label":"C","content":"要，读作fiào,表示否定，相当于“不要”"},{"label":"D","content":"戡，读作xiǎn,意思是稀有的、罕见的"}],"answer":"B","explanation":"合成字的定义要点：①原本是汉语中一个常用的词语、词组；②在方言中使用的频率很高；③原封不动地组合。<br>B项，“水”,“水人”并不是一个常用的词语，使用频率低，不符合定义要点①②,是一个会意字。<br>A、C、D三项中的字都属于合成字。","no":92},{"id":"1718789647845","type":"single","material":"","stem":"数字鸿沟指的是由于信息化和互联网的影响，人们的信息获取、信息处理和信息传播都是通过数字化技术来实现的，由此造成了不同个体、群体或者国<br>家在思想意识、经济、文化和政治等方面的差距越来越大。<br>根据上述定义，下列不涉及数字鸿沟的是：","options":[{"label":"A","content":"放假回家的小宋和同学用手机聊天，满口网络新词，一旁的奶奶一句也听不懂"},{"label":"B","content":"东部某镇种植的水果尚未成熟就已经通过网络平台被订购一空，而西部某乡质优价廉的水果由于无人知晓只能烂在树上"},{"label":"C","content":"小赵整天痴迷于网络游戏，父母多次苦口婆心地劝说，均没有效果，为此小赵和父母发生了多次争执"},{"label":"D","content":"一些西方国家利用其技术积累，在大数据处理方面取得了绝对的优势，他们进一步实行技术封锁，使得某些国家在大数据分享方面一筹莫展"}],"answer":"C","explanation":"数字鸿沟的定义要点：①信息；②通过数字化技术来实现的；③差距越来越大。<br>A项，小宋和奶奶由于互联网的发展产生差距，属于数字鸿沟。<br>B项，运用互联网导致东西部差异，也属于数字鸿沟。<br>C项，小赵痴迷于网络游戏不属于信息的范畴，不符合要点①。<br>D项，大数据技术封锁导致西方国家和其他国家产生差距，符合数字鸿沟的定义<br>要点。","no":93},{"id":"1718789647846","type":"single","material":"","stem":"择一的因果关系是指两个或者两个以上的行为人都实施了可能对他人造成损害的危险行为，并且已经造成了损害结果，但是无法确定其中谁是加害人。<br>根据上述定义，下列存在择一的因果关系的是：","options":[{"label":"A","content":"甲、乙两人在搬卸货物过程中因操作不当，造成货物损坏"},{"label":"B","content":"甲在乙的饮水中下毒，乙喝下后在毒发前又因琐事与丙发生争吵，丙一怒之下用刀刺死了乙"},{"label":"C","content":"甲、乙共同绑架了丙，甲负责向丙的家人索要赎金，乙为避免被丙认出，将丙残忍杀害"},{"label":"D","content":"甲、乙、丙三人带着相同的猎枪和子弹外出狩猎，甲、乙看到一只猎物出现在丙附近，二人同时开枪，结果其中一枪打中了丙"}],"answer":"D","explanation":"择一的因果关系的定义要点：①两个或两个以上的行为人；②对他人造成损害；③无法确定谁是加害人。<br>A项，造成货物损坏，并非对他人造成损害，不符合要点②。<br>B项，乙是在毒发前被丙刺死的，加害人为丙，不符合要点③。<br>C项，丙是被乙杀害的，乙为加害人，不符合要点③。<br>D项，甲、乙同时开枪，其中一枪打中了丙，无法确定谁是加害人，符合定义。","no":94},{"id":"1718789647847","type":"single","material":"","stem":"不规则需求是指某些物品或者服务的市场需求在不同季节，或一周不同日子，甚至一天不同时间上下波动很大的一种需求状况。<br>根据上述定义，下列哪项属于不规则需求?","options":[{"label":"A","content":"早晚高峰期出租车供不应求"},{"label":"B","content":"某品牌牙刷分为软、硬、中三种以面向不同消费者"},{"label":"C","content":"某电商店庆打折，活动当天点击量剧增"},{"label":"D","content":"某博物馆引进一批凡·高画作巡展，游客蜂拥而至"}],"answer":"A","explanation":"不规则需求定义的关键信息：在不同时间段市场需求的波动大。A项，早晚高峰用车量明显增多，即一天不同时间市场需求的波动很大，符合定义。<br>B项，牙刷分为软、硬、中三种以面向不同消费者，并未体现不同时间段市场需求的波动大，不符合定义。<br>C项，点击量剧增是因为有电商店庆打折活动，未体现市场需求的波动大，不符合定义。<br>D项，游客蜂拥而至是因为引进一批凡·高画作巡展，未体现市场需求的波动大，不符合定义。","no":95},{"id":"1718789647848","type":"single","material":"","stem":"红叶子理论认为：一个人职业的成功不在于红叶子的数目多少，而在于他是否具备一片特别硕大的红叶子，这片特别硕大的红叶子不是与生俱来的，需要根据个人优势不断努力才能获得。<br>根据上述定义，下列哪项能用红叶子理论解释?","options":[{"label":"A","content":"小李的销售能力和财务水平一般，但对市场特别敏感，他努力发展这方面优势，最后成了一名企业家"},{"label":"B","content":"小刘虽然偶尔迟到，但对工作尽职尽责、富有团队精神"},{"label":"C","content":"小张本科学习数学专业，但是他觉得数学专业比较枯燥，所以他选择攻读经济学硕士"},{"label":"D","content":"小文是英语系学生，但口语不太好，她辅修了国际法方面的课程，最后成了一名出色的律师"}],"answer":"A","explanation":"红叶子理论定义的关键信息：决定一个人职业成功的是他的优势这个优势不是与生俱来的，而是根据个人优势不断努力获得的。<br>A项，小李的优势是对市场敏感，他努力发展这方面优势，最终成了一名企业家，获得职业的成功，符合定义。<br>B项，只说小刘对工作尽职尽责、富有团队精神，但并未体现他利用这一个人优势不断努力，从而取得职业成功，不符合定义。<br>C项，小张觉得数学专业比较枯燥，选择攻读经济学硕士，并不涉及个人优势或职业成功，不符合定义。<br>D项，小文的口语不太好，说的是缺点而非个人优势，不符合定义。","no":96},{"id":"1718789647849","type":"single","material":"","stem":"生物学研究发现，成群的蚂蚁中，大部分蚂蚁很勤劳，寻找、搬运食物争先恐后，少数蚂蚁却东张西望不干活。当食物来源断绝或蚁窝被破坏时，那些勤快的蚂蚁一筹莫展。“懒蚂蚁”则“挺身而出”,带领众伙伴向它早已侦察到的新的食物源转移。这就是所谓的懒蚂蚁效应。<br>根据上述定义，下列属于懒蚂蚁效应的是：","options":[{"label":"A","content":"通信工程师待遇优厚，工作时间自由，擅长攻克技术难题"},{"label":"B","content":"某汽车公司鼓励员工创新，允许员工在上班时间钻研技术"},{"label":"C","content":"某经理用人不拘一格，看重的是坚韧和正直，而非学历背景"},{"label":"D","content":"在金融危机中，某外贸公司凭借多元化经营手段渡过了难关"}],"answer":"A","explanation":"懒蚂蚁效应定义的关键信息：少数平时不正常工作的个体能够处理特殊状况下的问题。<br>A项，通信工程师工作时间自由，是一个公司中平时不正常工作的群体，却能攻克技术难题，体现了懒蚂蚁效应，符合定义。<br>B项，公司鼓励员工创新，允许员工上班时间钻研技术，并未体现少数不正常工作的个体能够处理特殊问题，不符合定义。<br>C项，说的是某经理的用人标准，并未体现少数不正常工作的个体能够处理特殊问题，不符合定义。<br>D项，该公司凭借多元化经营手段渡过金融危机，并未体现少数不正常工作的个体能够处理特殊问题，不符合定义。","no":97},{"id":"1718789647850","type":"single","material":"","stem":"精益生产是通过系统结构、人员组织、运行方式和市场供求等方面的变革，最大限度地消除浪费和降低库存以及缩短生产周期，力求实现低成本准时生产的技术。其最终目的是通过流程整体优化、均衡物流、高效利用资源、消灭一切库存和浪费，达到用最少的投入向顾客提供最完美价值的目的。<br>根据上述定义，下列属于精益生产的是：","options":[{"label":"A","content":"为了抢占市场，甲公司不断提高空间利用率"},{"label":"B","content":"乙公司投入了大量资金以缩短其产品生产周期"},{"label":"C","content":"丙公司的强大供货体系保证它能随时满足客户"},{"label":"D","content":"丁公司充分发挥自身优势建立了超快的物流系统"}],"answer":"D","explanation":"精益生产定义的关键信息：消除浪费和降低库存以及缩短生产周期，实现低成本准时生产，达到用最少的投入向顾客提供最完美价值的目的。<br>A项，目的是抢占市场，没有体现出以最少的投入向顾客提供最完美的价值，不符合定义。<br>B项，投入大量资金，并不是以最少的投入，不符合定义。<br>C项，强大的供货体系，没有体现降低库存、消除浪费，不符合定义。<br>D项，建立超快的物流系统，体现了降低库存，用最少的投入向顾客提供最完美的价值，符合定义。","no":98},{"id":"1718789647851","type":"single","material":"","stem":"前控控制是指在计划实施之前，为了保证将来的实际成果能达到计划的要求，尽量减少偏离的控制。<br>根据上述定义，下列属于前控控制的是：","options":[{"label":"A","content":"营销部主任在方案推广期间，不断做出调整，尽量避免误差"},{"label":"B","content":"新药剂的配方尽管之前经过多位专家考证，但药效还不如老配方"},{"label":"C","content":"新游戏的图纸在投入编程之前，经过了几轮研讨以确保效果逼真"},{"label":"D","content":"新产品上市后销量一般，工厂组织技术人员进行升级后再次推向市场"}],"answer":"C","explanation":"前控控制定义的关键信息：在计划实施之前的控制。<br>A项，在方案推广期间，说明计划已经实施，不符合定义。<br>B项，新药剂的药效不如老配方，说明新药剂已经生产出来，并非在计划实施之前进<br>行控制，不符合定义。<br>C项，图纸投入编程之前进行研讨以确保效果逼真，是在计划实施之前进行控制，属于前控控制。<br>D项，新商品已经上市，并非在计划实施之前进行控制，不符合定义。","no":99},{"id":"1718789647852","type":"single","material":"","stem":"专利间接侵权是指，行为人的行为本身并不直接侵犯他人的专利，但却教唆、帮助或诱导他人实施专利侵权行为。<br>根据上述定义，下列哪项属于专利间接侵权?","options":[{"label":"A","content":"王某通过个人关系购买了甲公司发动机设备，该设备已申请国家专利，之后经甲公司许可转售给乙公司"},{"label":"B","content":"李某购买了一批已申请专利的用于浇注系统的模具，在购买前他和生产该模具的公司签订了相关合同"},{"label":"C","content":"宋某将某外文小说译成中文后，以第一作者身份出版该小说，从中获利一百万元"},{"label":"D","content":"甲公司遇到技术问题后委托乙公司解决，并暗示乙公司技术人员采用丙公司的专利技术，但未告知丙公司"}],"answer":"D","explanation":"专利间接侵权定义的关键信息：行为人不直接侵犯他人专利，而是教唆、帮助或者诱导他人实施专利侵权行为。<br>A项，王某是经过甲公司许可后将设备转售给乙公司，属于合法行为，并没有教唆、帮助或诱导他人实施专利侵权行为，不符合定义。<br>B项，李某的购买行为是合法的，并没有教唆、帮助或诱导他人实施专利侵权行为，不符合定义。<br>C项，宋某将翻译来的外文小说以第一作者的身份出版，是直接侵犯他人专利，不符合定义。<br>D项，甲公司暗示乙公司技术人员采用丙公司的专利技术，甲公司并未直接侵权，但诱导他人实施专利侵权行为，符合定义。","no":100},{"id":"1718789647853","type":"single","material":"","stem":"互助游是指有旅游意向的双方利用互联网等媒介中的人脉关系交换旅游资源，相互提供帮助而实现旅游的方式，达到双方都能降低旅游成本、实现深入体验旅游的目的。<br>根据上述定义，下列涉及互助游的是：","options":[{"label":"A","content":"小张在北京读书，利用暑假时间到同学所在的城市旅游，期间住在同学的宿舍"},{"label":"B","content":"小王家住南京，准备到西藏旅游，邀请家住西安的网友同行，分摊支出，旅途中互相帮助"},{"label":"C","content":"小刘住在北京，在桂林旅游期间住在网友家里，对方到北京旅游时，自己也向对方提供住宿"},{"label":"D","content":"小赵住在上海，到海南旅行，食宿与行程均由朋友安排负责，小赵返沪后邀请朋友到上海玩"}],"answer":"C","explanation":"互助游定义的关键信息：交换旅游资源。<br>A项，小张到同学所在的城市旅游，期间住在同学的宿舍，只是小张单方面使用了同学的资源，并未体现交换旅游资源，不符合定义。<br>B项，小王邀请网友一同旅游，分摊支出，并不是交换资源，而是共同使用其他资源，不符合定义。<br>C项，小刘和网友到对方的城市旅游时，互相提供住宿，体现了交换旅游资源，符合定义。<br>D项，小赵只是邀请朋友到上海玩，还未涉及旅游资源交换，不符合定义。","no":101},{"id":"1718789647854","type":"single","material":"","stem":"替代性攻击，即遭受挫折后由于无法直接向挫折制造的源头表达愤怒或不满，而将怒气发泄到另外的“替罪羊”身上，“替罪羊”往往处于相对较弱的地位。<br>根据上述定义，下列不属于替代性攻击的是：","options":[{"label":"A","content":"甲在工作中被老板责备，心怀不满，回家后因为一件小事责骂妻子"},{"label":"B","content":"乙上课时受到老师批评，心中憋闷，下课后在学校超市把货架上的方便面全部捏碎"},{"label":"C","content":"丙和邻居发生冲突时被迫忍气吞声，后趁天黑将邻居家的汽车车胎扎漏"},{"label":"D","content":"丁路过树下时被树上的鸟粪砸中，感到很生气，轰走了上来乞食的流浪猫"}],"answer":"C","explanation":"替代性攻击定义的关键信息：将怒气发泄转移到另外的“替罪羊”身上。<br>A项，将对老板的不满转移到妻子身上，符合定义。<br>B项，将对老师的憋闷转移到方便面身上，符合定义。<br>C项，和邻居发生冲突后扎漏了邻居家的车胎，不涉及将怒气转移，不符合定义。<br>D项，将对鸟的愤怒转移到流浪猫的身上，符合定义。","no":102},{"id":"1718789647855","type":"single","material":"","stem":"价值的条件化过程是指个体的价值评价建立在他人评价的基础上，以他人的价值规范为标准，而非根据自身的满足感进行评价。<br>根据上述定义，下列不属于价值的条件化过程的是：","options":[{"label":"A","content":"一个学生受到老师误解，虽然内心愤怒和委屈，但从小受教导应当尊重老师，认为即使受到误解，也不应该指责老师"},{"label":"B","content":"一个男孩把玻璃杯摔地上，他觉得很好玩，其父母因此不满并教育他不能随意摔东西，为让父母高兴，男孩学会不再摔东西"},{"label":"C","content":"一个婴儿突然哭了，母亲听到后立刻给他换上干净清洁的纸尿裤，并给他喂奶，婴儿停止哭闹，不久后酣然入睡"},{"label":"D","content":"一个身材适中的女孩，其男友认为她很胖，于是女孩开始每天通过节食的方式进行减肥，即使饿了也不多进食"}],"answer":"C","explanation":"价值的条件化过程定义的关键信息：以他人的价值规范为标准。<br>A项，以从小受到的教导为标准，体现了以他人的价值规范为标准，符合定义。<br>B项，以父母的教育为标准，体现了以他人的价值规范为标准，符合定义。<br>C项，体现的是婴儿的生理需求，不涉及价值标准，不符合定义。<br>D项，以男朋友的观点为标准，体现了以他人的价值规范为标准，符合定义。","no":103},{"id":"1718789647856","type":"single","material":"","stem":"姻亲是指男女结婚后，配偶之一和另一方的亲属之间形成的亲属关系。<br>根据上述定义，下列不属于姻亲的是：","options":[{"label":"A","content":"张明和王梅结婚后，王梅的弟弟与张明之间"},{"label":"B","content":"王峰和苏洁结婚后，王峰的弟弟与苏洁的妹妹之间"},{"label":"C","content":"吴凯和马月结婚后，吴凯与马月的父亲母亲之间"},{"label":"D","content":"赵天和刘蕾结婚后，刘蕾的二姨与赵天之间"}],"answer":"B","explanation":"姻亲定义的关键信息：配偶之一和另一方的亲属之间。<br>A项，王梅的弟弟与张明，张明是配偶之一，王梅弟弟为另一方的亲属，属于姻亲。<br>B项，王峰的弟弟与苏洁的妹妹均不属于“配偶之一”,不符合定义。<br>C项，吴凯与马月的父亲母亲，吴凯是配偶之一，马月父母亲为另一方的亲属，属于姻亲。<br>D项，刘蕾的二姨与赵天，赵天是配偶之一，刘蕾二姨为另一方的亲属，属于姻亲。","no":104},{"id":"1718789647857","type":"single","material":"","stem":"拧巴立场是指一个人的思想认识和行为方式表现出前后相忤、不一致的情形。根据上述定义，下列不属于拧巴立场的是：","options":[{"label":"A","content":"王老汉一向觉得医生工作辛苦、责任大，不是一个好职业，可后来孙子填报高考志愿时，老人又斩钉截铁地说：“一定要考医学院当医生!”"},{"label":"B","content":"小李一向对办事情要找关系送礼深恶痛绝，当发现自己晋升职称有困难时，他首先想到的就是想办法请朋友帮忙"},{"label":"C","content":"郝老师得知学生小梅的父母都是某知名高校的美术老师，觉得小梅可能有画画的天分，但当她看到小梅交来的绘画作业时，却大跌眼镜，彻底颠覆了自己的想法"},{"label":"D","content":"小潘对特牌车一直愤愤不平，有一次他偶然坐在里面兜了一圈，当时就觉得无比痛快和神气，过后还不时对同事谈起那时的情景"}],"answer":"C","explanation":"：拧巴立场定义的关键信息：思想认识和行为方式前后相忤。<br>A项，王老汉一向觉得医生不是一个好职业，却让孙子一定要考医学院当医生，王老汉的思想认识和行为方式前后相忤，属于拧巴立场。<br>B项，小李一向对找关系送礼办事深恶痛绝，但自己遇到事情时却还是找关系，小李的思想认识和行为方式前后相忤，属于拧巴立场。<br>C项，郝老师之前觉得小梅可能有画画的天分，这只是她的预想和假设，见到小梅的绘画作业后，推翻了原先的预想，并非思想认识和行为方式不一致，不符合定义。<br>D项，小潘对特牌车一直愤愤不平，但坐在里面却觉得无比痛快和神气，小潘的思想认识和行为方式前后相忤，属于拧巴立场。","no":105},{"id":"1718789647858","type":"single","material":"","stem":"构形歧义是指语句和语法结构不确定导致所反映的命题含义不确定，可以解释成不同的命题，从而形成构形歧义。<br>根据上述定义，下列属于构形歧义的是：","options":[{"label":"A","content":"他看着妈妈吃饭"},{"label":"B","content":"1、9为奇数，所以，1+9是奇数"},{"label":"C","content":"奇迹不会发生"},{"label":"D","content":"强权即公理"}],"answer":"A","explanation":"构形歧义定义的关键信息：语法结构不确定导致含义不确定。<br>A项，根据不同的语法结构可以有两种理解：①他一边吃饭一边看着妈妈；②他的妈妈在吃饭，他在一旁看着。因此该项属于构形歧义。<br>B、C、D三项，句子的含义都是确定的，并没有歧义，不符合定义。","no":106},{"id":"1718789647859","type":"single","material":"","stem":"志愿服务是指不以盈利为目的，基于利他动机，自愿贡献知识、体力、技能等，促进社会和谐与进步的服务活动。<br>根据上述定义，下列不属于志愿服务的是：","options":[{"label":"A","content":"张老师每年春节前都组织“献爱心送温暖”活动，为孤寡老人打扫房间，送上粮油"},{"label":"B","content":"某居民小区常有穿着白大褂的人为老年人免费量血压，热情推销保健品"},{"label":"C","content":"某地遭强台风袭击后，不少人士自行驾车帮助运送救灾物资"},{"label":"D","content":"某大学韩教授经常为所在社区居民作公益专题讲座，引导居民提高生活质量"}],"answer":"B","explanation":"志愿服务定义的关键信息：不以盈利为目的。<br>A项，为孤寡老人打扫房间，送上粮油，是不以盈利为目的的服务活动，属于志愿服务。<br>B项，量血压是免费的，但却是为了推销保健品，最终是以盈利为目的，不符合定义。<br>C项，台风袭击后，不少人士自行驾车帮助运送救灾物资，是不以盈利为目的的服务活动，属于志愿服务。<br>D项，韩教授为居民作公益专题讲座，是不以盈利为目的的服务活动，属于志愿服务。","no":107},{"id":"1718789647860","type":"single","material":"","stem":"二次事故是指在原有的医疗事故、煤矿安全事故、交通事故等基础上，由自然不可抗力、救援方的疏忽或当事人的错误操作引起的事故。<br>根据上述定义，下列不属于二次事故的是：","options":[{"label":"A","content":"李某在高速公路上与前车追尾，他匆忙下车捡拾自己小车洒落的物品，被后方驶来的汽车撞击身亡"},{"label":"B","content":"刘某突发急性阑尾炎入院，医生在阑尾切除手术结束时将一块止血棉遗留在刘某腹腔内没有取出，导致刘某再次入院"},{"label":"C","content":"某市连日暴雨引发的洪水及泥石流导致25人丧生，部分房屋被毁，数千人被迫离开家园"},{"label":"D","content":"某煤矿井下渗水，矿工私自启动水泵抽水，拉闸时产生火花，致井内瓦斯爆炸，造成4人当场死亡"}],"answer":"C","explanation":"二次事故定义的关键信息：在原有事故的基础之上，由自然不可抗力等原因引起的事故。<br>A项，是在原有交通事故的基础上，由当事人的错误操作引起的事故，属于二次事故。<br>B项，是在原有医疗事故的基础上，由救援方的疏忽引起的事故，属于二次事故。<br>C项，洪水及泥石流造成损害，仅涉及原有事故，并没有多次事故发生，不符合定义。<br>D项，是在原有煤矿安全事故的基础上，由当事人的错误操作引起的事故，属于二次事故。","no":108},{"id":"1718789647861","type":"single","material":"","stem":"差异化战略是指为使企业产品、服务、企业形象等与竞争对手有明显的区别，以获得竞争优势为目的而采取的战略。<br>根据上述定义，下列属于差异化战略的是：","options":[{"label":"A","content":"某家电企业在国内家电业独占鳌头，为绕过贸易壁垒，进一步打开国外市场，正积极开展资本和技术输出，在海外建立制造和销售基地"},{"label":"B","content":"面对日益激烈的竞争环境，某跨国企业决定剥离不盈利的个人电脑业务，主攻旗下高利润率的智能计算和服务器业务"},{"label":"C","content":"随着楼市调控政策的不断出台，某房产龙头企业积极调整战略，逐步形成了对旅游、餐饮、物流等行业的多元化产业布局"},{"label":"D","content":"在国内手机厂商大打价格战时，某手机品牌始终秉持“只做最好的产品”这一理念，依靠技术和产品设计的优势，坚持走高端路线"}],"answer":"D","explanation":"差异化战略的定义要点：①使企业产品、服务、企业形象等与竞争对手有明显的区别；②获得竞争优势。<br>A项，该企业是为了进一步打开国外市场，并未体现使自己与竞争对手有明显的区别，不符合要点①。<br>B项，该企业做出这样的改变是为了在激烈的竞争环境中占据优势，并未体现使自己与竞争对手有明显的区别，不符合要点①。<br>C项，说的是该企业的产业布局，并未体现使自己与竞争对手有明显的区别，不符合要点①。<br>D项，该品牌始终秉持自己的理念，坚持走高端路线，不与其他厂商打价格战，体现了使自己与竞争对手有明显的区别，符合要点①;该品牌具有技术和产品设计优势，符合要点②。该项属于差异化战略。","no":109},{"id":"1718789647862","type":"single","material":"","stem":"房地产经纪是以提取佣金为经济特征，为促成他人房地产交易，而从事房地产买卖交换、租赁、置换等信息提供、信托劳务、居间代理等业务的经济活动。<br>根据上述定义，下列属于房地产经纪的是：","options":[{"label":"A","content":"作为社区工作者，张大妈经常为小区内买卖房屋的人牵线搭桥"},{"label":"B","content":"某网站设置房产专栏，免费为发布租房卖房信息的会员提供服务"},{"label":"C","content":"某中介公司接受一房地产开发商的委托，销售其新开发的商品房"},{"label":"D","content":"物业顾问小李通过自己的房产人脉关系买到一套性价比较高的房子"}],"answer":"C","explanation":"房地产经纪定义的关键信息：以提取佣金为经济特征。<br>A项，为小区内的人牵线搭桥，不符合定义。<br>B项，免费提供服务，也不收取佣金，不符合定义。<br>C项，中介公司接受委托销售新房符合定义。<br>D项，自己买房，不符合定义。","no":110},{"id":"1718789647863","type":"single","material":"","stem":"感知综合障碍是指病人在感知某一现实事物时，作为一个客观存在的整体来说是正确的，但对该事物的个别属性，如大小、形状、颜色、空间距离等产生与该事物不相符合的感知。<br>根据上述定义，下列属于感知综合障碍的是：","options":[{"label":"A","content":"王某由于沉迷于游戏而经常出现幻觉，眼前浮现游戏中打斗的场景"},{"label":"B","content":"张某最近一段时间以来经常觉得正在摆动着的钟摆停止了摆动"},{"label":"C","content":"由于眼睛高度近视，李某在大街上经常会认错人，心里非常苦闷"},{"label":"D","content":"孙某对颜色的辨别能力差，经医生检查发现这是色弱的表现"}],"answer":"B","explanation":"感知综合障碍的定义要点：①作为一个客观存在的整体来说是正确的；②对个别属性产生不符合该事物的感知。<br>A项，出现幻觉不符合要点①。<br>B项，符合感知综合障碍的定义。<br>C项，高度近视不符合要点①。<br>D项，色弱也不符合要点①。","no":111},{"id":"1718789647864","type":"single","material":"","stem":"事件营销是指企业整合自身的资源，通过借用社会关注焦点，策划富有创意的活动或事件，使之成为大众关心的话题、议题，从而吸引媒体的报道与消费者的参与，进而达到提升企业形象或销售产品的目的。<br>根据上述定义，下列不属于事件营销的是：","options":[{"label":"A","content":"某电视剧续集投放之前，影视公司将续集的拍摄花絮放在网上，网友大量点击。该续集播出后收视率很高"},{"label":"B","content":"某选秀节目的策划团队有意地制造一些参赛者的“绯闻”,吸引了广大媒体报道，使该节目收视率在短期内迅速提高"},{"label":"C","content":"某科技公司新开产品专营店，欢迎客户进店体验，店员帮助讲解功能和应用，赢<br>得良好的口碑，提升了产品销量"},{"label":"D","content":"某企业在M市受灾后第一时间捐出巨额善款，当地媒体纷纷报道，较好地提升了企业形象"}],"answer":"C","explanation":"事件营销的定义要点：①借用社会关注焦点；②策划富有创意的活动或事件；③吸引媒体的报道和消费者的参与；④达到提升企业形象或销售产品的目的。<br>A项，将续集的花絮放在网上，吸引了消费者的注意，符合事件营销的定义。<br>B项，制造绯闻吸引媒体报道，使收视率提高，也属于事件营销。<br>C项，开新店不符合要点①②,通过店员讲解获得良好口碑不符合要点③,因此不属于事件营销。<br>D项，给受灾地区捐款，是社会关注焦点，吸引媒体报道，提升企业形象，符合定义。","no":112},{"id":"1718789647865","type":"single","material":"","stem":"传媒接近权是指普通公民或社会组织享有的，有法律规定、认可和保障的，为公开发表、传递自己的意见、主张、观点、情感等内容而使用各种媒介手段与方式，不受任何他人或组织非法干涉、限制或侵犯的权利。<br>根据上述定义，下列不涉及传媒接近权的是：","options":[{"label":"A","content":"政府召开新闻发布会"},{"label":"B","content":"企业在电视上播出产品广告"},{"label":"C","content":"某学者在杂志上发表自己的学术观点"},{"label":"D","content":"某人在报纸上刊登寻找失物的酬谢广告"}],"answer":"A","explanation":"传媒接近权的定义主体是“普通公民或社会组织”。A项，政府不符合定义主体，不涉及传媒接近权。B项中的企业在电视上播广告、C项中的在杂志上发表学术观点和D项中的在报纸上刊登寻物启事，均符合传媒接近权的定义。","no":113},{"id":"1718789647866","type":"single","material":"","stem":"职业基因是指每个人的职业方向都与自己的某种气质相匹配，这种气质是在人际交往中潜移默化而形成的一种带有强烈个人色彩的心理修养。<br>根据上述定义，下列现象中符合职业基因理论的是：","options":[{"label":"A","content":"小明的父母都是教师，最终小明也选择了教师职业"},{"label":"B","content":"小红从小爱看动画片，长大后成为一名动漫设计师"},{"label":"C","content":"性情开朗、活泼好动的小丁应聘为某商城销售人员"},{"label":"D","content":"快言快语的小李毕业当了两年医生后变得慢条斯理"}],"answer":"C","explanation":"职业基因理论定义的关键信息：与自己的某种气质相匹配。<br>A项，小明受父母的影响也选择了教师职业，并未体现与自己的气质相匹配，排除。<br>B项，小红因为爱看动画片而成为动漫设计师，并未体现与自己的气质相匹配，排除。<br>C项，小丁应聘为销售人员，这与他性情开朗、活泼好动的气质相匹配，符合职业基因理论。<br>D项，小李当上医生之后变得慢条斯理，这与他快言快语的气质并不匹配，排除。","no":114},{"id":"1718789647867","type":"single","material":"","stem":"卡瑞尔公式是指唯有强迫自己面对最坏的情况，在精神上先接受它以后，才会使我们处在一个可以集中精力解决问题的地位上。<br>根据上述定义，下列选项涉及卡瑞尔公式的是：","options":[{"label":"A","content":"一商人因经营不善而欠下一大笔债务，心灰意冷地来到亲戚的农庄，想在此度过余生，却在瓜农的鼓励下，最终重新崛起"},{"label":"B","content":"A君炒股被套十分苦闷，后来想通了，学习当鸵鸟，不看股票，专心工作，几年后，他事业取得成功"},{"label":"C","content":"一个卖花老太太衣着破旧却满是喜悦，她说：“耶稣星期五被钉在十字架上死去，可三天后不就是复活节了吗?所以我总是心怀喜悦。”"},{"label":"D","content":"阿Q与小D打架吃亏，心想：“我总算被儿子打了，现在这世界真不像样，儿子居然打起老子<br>来了。”于是他心满意足，俨然胜利了似的"}],"answer":"A","explanation":"卡瑞尔公式的定义要点：①面对最坏的情况；②精神上先接受它；③解决问题。<br>A项，商人经营不善后来到亲戚的农庄，想在此度过余生，是在精神上接受了最坏的情况，重新崛起是解决了问题，符合上述所有要点。<br>B项，炒股被套，便专心工作，取得事业成功，但是炒股被套的问题并没有得到解决，不符合要点③。<br>C项，衣着破旧却满是喜悦，并没有体现出在精神上接受了最坏的情况，不符合要点②。<br>D项，是被打之后自我安慰，实际上并没有解决问题，不符合要点③。","no":115},{"id":"1718789647868","type":"single","material":"","stem":"行政比例原则是指行政主体实施行政行为应兼顾行政目标的实现和相对人权益的保护。如果初始行政目标可能对相对人权益造成某种不利影响，应使这种不利影响限制在尽可能小的范围和限度内，保持二者处于适度的比例。<br>根据上述定义，下列选项符合行政比例原则的是：","options":[{"label":"A","content":"王某因在商业区摆地摊，被城市管理部门以无证经营为由罚款5万元"},{"label":"B","content":"谭某在批准建设的三层楼房上加盖二层，被责令拆除加盖的二层楼房"},{"label":"C","content":"马某醉酒驾车，酒精含量为300mg/100ml,被处3个月拘役，缓刑一年"},{"label":"D","content":"张某和李某互殴，张某将李某打成轻微伤，被处罚款500元并拘留15天"}],"answer":"B","explanation":"行政比例原则的定义要点：①行政行为；②不利影响；③尽可能小；④适度的比例。<br>A项，摆地摊罚款5万元，属于罚款过重，不符合要点④。<br>B项，违规加盖二层，被责令拆除，既实现了初始行政目标，又将不利影响限制在尽可能小的范围和限度内，符合行政比例原则。<br>C项，醉酒驾车被处3个月拘役，缓刑一年，这属于刑事处罚，而非行政处罚，因此其不属于行政行为，不符合要点①。<br>D项，将人打成轻微伤被处罚款500元并拘留15天，行政拘留15天是拘留处罚的上限，并没有将不利影响限制在尽可能小的范围和限度内，不符合要点③。","no":116},{"id":"1718789647869","type":"single","material":"","stem":"首因效应是指个体在社会认知过程中，通过第一印象最先输入的信息对客体以后的认知产生显著的影响作用。第一印象作用最强，持续的时间也长，比以后得到的信息对于事物整个印象产生的作用更强。<br>根据上述定义，下列首因效应没有发挥作用的是：","options":[{"label":"A","content":"金融行业从业人员，一般着深色套装，给人专业和严谨的印象"},{"label":"B","content":"小张在面试中表现突出，后公司的人力资源部发现小张的简历上存在错别字而取消了录用他的计划"},{"label":"C","content":"已过而立之年的王先生频频相亲却没有结果，据和他有过一面之交的金小姐说，王先生“以我为中心”的夸夸其谈，令她很反感"},{"label":"D","content":"刚刚毕业的小张在找工作的过程中屡屡碰壁，后经咨询专业人士才得知因她染了一头红色的头发，而给人不够成熟稳重的感觉"}],"answer":"B","explanation":"首因效应强调的是第一印象的重要性，先输入的信息对于事物整体印象产生的作用更强。<br>A项，金融行业从业人员着深色套装，是为了给别人留下专业、严谨的第一印象，体现了首因效应。<br>B项，面试时表现突出是第一印象，后来发现简历上存在错别字而取消了录用他的计划，是后来得到的信息影响了第一印象，此时首因效应没有发挥作用，当选。<br>C项，王先生给别人的第一印象是“以我为中心”,这样的第一印象使得王先生频频相亲却没有结果，体现了首因效应。<br>D项，小张染了一头红色的头发，在找工作的过程中给人的第一印象是不够成熟稳重，这样的第一印象使得她屡屡碰壁，体现了首因效应。","no":117},{"id":"1718789647870","type":"single","material":"","stem":"生态补偿是在经济社会发展中对生态功能和质量所造成损害的一种补助，是为了提高受损地区的环境质量或者用于创建新的具有相似生态功能和环境质量的区域。生态补偿在原则上适用谁破坏谁补偿。<br>根据上述定义，下列属于生态补偿的是：","options":[{"label":"A","content":"某建筑公司在甲地破坏1公顷森林，在乙地重新营造1公顷森林"},{"label":"B","content":"张某为扩大土豆种植面积，租用邻居耕地20亩，经商议，租赁费为每年2万元"},{"label":"C","content":"山东省根据各市环境空气质量情况发放奖金，其中聊城空气质量考核得分最高，获奖950万元"},{"label":"D","content":"李某非法占用基本农田5亩，被以非法占用农用地罪判处有期徒刑1年6个月，并处罚金1.5万元"}],"answer":"A","explanation":"生态补偿的定义要点：①经济社会发展对生态功能和质量造成了损害；②为了提高受损地区的环境质量或者用于创建相似的生态功能和环境质量的区域。<br>A项，某建筑公司在甲地破坏1公顷森林，对生态功能和质量造成了损害，符合要点①;该公司又在乙地重新营造1公顷森林，是为了创建相似的生态功能和环境质量的区域，符合要点②。该项属于生态补偿。<br>B项，张某为扩大土豆种植面积而租用邻居的耕地，并没有对生态功能和质量造成损害，不符合要点①;张某给邻居每年2万元是租赁费，不符合要点②。<br>C项，根据各市环境空气质量情况发放奖金，并未体现对生态功能和质量造成损害，不符合要点①;聊城获得950万元奖金也并非补偿，不符合要点②。<br>D项，李某非法占用基本农田，并未体现对生态功能和质量造成损害，不符合要点<br>①;1.5万元是对李某非法占用农田行为的处罚，而非为了补偿受损地区的环境质量，不符合要点②。","no":118},{"id":"1718789647871","type":"single","material":"","stem":"国际经济法是调整国家、国际组织、法人、自然人从事跨国经济交往活动所产生的关系的国际法和国内法的总称。<br>根据上述定义，下列说法错误的是：","options":[{"label":"A","content":"国际经济法既包括国际法也包括国内法"},{"label":"B","content":"跨国婚姻关系不属于国际经济法调整的对象"},{"label":"C","content":"国际经济法包含了国家之间关于海洋领土划界的协议"},{"label":"D","content":"跨国经济交往活动的主体有国家、国际组织、法人和自然人"}],"answer":"C","explanation":"国际经济法的定义要点：①国家、国际组织、法人、自然人；②从事跨国经济交往活动；③包括国际法和国内法。<br>A项，体现了要点③,说法正确。<br>B项，跨国婚姻关系不属于经济交往活动，不符合要点②,因此不属于国际经济法调整的对象，说法正确。<br>C项，海洋领土划界不属于经济交往活动，不符合要点②,因此国际经济法中并不包含关于海洋领土划界的协议，说法错误。<br>D项，体现了要点①,说法正确。","no":119},{"id":"1718789647872","type":"single","material":"","stem":"垂直绿化指的是利用攀援植物向空中生长进行纵向绿化的一种方式，以期达到在有限面积内最大限度地利用空气和阳光来提高绿化的效率。<br>根据上述定义，下列涉及垂直绿化的是：","options":[{"label":"A","content":"爬山虎爬满了墙头和屋顶"},{"label":"B","content":"松树林从山脚一直延伸到山顶"},{"label":"C","content":"利用巴根草匍匐攀援的特性，人们在沙漠中逐渐开拓出一片绿洲"},{"label":"D","content":"在丘陵地区，人们常使用飞机从空中播种的方式对山地进行绿化"}],"answer":"A","explanation":"垂直绿化定义的关键信息：利用攀援植物向空中生长进行纵向绿化。<br>A项，爬山虎是攀援植物，利用爬山虎进行纵向绿化，符合定义。<br>B项，松树并非攀援植物，不符合定义。<br>C项，巴根草的特性是“匍匐攀援”,并非向空中生长，无法实现纵向绿化，不符合定义。<br>D项，用飞机从空中播种，并非利用攀援植物进行纵向绿化，不符合定义。","no":120},{"id":"1718789647873","type":"single","material":"","stem":"狭义的同行评议，指作者投稿以后，由刊物主编或纳稿编辑邀请具有专业知识或造诣的学者，评议论文的学术和文字质量，提出意见和做出判定，主编按评议的结果决定是否适合在本刊发表。<br>根据上述定义，以下属于狭义的同行评议的是：","options":[{"label":"A","content":"张教授在学术杂志上发表了一篇研究论文，不久后很多同领域的学者发来意见，对该研究的质量提出质疑"},{"label":"B","content":"研究生小李提交毕业论文后，学术委员会邀请国内相关专业的教授对该论文的学术水平进行评估"},{"label":"C","content":"李医生提出一个新的手术思路，某期刊编辑将他的投稿论文发给多位外科专家，专家们认为很有创新性"},{"label":"D","content":"张先生将自我保健心得撰文投稿到某心理健康杂志，编辑认为该文不属于心理领域，不宜在本刊发表"}],"answer":"C","explanation":"狭义的同行评议定义的关键信息：作者投稿后由主编或编辑邀请业内学者，评议论文的质量，提出意见和做出判定，主编按评议结果决定是否发表。<br>A项，张教授已经在学术杂志上发表了论文，而狭义的同行评议说的是论文发表之前的过程，不符合定义。<br>B项，研究生提交毕业论文，并非在刊物上进行发表，不符合定义。<br>C项，李医生向某期刊投稿，期刊编辑将他的论文给业内专家评议，专家对他的论文做出判定，认为很有创新性，期刊编辑可以根据这一评议结果决定是否发表，符合定义。<br>D项，杂志编辑并未把张先生的投稿交由业内专家评议，而是自己做出了判断，认为他的文章不属于心理领域，不宜发表，不符合定义。","no":121},{"id":"1718789647874","type":"single","material":"","stem":"纯粹接触效应也被称之为只看效应，是指个体接触一个刺激的次数越频繁，对该刺激就越喜欢的现象。纯粹接触效应是影响个体和社会偏好的一种非常简单但却是非常重要的方式。<br>根据上述定义，以下符合纯粹接触效应的是：","options":[{"label":"A","content":"小秦喜欢穿颜色鲜艳的衣服，张教授上课时常能注意到她。硕士研究生面试时，在条件类似的几个学生中，张教授最终选择了小秦"},{"label":"B","content":"小柯想给妈妈买一份营养品，面对琳琅满目的营养品，他选择了在电视上看到的那个以品质安全著称的品牌"},{"label":"C","content":"小芳经人介绍认识了高大帅气的小李，一见钟情，随着两人交往逐渐深入，小芳对小李越来越喜欢"},{"label":"D","content":"小霞看到自己喜欢的明星穿着某品牌的衣服，作为“铁杆粉丝”,她对这个品牌也越来越喜欢"}],"answer":"A","explanation":"纯粹接触效应定义的关键信息：接触某一刺激的次数越频繁，对该刺激就越喜欢，从而产生偏好。<br>A项，由于小秦喜欢穿颜色鲜艳的衣服，张教授在上课时多次注意到她，所以在面试中对小秦产生偏好，在条件类似的几个学生中选择了小秦，符合定义。<br>B项,小柯面对众多营养品,出于安全考虑而选择了这一品牌,并未体现由多次接触而产生偏好,不符合定义。<br>C项,小芳对小李一见钟情,即一开始就产生了偏好,而不是接触次数多才产生的偏好,不符合定义。<br>D项,小霞因为自己喜欢的明星穿着某品牌衣服而喜欢这一品牌,本身已存在偏好而不是接触次数多才产生的偏好,不符合定义。","no":122},{"id":"1718789647875","type":"single","material":"","stem":"非职务发明是指发明人利用自己的时间、资金、设备等物质条件或技术条件完成的发明创造。非职务发明的专利申请权归发明人或设计人。<br>根据上述定义，以下属于非职务发明的是：","options":[{"label":"A","content":"时装设计师海燕在读到“道由白云尽，春与青溪长”时受到启发，设计了清溪系列的春装，该春装成为公司的明星产品"},{"label":"B","content":"老张是一名植物学家，农科院退休之后，归隐田间，摸索出大棚种植灵芝的先进技术"},{"label":"C","content":"建筑师小王是一名考古发烧友，假日里相约好友考古时，竟无意间发现明代古城墙遗址"},{"label":"D","content":"化学家马克对研究野生菌类充满兴趣，闲暇之余在深山发现了名贵菌株，并将其命名为马克菇"}],"answer":"B","explanation":"非职务发明定义的关键信息：利用自己的时间、资金、设备等进行发明创造。<br>A项，时装设计师海燕设计春装属于其工作范围之内的事情，并未体现利用自己的时间、资金、设备进行发明创造，不符合定义。<br>B项，老张退休后摸索出大棚种植灵芝的先进技术，是利用自己的时间、资金、设备进行发明创造，符合定义。<br>C项，小王发现明代古城墙遗址，并非进行发明创造，不符合定义。<br>D项，马克发现名贵菌株，并非进行发明创造，不符合定义。","no":123},{"id":"1718789647876","type":"single","material":"","stem":"符号现象是指表意上没有相关性的甲、乙两个事物，当我们用甲事物代表乙事物时，甲事物就可以视为乙事物的符号。<br>根据上述定义，下列不属于符号现象的是：","options":[{"label":"A","content":"消防车的警笛声"},{"label":"B","content":"医疗机构使用的十字标记"},{"label":"C","content":"法院大门上雕刻的天平图案"},{"label":"D","content":"体育比赛裁判员的哨声"}],"answer":"C","explanation":"符号现象是指表意上没有相关性的甲、乙两个事物，当我们用甲事物代表乙事物时，甲事物就可以视为乙事物的符号。<br>A项，警笛常代表消防车，在表意上两者没有相关性，属于符号现象。<br>B项，十字标记常代表医疗机构，在表意上两者没有相关性，属于符号现象。<br>C项，“法院”与“天平”本就具有相关性，因为天平象征着公平，才会与法院联系起来，只是为了表明法院是公平的，而非用天平来代表法院，不属于符号现象。<br>D项，哨声常代表体育比赛的裁判员，在表意上两者没有相关性，属于符号现象。","no":124},{"id":"1718789647877","type":"single","material":"","stem":"人耳对一个声音的感受性会因另一个声音的存在而发生改变。一个声音能被人耳听到的最低值会因另一声音的出现而提高，这种现象就是听觉掩蔽。<br>根据上述定义，下列符合听觉掩蔽的是：","options":[{"label":"A","content":"吵闹的课间，老师得大声说话，同学们才能听到"},{"label":"B","content":"长时间戴耳机听音乐，会觉得听到的音量逐渐变小"},{"label":"C","content":"人类无法听到蝙蝠等动物发出的超声波"},{"label":"D","content":"在安静的房间内，我们能够听到闹钟“滴答”的声音"}],"answer":"A","explanation":"根据题干定义，听觉掩蔽的发生必须要有两个声音存在，并且一个声音能被人耳听到的最低值会因另一声音的出现而提高。<br>A项，吵闹的课间老师得大声说话才能被听到，对于老师的话来说，吵闹的课间是另一个声音，符合“人耳对一个声音的感受性会因另一个声音的存在而发生改变”,老师大声说话才能被听到符合“被人耳听到的最低值会因另一个声音的出现而提高”,符合定义。<br>B项，长时间戴耳机听音乐，音量逐渐变小，不存在另一个声音的存在对其产生影响，不符合定义。<br>C项，无法听到超声波，不存在另一个声音对其产生影响，不符合定义。<br>D项，听到闹钟“滴答”的声音，不存在另一个声音对其产生影响，不符合定义。","no":125},{"id":"1718789647878","type":"single","material":"","stem":"间接正犯又称为间接实行犯，是指利用他人为道具而实施犯罪的实行行为，利用者通过支配被利用者的工具行为实现自己的犯罪意图。利用者与被利用者不构成共同犯罪。它包括以下两种情况：一是利用无刑事责任能力人犯罪；二是利用他人过失或不知情的行为犯罪。<br>根据上述定义，下列甲的行为属于间接正犯的是：","options":[{"label":"A","content":"甲挑唆乙与丙的关系，致使乙一怒之下将丙打成重伤。甲、乙、丙均为完全刑事责任能力人"},{"label":"B","content":"甲教唆精神病人乙用刀砍伤与其素有仇怨的丙。甲、丙为完全刑事责任能力人，乙为无刑事责任能力人"},{"label":"C","content":"甲派员工乙殴打一直欠钱不还的丙，并允诺给其好处，乙随后将丙打伤。甲、乙、丙均为完全刑事责任能力人"},{"label":"D","content":"甲让自己尚未成年的孩子乙诬告丙，未想到乙捏造的事实正是丙客观存在的事实。甲、丙为完全刑事责任能力人，乙为无刑事责任能力人"}],"answer":"B","explanation":"间接正犯的定义要点：①利用他人为道具而实施犯罪的实行行为；②利用者和被利用者不构成共同犯罪；③包括两种情况：利用无刑事责任能力人犯罪、利用他人过失或不知情的行为犯罪。<br>A项，甲利用乙实施犯罪，但乙是有刑事责任能力的人，不符合题干中的第一种情况；犯罪行为是在乙故意或知情的情况下发生的，不符合题干中的第二种情况。<br>B项，甲利用乙实施犯罪，且乙是无刑事责任能力人，符合定义和题干中的第一种情况。<br>C项，甲利用乙实施犯罪，但乙是有刑事责任能力的人，不符合题干中的第一种情况；犯罪行为是在乙故意或知情的情况下发生的，不符合题干中的第二种情况。<br>D项，甲意图利用乙实施犯罪，但乙捏造的事实正是丙客观存在的事实，因此不构成诬告，不符合题干中的任一情况。","no":126},{"id":"1718789647879","type":"single","material":"","stem":"经济文盲指的是被很多经济学名词弄得满头大汗不知其意的人们，他们的典型特色是容易盲从，专家说啥信啥，缺乏独立思考，即使专家说错了他们也会继续相信。<br>根据上述定义，下列涉及经济文盲的是：","options":[{"label":"A","content":"某“专家”在其出版的书中宣扬“绿豆治百病大法”,引发市场绿豆涨价"},{"label":"B","content":"一天电视节目里某娱乐明星说低钠盐好处多，第二天一些超市的低钠盐被一抢而空"},{"label":"C","content":"为了通过某资格考试，小王死记硬背了“边际效益”等很多经济学名词，但是他并没有发现复习资料中其实有许多错误"},{"label":"D","content":"小王被《重金属攻略》一书中的“浮动盈亏”等概念弄糊涂了，但是看到书中宣传的重金属盈利前景，还是迅速参与了交易"}],"answer":"D","explanation":"经济文盲的定义要点：①被经济学名词弄得满头大汗不知其意；②容易盲从，缺乏独立思考。<br>A项，“绿豆治百病大法”并不是经济学名词，不符合要点①。<br>B项，“某娱乐明星说低钠盐好处多”不涉及经济学名词，不符合要点①。<br>C项，小王只是在死记硬背，并没有体现出被经济学名词弄得满头大汗不知其意，不符合要点①。<br>D项，被书中的经济学概念弄糊涂了，符合要点①;在糊涂的情况下，看到书中的宣传就盲目参与交易，符合要点②。","no":127},{"id":"1718789647880","type":"single","material":"","stem":"回弹效应是指通过技术进步提高能源使用效率，节约了能源，但技术进步的同时也会促进经济规模的扩大，对能源产生新的需求，从而部分甚至完全地抵消所节约的能源。<br>根据上述定义，下列选项可以有效控制回弹效应的是：","options":[{"label":"A","content":"发动机效率提升降低了行车成本，更多人选择以车代步"},{"label":"B","content":"厂商进一步提高能源效率，利润增加，生产出更多产品"},{"label":"C","content":"太阳能热水器热销，慢慢取代传统电热水器"},{"label":"D","content":"现在越来越多的消费者购买节能型家用电器"}],"answer":"C","explanation":"回弹效应定义的关键信息：节约能源的同时也会促进经济规模的扩大，对能源产生新的需求。<br>A项，“更多人选择以车代步”说明促进了经济规模的扩大，对能源产生新的需求，无法有效控制回弹效应，排除。<br>B项，“生产出更多产品”说明促进了经济规模的扩大，对能源产生新的需求，无法有效控制回弹效应，排除。<br>C项，太阳能热水器取代传统电热水器可以节约电能，以太阳能的使用取代电能的使用，并不会对能源产生新的需求，可以有效控制回弹效应。<br>D项，“越来越多的消费者购买”说明促进了经济规模的扩大，对能源产生新的需求，无法有效控制回弹效应，排除。","no":128},{"id":"1718789647881","type":"single","material":"","stem":"赤潮，又称“红潮”。赤潮是海洋中一种或多种微小浮游植物、原生动物或细菌，在一定的环境条件下突发性迅速增殖或聚集，引起一定海域范围在一段时间内变色的自然生态现象。赤潮是一种海洋生物灾害。通常水体颜色因赤潮生物的数量、种类而呈红、黄、绿和褐色等。<br>根据上述定义，以下最有可能属于赤潮现象的是：","options":[{"label":"A","content":"我国长江中游多次发生水体变蓝现象"},{"label":"B","content":"位于尼泊尔博克拉市区的贝格纳斯湖湖水曾变红"},{"label":"C","content":"日本濑户内海、有明海等水域频繁发生水体变红"},{"label":"D","content":"美国密西西比河部分水域发生洪灾，水中含大量泥沙"}],"answer":"C","explanation":"赤潮的定义要点：①海洋中；②微小浮游植物、原生动物或细菌突发性迅速增殖或聚集；③海水呈现红、黄、绿和褐色等。<br>A项，长江不属于海洋，不符合要点①。<br>B项，贝格纳斯湖不属于海洋，不符合要点①。<br>C项，日本的濑户内海、有明海属于海洋，水体变红属于水体变色，符合定义。<br>D项，密西西比河不属于海洋，不符合要点①;含有大量泥沙并非微生物大量繁殖造成的水体变色，不符合要点②③。","no":129},{"id":"1718789647882","type":"single","material":"","stem":"网络小说，是指由作者创作并首次在网络上发表，并以连载模式形成的小说。和传统小说相比，网络小说偏重于娱乐性和读者阅读时的体验。<br>根据上述定义，以下属于网络小说的是：","options":[{"label":"A","content":"小张将自己考研的坎坷经历写成文章发表在网上，很多考研的学生看过之后很受感动，转发次数上百万"},{"label":"B","content":"小金根据《西游记》绘制长篇连环画，每天在网上连载发表，受到很多网友的追捧"},{"label":"C","content":"小黄根据姥姥讲的民间故事，写了长篇灵异小说发表在网站上，每日更新，小说完结后出版社主动与小黄联系，打算出版"},{"label":"D","content":"小姜将生活中的不文明现象写成一篇微小说发表在网上，电视台编导与他联系，想把他的小说拍摄成文明宣传片"}],"answer":"C","explanation":"网络小说定义的关键信息：在网上发表并以连载的模式形成的小说。<br>A项，考研经历既不是小说，也没有以连载的模式形成，不符合定义。<br>B项，连环画不是小说，不符合定义。<br>C项，小黄写了长篇灵异小说发表在网站上属于创作并发表，每日更新属于连载，符合网络小说的定义。<br>D项，一篇微小说不是以连载的模式形成，不符合定义。","no":130},{"id":"1718789647883","type":"single","material":"","stem":"《科学技术期刊管理办法》对科技期刊的定义为：具有固定刊名、刊期、年卷或年月顺序编号、印刷成册、以报道科学技术为主要内容的连续出版物。这一定义限定了科技期刊的刊载内容、外观和出版方式。<br>根据上述定义，以下属于科技期刊的是：","options":[{"label":"A","content":"《中国首届砂石生产技术交流会论文集》"},{"label":"B","content":"《青年文摘》"},{"label":"C","content":"《哈尔滨工程大学学报》"},{"label":"D","content":"《汽车新型光源科技研讨会会议纪要》"}],"answer":"C","explanation":"科技期刊的定义要点：①以报道科学技术为主要内容；②具有固定刊名、刊期、年卷或年月顺序编号、印刷成册；③连续出版物。<br>A项，《中国首届砂石生产技术交流会论文集》是该届交流会的论文合集，不属于连续出版物，不符合要点③。<br>B项，《青年文摘》并非以报道科学技术为主要内容，不符合要点①。<br>C项，《哈尔滨工程大学学报》是一本公开发行的综合学术性期刊，具备科技期刊的所有要点，符合定义。<br>D项，《汽车新型光源科技研讨会会议纪要》是该会议的会议纪要，不属于连续出版物，不符合要点③。","no":131},{"id":"1718789647884","type":"single","material":"","stem":"即发侵权，是指侵权活动开始之前，权利人有证据证明某行为很快就会构成对自己知识产权的侵犯，或该行为的正常延续必然构成侵权行为，权利人可依法予以起诉。<br>根据上述定义，以下事例可以以即发侵权进行起诉的是：","options":[{"label":"A","content":"知名乐队黑眼豆豆新出的专辑“夜空”正在大卖，同时，另一个知名度不高且取名为黑米果果的乐队也正抓紧制作名为“星空”的专辑"},{"label":"B","content":"小雪人形状的雪糕深受孩子们喜爱，最近市面上又出现一种形状非常相似的山寨小雪人雪糕"},{"label":"C","content":"小张是某软件开发公司的研发部经理，掌握该公司某项专利产品的核心技术，后来小张被另一公司高薪挖走，正在开发类似的产品"},{"label":"D","content":"小小读书郎的电子产品上市之后深受好评，另一家公司也紧跟着研发小小状元人机互动学习机"}],"answer":"C","explanation":"即发侵权的定义要点：①侵权活动开始之前；②有证据证明行为很快就会构成对自己知识产权的侵犯或该行为的正常延续必然构成侵权行为。<br>A项，黑米果果和黑眼豆豆，“星空”和“夜空”只是名称相似，不一定构成侵权，不符合要点②。<br>B项，和小雪人雪糕相似的山寨雪糕已经出现在市面上了，说明侵权行为已经发生了，不符合要点①。<br>C项，小张掌握着该公司某项专利产品的核心技术，跳槽到另一家公司开发类似的产品，正常延续必然会构成侵权行为，符合定义。<br>D项，另一家公司的小小状元互动学习机是自己研发的，不构成侵权，不符合要点②。","no":132},{"id":"1718789647885","type":"single","material":"","stem":"信赖保护原则是行政法的一项基本原则，是指政府对自己作出的行为或承诺应守信用，不得随意变更、反复无常。<br>根据上述定义，下列属于违反信赖保护原则的是：","options":[{"label":"A","content":"某市政府规定对于能够吸引外资企业投资的个人进行奖励，赵某引荐某国企业到该市进行投资，但事后市政府拒绝给付奖励"},{"label":"B","content":"某省工商局规定外地啤酒进入本地销售必须事先获得该局许可，同时应当缴纳特别经营费，后来该规定因涉嫌行政垄断被废除"},{"label":"C","content":"某市公安局拟对钱某作出处以吊销许可证的处罚，后经调查证实钱某的行为并未违法，因此未进行处罚"},{"label":"D","content":"某市环保局认为其下级部门对孙某作出的五万元处罚过重，改为罚款五千元"}],"answer":"A","explanation":"信赖保护原则定义的关键信息：政府对自己作出的行为或承诺应守信用，不得随意变更。<br>A项，市政府没有按照规定给付奖励，即对自己作出的承诺没有守信用，明显违反了信赖保护原则。<br>B项，废除了涉嫌行政垄断的规定，并非对自己作出的行为或承诺随意变更，没有违反信赖保护原则，排除。<br>C项，根据调查后的事实情况调整处理决定，并非对自己作出的行为或承诺随意变更，没有违反信赖保护原则，排除。<br>D项，调整下级部门的处罚决定，并非对自己作出的行为或承诺随意变更，没有违反信赖保护原则，排除。","no":133},{"id":"1718789647886","type":"single","material":"","stem":"社区居家养老指以家庭为核心、社区为依托，向居住在家中的老年人提供专业化、社会化服务，以解决日常生活中各种实际困难的养老方式。<br>下列属于社区居家养老的是：","options":[{"label":"A","content":"自从去年住进街道办的托老所后，文大爷整整胖了5斤。那里不光生活很舒心，而且还有周边社区的20多位老人做伴，连过年他都有点舍不得回家"},{"label":"B","content":"某社区联合一家养老企业推出适老化改造项目：针对老人的生理特点及生活习惯合理调整家里卧室、阳台、卫生间、厨房等处的生活设施。仅去年就完成了600多户家庭的改造工作"},{"label":"C","content":"退休多年的周婆婆每天上午都去社区养老服务中心跟着专业老师学习民族舞，下午又到那里当义工，傍晚才回家。中心也会定期派专职人员上门为她进行体检及其他服务"},{"label":"D","content":"南方某养老社区通过“互联网+社区+服务”模式，为准备在该社区过冬的“候鸟老人”提供网上预定租住房源以及接送服务，全程安排旅居、娱乐、社交生活"}],"answer":"C","explanation":"社区居家养老的定义要点：①以家庭为核心、社区为依托；②向居住在家中的老年人提供专业化、社会化服务；③以解决各种实际困难。<br>A项，文大爷住在了托老所，不符合要点①。<br>B项，社区与养老企业推出适老化改造项目，没有体现解决老人困难，不符合要点③。<br>C项，周婆婆白天去社区学习、当义工，晚上回家，家庭与社区相结合，有专人为她进行体检等专业化服务，帮她解决实际困难，符合要点①②③。<br>D项，养老社区为该社区的“候鸟老人”提供各种服务，没有以家庭为核心，不符合要点①。","no":134},{"id":"1718789647887","type":"single","material":"","stem":"田园综合体指一种新型的集特色优势产业、休闲旅游、乡村社区为一体的跨产业、多功能的农业生产经营体系。<br>下列属于田园综合体的是：","options":[{"label":"A","content":"某县刚刚落成的高科技农业园区中，万亩良田都装配了电子控制设施。园区附近还建有一个多功能老年公寓、十多个大型养生会馆"},{"label":"B","content":"作为首批省级乡村旅游示范区，向阳村“农家乐”已经成为某镇的骄傲，每年春天，那里的万亩油菜花田都吸引着成千上万的外地游客"},{"label":"C","content":"某乡打算在三年内建设成现代化的新型农村社区，没有高楼大厦，到处是小桥流水，服务配套设施齐全"},{"label":"D","content":"某乡村经过数年努力，形成了绿色食品生产经营、游客餐饮住宿、湿地公园观光的产业链，山更青水更绿了，村民生活也更富足了"}],"answer":"D","explanation":"田园综合体的定义要点：①集特色优势产业、休闲旅游、乡村社区为一体；②跨产业、多功能的农业生产经营体系。<br>A项，只提到某县的优势产业和社区，并未提及休闲旅游，不符合要点①。<br>B项，向阳村只是“农家乐”和油菜花田吸引了游客，只体现了发展旅游业，没有体现跨行业、多功能，不符合要点②。<br>C项，某乡只是要建设新农村，服务配套齐全，既没有体现发展优势产业、休闲旅游，又没有体现要建设跨产业、多功能的农业生产经营体系，不符合要点①②。<br>D项，某乡村形成了绿色食品生产经营、游客餐饮住宿、湿地公园观光的产业链，符合定义。","no":135},{"id":"1718789647888","type":"single","material":"","stem":"危机下沉，指年轻人面对本应在下一年龄段才会出现的问题时所产生的过度担忧。<br>下列属于危机下沉的是：","options":[{"label":"A","content":"每当想起两年后即将开始的退休生活，老张心头就涌起一种莫名的失落和焦虑"},{"label":"B","content":"小李刚刚考进江城大学，看到周边房价飙涨，天天担心自己毕业后买不起房而无法安家"},{"label":"C","content":"小黄硕士毕业四五年了，至今还是单身，她担心自己再拖下去就很难找到合适的对象了"},{"label":"D","content":"小梁夫妇最近为女儿明年上小学的事儿愁得睡不着觉，因为买不起心仪的那所名校的学区房"}],"answer":"B","explanation":"危机下沉的定义要点：①年轻人；②面对本应在下一年龄段才会出现的问题所产生的过度担忧。<br>A项，退休的老张不属于年轻人，不符合要点①。<br>B项，小李刚考进大学就开始担忧毕业后买不起房，属于对下一阶段的过度担忧，符合定义。<br>C项，毕业四五年的小黄至今单身，担心拖下去找不到合适的对象，属于现阶段的担忧，不符合要点②。<br>D项，小梁夫妇为女儿明年上学买不起学区房而担忧，属于现阶段的担忧，不符合要点②。","no":136},{"id":"1718789647889","type":"single","material":"","stem":"恶性抵制，指当事人在自身正当权利长时间受损，经过反复协商都无法解决的情况下采取的不文明、非理性、可能造成严重后果的抵制行为。<br>下列属于恶性抵制的是：","options":[{"label":"A","content":"某小区业主无法忍受广场舞噪音，多次沟通未果后，集资26万元购买了俗称“高音炮”的扩音系统，天天对着广场循环播放汽车喇叭声"},{"label":"B","content":"老李承包的果园曾经多次被小偷光顾，为了避免更大的损失，他在几棵果树上缠上了铁丝并通上了电，从此果园再也没有被偷过"},{"label":"C","content":"小区物业发现送快递的电瓶车车速过快，存在安全隐患，多次要求他们减速慢行，却收效甚微。于是禁止所有送快递的电瓶车进入小区"},{"label":"D","content":"某小区长期受到“牛皮癣”广告的骚扰，于是购买了一款“呼死你”软件，挨个呼叫广告上的手机号码，很快就解决了这个老大难问题"}],"answer":"A","explanation":"恶性抵制的定义要点：①正当权利长时间受损；②经过反复协商无法解决；③采取不文明、非理性的抵制行为。<br>A项，小区业主休息的权利长期受广场舞噪音侵害，多次沟通无果，买了“高音炮”对着广场放喇叭声，属非理性行为，符合定义。<br>B项，老李在树上缠上铁丝以防小偷光顾，未体现反复协商，不符合要点②。<br>C项，小区物业只是禁止快递电动车进入小区，杜绝安全隐患，属于理性的行为，不符合要点③。<br>D项，小区直接购买了一套“呼死你”的软件，没有反复协商，不符合要点②。","no":137},{"id":"1718789647890","type":"single","material":"","stem":"中介后遗症，指用户接受中介机构的服务后，个人信息被泄露到其他机构而长时间遭到骚扰的现象。<br>下列属于中介后遗症的是：","options":[{"label":"A","content":"小陈在商场购买了一台空调，销售商把小陈的信息通报给了厂家。小陈多次接到询问安装时间及地点的电话，后来又经常接到空调使用情况的回访电话"},{"label":"B","content":"小蔡在某房地产开发公司买了一套住房，随后就经常接到装修公司询问是否需要家装的电话，小蔡暂时不打算装修，非常反感这些来电"},{"label":"C","content":"小张通过一家猎头公司找到了满意的工作，但接下来的几个月里每天还会接到一些来路不明的电话，向他推荐“待遇优厚、时间灵活、任务轻松”的工作"},{"label":"D","content":"老王挂号就医时遇到了自称认识名医的丁某，在看过丁某推荐的名医后，病情未见好转，便不再理会丁某，也不再接丁某的骚扰电话"}],"answer":"C","explanation":"中介后遗症的定义要点：①接受中介机构的服务后；②长时间遭到骚扰的现象。<br>A项，小陈购买空调时的销售商不属于中介机构，不符合要点①。<br>B项，小蔡在房地产开发公司买了一套住房，房地产公司不属于中介机构，不符合要点①。<br>C项，小张通过中介机构猎头公司找到工作后，不断接到来路不明的向他推荐新工作的骚扰电话，符合定义。<br>D项，老王挂号就医认识的丁某，通过丁某认识名医但没有效果，不理丁某后没有接到骚扰信息，不符合要点①②。","no":138},{"id":"1718789647891","type":"single","material":"","stem":"非虚构写作，指以“亲历事实”为写作背景，秉承“诚实原则”,强调独特的现场感和真实感的写作行为，是文学创作的一种类型。<br>下列属于非虚构写作的是：","options":[{"label":"A","content":"近年来，国内影视界对宫廷秘史情有独钟，很多影视作品都是根据史书上所载真实事件改编而成的。有案可稽的史料已经成为这类影视创作的重要来源"},{"label":"B","content":"为了真实再现一桩离奇凶杀案的主要细节，作家阿克亲自来到案件发生的小镇，进行了两年多的实地调查，最终写出了他的成名作《小镇奇案始末》"},{"label":"C","content":"曹雪芹不但对社会生活有着严肃而深刻的哲学思考，也细心体察自己及身边普通人的不同命运。这些真实故事为他创作《红楼梦》提供了丰富素材"},{"label":"D","content":"许多研究中国农村问题的学者长年驻守农村，并根据田野调查资料写就论文专著,这与喜欢运用国外流行理论方法的学院派写作风格上显然不同"}],"answer":"B","explanation":"非虚拟写作的定义要点：①“亲历事实”为写作背景；②强调独特的现场感和真实感；③文学创作。<br>A项，影视作品是对史书的记载改编而成，背景都发生在古代，不属于以“亲历事实”为写作背景，不符合要点①。<br>B项，根据实地调查，真实再现了案发的现场感和真实感，符合定义。<br>C项，只体现出了曹雪芹为《红楼梦》如何提供写作素材，但小说中的人、事、物均为虚构，无法体现以“亲历事实”为背景，不符合要点①②。<br>D项，学者长期驻守农村，实地调查资料写就论文专著,并非文学创作，不符合要点③。","no":139},{"id":"1718789647892","type":"single","material":"","stem":"头条模式，指互联网公司、媒体等向特定用户精准推送筛选出的、对用户具有重要参考价值信息的一种信息服务模式。<br>下列属于头条模式的是：","options":[{"label":"A","content":"小李在某商场购买奶粉后，三年来陆续收到商场发来的澡盆、遥控玩具、儿童图书等商品的打折促销信息，还真省了不少钱"},{"label":"B","content":"某网络文献检索平台可以根据用户要求提供所需的文献及其下载率、引用率等信息，但是用户必须提供准确的个人信息"},{"label":"C","content":"某网络媒体公司将其平台专题栏目内容分为免费和付费两类，付费内容专业性很强，主要供有特定需求的人士选择使用"},{"label":"D","content":"某新媒体公司通过分析客户数据，组织专门团队实时筛选不同种类的信息，保证特定用户第一时间就能看到自己关心的内容"}],"answer":"D","explanation":"头条模式的定义要点：①互联网公司、媒体等；②向特定用户精准推送信息。<br>A项，小李收到商城发来的打折促销信息，商城不属于互联网公司、媒体等，不符合要点①。<br>B项，网络文献检索平台是根据用户要求提供信息，不是精准推送，不符合要点②。C项，网络媒体公司只是将栏目分为两类，未体现精准推送，不符合要点②。<br>D项，新媒体通过数据分析，保证特定用户第一时间可以看到自己关心的内容，符合定义。","no":140},{"id":"1718789647893","type":"single","material":"","stem":"数码技术后遗症，指由于过度使用、依赖数码产品而导致的记忆力衰退或认知能力降低现象。<br>下列属于数码技术后遗症的是：","options":[{"label":"A","content":"小朱方位感很好，以前开车从不用导航仪，自从装上导航仪后，就一天也离不开它了。昨晚导航仪出了故障，本来15分钟的车程他整整开了两个小时"},{"label":"B","content":"六十多岁的丁先生记忆力越来越差，不少曾经记得滚瓜烂熟的文献材料现在已经记不清楚了，经常需要用手机检索核实相关内容"},{"label":"C","content":"小李和几个朋友周末一起去网吧玩了个通宵。第二天早上刚走出网吧的时候，觉得路边的行人都是模模糊糊的"},{"label":"D","content":"张女士多次听朋友说手机上也可以直接购买理财产品，就下载了一个理财App,不料上了钓鱼网站，被骗了3万多元"}],"answer":"A","explanation":"数码技术后遗症的定义要点：①过度使用、依赖数码产品；②导致记忆力衰退或认知能力降低。<br>A项，小朱原本方向感很好，装上导航后，过度依赖导航仪，以致于在导航仪出故障后15分钟的路要开两个小时的车，由此可知其方向感变差，符合定义。<br>B项，丁先生是由于年龄大了记忆力减退才借助手机，不符合要点①②。<br>C项，小李和同事在网吧玩了个通宵，因为太累导致了刚出门看行人都是模糊的，不符合要点②。<br>D项，张女士下载了一个理财APP,被骗了3万多元，没有体现过度使用和依赖数码产品，也就无法导致不良影响，不符合要点①②。","no":141},{"id":"1718789647894","type":"single","material":"","stem":"人类命运共同体是指在追求本国利益时兼顾他国合理关切，在谋求本国发展中促进各国共同发展。人类只有一个地球，各国共处一个世界，要倡导“人类命运共同体”意识。<br>根据上述定义，以下不符合人类命运共同体理念的是：","options":[{"label":"A","content":"中国始终坚持正确的义利观，树立共同、综合、合作、可持续的新安全观"},{"label":"B","content":"中国必须统筹国际国内两个大局，始终走和平发展道路"},{"label":"C","content":"人类命运共同体没有超越社会制度差异、意识形态差异和价值观念分歧"},{"label":"D","content":"中国愿意始终做世界和平的建设者、全球发展的贡献者、国际秩序的维护者"}],"answer":"C","explanation":"人类命运共同体定义的关键信息：追求本国利益时兼顾他国合理关切，促进人类共同发展。<br>A项，正确的义利观(以重义轻利为基础，为社会群众创造价值，汲取较少的物质财富)和新安全观(共同、综合、合作、可持续),符合定义。<br>B项，统筹国际国内两个大局(追求本国利益时兼顾他国合理关切),始终走和平发展道路(促进人类共同发展),符合定义。<br>C项，人类命运共同体包含了全人类，因此也就超越了社会制度差异、意识形态差异和价值观念分歧，不符合定义。<br>D项，全球发展的贡献者(追求本国利益时兼顾他国合理关切),世界和平的建设者、国际秩序的维护者(促进人类共同发展),符合定义。<br>答案：C<br>解析：人类命运共同体定义的关键信息：追求本国利益时兼顾他国合理关切，促进人类共同发展。<br>A项，正确的义利观(以重义轻利为基础，为社会群众创造价值，汲取较少的物质财富)和新安全观(共同、综合、合作、可持续),符合定义。<br>B项，统筹国际国内两个大局(追求本国利益时兼顾他国合理关切),始终走和平发展道路(促进人类共同发展),符合定义。<br>C项，人类命运共同体包含了全人类，因此也就超越了社会制度差异、意识形态差异和价值观念分歧，不符合定义。<br>D项，全球发展的贡献者(追求本国利益时兼顾他国合理关切),世界和平的建设者、国际秩序的维护者(促进人类共同发展),符合定义。","no":142},{"id":"1718789647895","type":"single","material":"","stem":"虹吸是指利用液面高度差的作用力现象，将液体充满一根倒U形的管状结构内后，将开口高的一端置于装满液体的容器中，容器内的液体会持续通过虹吸管从开口更低的位置流出。<br>根据上述定义，以下不属于虹吸现象原理的是：","options":[{"label":"A","content":"汽车司机用橡胶管从油桶中吸出汽油或柴油"},{"label":"B","content":"我国黄河中下游的水面大都高出堤外地面，在河南、山东一带农民引黄河水灌溉农田"},{"label":"C","content":"小王给家里的鱼缸换水时把管子里的空气挤出，然后把管子插入水中，水源源不断地流出"},{"label":"D","content":"小刘家住某小区30楼，家中自来水来自二次供水"}],"answer":"D","explanation":"虹吸定义的关键信息：利用液面高度差的作用力。<br>A项，从油桶中吸油，利用了油桶中油面和容器的高度差作用力，符合定义。<br>B项，引黄河水灌溉农田，利用了黄河水面和农田的高度差作用力，符合定义。<br>C项，鱼缸换水，利用了鱼缸水面和地面高度差作用力，符合定义。<br>D项，高层自来水来自二次供水，利用的是加压，不符合定义。","no":143},{"id":"1718789647896","type":"single","material":"","stem":"股东派生诉讼是指当公司的董事、监事、高级管理人员或者他人违反法律、行政法规或者公司章程的行为侵害了公司权益，而公司拒绝或怠于追究其责任时，符合法定要件的股东为公司的利益以自己的名义对侵害人提起诉讼，请求违法行为人赔偿公司损失的行为。<br>根据上述定义，以下属于股东派生诉讼的是：","options":[{"label":"A","content":"某上市公司董事会秘书李某执行公司职务时，违反公司章程的规定，给公司造成了损失。王某是该公司连续一年持有10%股份的股东，王某可以以公司的名义起诉李某"},{"label":"B","content":"刘某是甲有限责任公司的董事长兼总经理。任职期间，多次利用职务之便，指示公司会计将资金借贷给一家主要由刘某儿子投资设立的乙公司。对此，持有公司股权3%的股东王某认为甲公司应起诉乙公司还款，但甲公司不可能起诉，王某便以自己的名义起诉乙公司，要求乙公司将借款返还给甲公司"},{"label":"C","content":"黄某是甲公司的董事，自2012年起，黄某在任职期间，另行申请设立了乙公司，该公司的经营范围与甲公司基本相同。黄某利用甲公司的业务渠道和技术资料从事与该公司同类的业务活动，造成甲公司约70万元的损失。甲公司遂起诉要求黄某停止违法经营活动，返还违法经营所得，并赔偿损失"},{"label":"D","content":"某股份有限责任公司总经理钟某违反公司章程的规定，未经股东大会同意，将公司资金无偿借贷给妻子弟弟，给公司造成了利益损失。对此，公司监事会有权提起诉讼，请求追究钟某的法律责任"}],"answer":"B","explanation":"股东派生诉讼的定义要点：①公司的董事等人违反法律、法规或者公司章程；②侵害了公司权益；③公司拒绝或者怠于追究其责任；④符合法定要件的股东以自己的名义提出诉讼，请求违法行为人赔偿损失。<br>A项，王某以公司名义起诉李某，不符合要点④。<br>B项，甲公司董事长刘某利用职务之便将资金借给乙公司(公司的董事等人违反法律、法规或者公司章程，侵害了公司权益),甲公司不可能起诉(公司拒绝或者怠于追究其责任),持有公司股权3%的股东王某(符合法定要件的股东),以自己的名义起诉乙公司，要求返还借款给甲公司(请求违法行为人赔偿损失),符合定义。<br>C项，甲公司起诉黄某，令其停止违法经营活动，是公司进行的起诉，不符合要点④。<br>D项，公司监事会起诉钟某，不符合要点④。","no":144},{"id":"1718789647897","type":"single","material":"","stem":"缔约过失责任是指在合同订立过程中，一方因违背其依据诚实信用原则所产生的义务，而致另一方的信赖利益受损，应承担损害赔偿责任；另一方因信赖合同的成立和有效，但由于合同不成立或无效而蒙受不利益，此种不利益即为信赖利益的损失。<br>根据上述定义，下列各项中甲方无需承担缔约过失责任的是：","options":[{"label":"A","content":"甲乙双方磋商共同兴建制药厂，甲方以技术出资，并提出乙方需培训相关人员后，方能与乙方签约。乙方出资100万元培训了相关人员后，甲方发现乙方制药技术存在问题，中止了与乙方的合作"},{"label":"B","content":"甲方声称有一批优质紫檀木欲出售给乙方，乙方立即与丙方签订了一份紫檀木家具供货协议，并向丙方支付了保证金。结果乙方在与甲方签约前发现甲方欲出售的紫檀木是假冒的"},{"label":"C","content":"甲方欲以50万元的价格将自己的房子卖给乙方，要求乙方在10天内以现金购买。乙方为筹集房款，将新买的汽车以极低的价格卖掉，第9天去购房时，甲方已将房子卖予丙方并已办理了过户手续"},{"label":"D","content":"甲方为报复乙方，声称欲以高价购买乙方的一批水果。乙方本有意将水果卖给丙方，遂中止了与丙方的协商。结果甲方在签约前反悔，致使乙方的水果未能及时卖出而腐烂"}],"answer":"A","explanation":"缔约过失责任定义的关键信息：一方因违背其依据诚实信用原则所产生的义务，导致另一方因信赖而利益受损。<br>A项，甲方未违背诚实信用原则，而是由于发现乙方技术存在问题而中止合同，无需承担缔约过失责任。<br>B项，甲方出售的紫檀木是假冒的，符合“一方因违背其依据诚实信用原则所产生的义务”,甲需要承担缔约过失责任，排除。<br>C项，甲方要求乙方在10天内以现金购买其房屋，乙方将新买的汽车以极低的价格卖掉以筹集房款，但在未逾期的情况下甲方却将房子卖予丙方。符合“一方因违背其依据诚实信用原则所产生的义务，导致另一方因信赖而利益受损”,甲需要承担缔约过失责任，排除。<br>D项，甲声称买乙的水果，乙信以为真，结果甲方在签约前反悔，致使乙方的水果未能及时卖出而腐烂。符合“一方因违背其依据诚实信用原则所产生的义务，导致另一方因信赖而利益受损”,甲需要承担缔约过失责任，排除。","no":145},{"id":"1718789647898","type":"single","material":"","stem":"鸟笼效应是一个心理学概念，它是指人们会在偶然获得一件原本不需要的物品的基础上，继续添加更多与之相关而自己不需要的东西。<br>根据上述定义，下列符合鸟笼效应的是：","options":[{"label":"A","content":"雯雯在网上购物，为了参与“满减”活动比预期多买了好几件商品"},{"label":"B","content":"刘阿姨去超市买菜，发现清洁用品正好在打折，忍不住买了一堆"},{"label":"C","content":"丽丽买裙子送了条毛衣链，她觉得没有毛衣可以搭配，又买了件毛衣，但却从没穿过"},{"label":"D","content":"小玲的男朋友送了她一束花，她很开心，还专门去买了个漂亮的花瓶"}],"answer":"C","explanation":"鸟笼效应定义的关键信息：偶然获得一件不需要的物品，继续添加与之相关而不需要的东西。C项因为买裙子获送毛衣链，然后买自己不需要的毛衣与之搭配，符合定义。A项多买了几件商品、B项买了一堆清洁用品、D项买了个花瓶，均未体现是自己不需要的东西，不符合定义的关键信息。","no":146},{"id":"1718789647899","type":"single","material":"","stem":"完全归纳推理又称完全归纳法，是以某类中每一对象(或子类)都具有或不具有某一属性为前提，推出该类对象全部具有或不具有该属性为结论的归纳推理。<br>根据上述定义，下列属于完全归纳推理的是：","options":[{"label":"A","content":"美国居民的祖先都是从国外迁徙来的。早期的居民是美洲印第安人，他们是几千年前从亚洲迁徙来的。后来的居民是欧洲人，他们是在250年至350年前作为殖民地开拓者来到这里的"},{"label":"B","content":"在很早的时候，中国就发明了指南针、造纸术、活字印刷术和火药，所以，中国是世界文明发展最早的国家之一"},{"label":"C","content":"凡有所学，皆成性格。读书使人充实，讨论使人机智，笔记使人准确，读史使人明智，读诗使人灵秀，数学使人周密，物理使人深刻，伦理使人庄重"},{"label":"D","content":"世界各国人民历来就相互进行科技的引进和交流。西方国家引进了中国古代的“四大文明”;日本的明治维新，主要是引进了欧洲的技术；今天许多国家种植的玉米、马铃薯，都是美洲印第安人培育出来的"}],"answer":"A","explanation":"完全归纳推理定义的关键信息：以某类中每一对象(或子类)都具有或不具有某一属性为前提。<br>A项，早期的居民和后来的居民，是以美国居民中每一个对象都具有某一属性为前提的，符合定义。<br>B项，只提到了中国，没有涉及其他国家的文明发展情况，不符合定义。<br>C项，只提到了读书、讨论、笔记、读史、读诗、数学、物理、伦理，并没有涵盖“凡有所学”中的每一个对象，不符合定义。<br>D项，只提到了西方国家与中国之间、日本与欧洲之间、“许多国家”与印第安人之间，并没有涵盖“世界各国人民”中的每一个对象，不符合定义。","no":147},{"id":"1718789647900","type":"single","material":"","stem":"当人们将一般规则应用于它所不适用的特殊事例时，就会产生“偶性的谬误”。<br>下列各项中，没有产生“偶性的谬误”的是：","options":[{"label":"A","content":"公民依法享有言论自由。所以老赵不该因为他上周发表颠覆政府的言论而被追诉"},{"label":"B","content":"借用他人物品应及时归还。你昨天从老钱家借了菜刀，前面那闹事的醉汉就是老钱，既然遇到他了，你现在赶紧把菜刀还给他"},{"label":"C","content":"生命在于运动。小孙正值长身体的时候，不能总是待在家里学习，该出去跑跑步锻炼锻炼"},{"label":"D","content":"你是在礼仪之乡长大的，深知诚实坦率是美德。现在就把你们公司的机密告诉我吧"}],"answer":"C","explanation":"“偶性的谬误”产生的条件是人们将一般规则应用于它所不适用的特殊事例。<br>A项，相对于一般规则“公民依法享有言论自由”,老赵发表颠覆政府的言论属于特殊事例，不适用该规则，产生了“偶性的谬误”,符合定义。<br>B项，相对于一般规则“借用他人物品应及时归还”,醉酒时候的老钱处于非正常状态，不适合还菜刀，属于特殊事例，不适用该规则，产生了“偶性的谬误”,符合定义。<br>C项，相对于一般规则“生命在于运动”,小孙出去跑步锻炼身体是正常的行为，不属于特殊事例，适用该一般规则，没有产生“偶性的谬误”,不符合定义。<br>D项，相对于一般规则“诚实坦率是美德”,公司机密是特殊的信息，泄露公司机密是违法行为，属于特殊事例，不适用该规则，产生了“偶性的谬误”,符合定义。","no":148},{"id":"1718789647901","type":"single","material":"","stem":"商业生态系统是指由组织和个人所组成的经济联合体，其成员包括核心企业、消费者、市场中介、供应商、风险承担者等，在一定程度上还包括竞争者。这些成员之间构成了价值链，不同的链之间相互交织形成了价值网，物质、能量和信息等通过价值网在联合体成员间流动和循环，从而形成整体的竞争优势。<br>根据上述定义，下列企业行为与商业生态系统不符合的一项是：","options":[{"label":"A","content":"日立公司强调如何利用企业的内部资源来形成竞争优势"},{"label":"B","content":"滴滴公司通过建设一个信息平台，撬动圈内其他企业和个人的资源"},{"label":"C","content":"飞利浦和美国电话电报公司合作，也同德国西门子公司合作"},{"label":"D","content":"苹果公司和微软公司的关系很复杂，既合作又竞争"}],"answer":"A","explanation":"商业生态系统定义的关键信息：组织和个人组成的经济联合体。其成员包括：核心企业、消费者、市场中介、供应商、风险承担者、竞争者。成员之间的联系形式：成员之间构成了价值链，不同的链之间相互交织形成了价值网。<br>A项，日立公司利用企业的内部资源来形成竞争优势，只是日立公司内部，即只涉及核心企业，没有与其他成员组成经济联合体，也没有构建价值链和价值网，不符合定义。<br>B项，滴滴公司建设信息平台，撬动圈内其他企业和个人的资源，构建了经济联合体，形成了价值网，符合定义。<br>C项，飞利浦和美国电话电报公司合作，也同德国西门子公司合作，说明和两个公司组成了经济联合体，形成了价值网，符合定义。<br>D项，苹果公司和微软公司的关系既合作又竞争，说明组成了经济联合体，形成了价值网，符合定义。","no":149},{"id":"1718789647902","type":"single","material":"","stem":"近因效应是指在总体印象形成过程中，新近获得的信息对人们认知的影响，远远大于以往所获得的信息。这是因为，在印象形成过程中，人们对原来的印象逐渐淡忘，当有新信息进入视野时，容易对人们的感官产生新的刺激，从而形成最新的印象，直接影响人们的认知和判断。<br>根据上述定义，下列不属于近因效应的一项是：","options":[{"label":"A","content":"某社会名流声名卓著,到了晚年却因为一桩丑闻而臭名昭著"},{"label":"B","content":"面试时衣冠整洁，给人以良好的印象，被录取的概率也较大"},{"label":"C","content":"夫妻本来感情很好，因为一件小事吵架，闹嚷着要离婚"},{"label":"D","content":"小玲和小菲是多年好友，因小玲最近“得罪”了小菲，两人形同陌路"}],"answer":"B","explanation":"近因效应定义的关键信息：新近获得的信息对人们认知的影响，远远大于以往所获得的信息。<br>A项，声名卓著属于以往所获得的信息，一桩丑闻属于新近获得的信息，结果臭名昭著显然是受到了新近获得的信息的影响，符合定义。<br>B项，面试时衣冠整洁，给人以良好的印象，不存在新近信息和以往信息的比较，不属于近因效应。<br>C项，本来感情很好属于以往所获得的信息，因一件小事吵架属于新近获得的信息，结果闹嚷着要离婚显然是受到了新近获得的信息的影响，符合定义。<br>D项，多年好友说明关系好，属于以往所获得的信息，最近的“得罪”属于新近获得的信息，结果形同陌路显然是受到了新近获得的信息的影响，符合定义。","no":150},{"id":"1718789647903","type":"single","material":"","stem":"合义务的择一举动是指虽然行为人实施了违法行为，造成了结果，但即使其遵守法律，也不能避免该结果的情形。<br>根据上述定义，下列属于合义务的择一举动的是：","options":[{"label":"A","content":"甲驾车正常行驶，行人王某从人行道上猛然冲向甲，结果王某被撞伤"},{"label":"B","content":"乙醉酒后驾车，行人王某同样喝醉了酒，从人行道上猛然冲向乙，结果王某被撞伤"},{"label":"C","content":"丙驾车超速行驶，行人王某横穿马路，丙来不及刹车，将王某撞伤"},{"label":"D","content":"丁驾车超载行驶，行人王某横穿马路，幸而丁紧急刹车，才没有撞到王某"}],"answer":"B","explanation":"合义务的择一举动的定义要点：①行为人实施了违法行为；②造成了结果；③即使遵守法律也不能避免该结果。<br>A项，甲驾车正常行驶不符合要点①。<br>B项，即使乙不是醉酒后驾车也不能避免王某被撞，符合定义。<br>C项，如果丙不是超速行驶的话，结果是可以避免的，不符合要点③。<br>D项，没有造成结果，不符合要点②。","no":151},{"id":"1718789647904","type":"single","material":"","stem":"稻草人谬误是指反驳者在没有任何证据或推理可用时，偷换对方的论点，然后把这个论点当作是对方的论点并加以推翻的一种逻辑错误。<br>根据上述定义，下列反驳中存在稻草人谬误的是：","options":[{"label":"A","content":"正方：某大学开设了炒作学专业，所以炒作是有益的。<br>反方：某大学还开设了犯罪学专业呢!犯罪也有益?"},{"label":"B","content":"正方：请对方辩友正面回答我的问题!<br>反方：对方的观点根本就是无稽之谈，不需要回答。"},{"label":"C","content":"正方：心灵美比外表美更重要。<br>反方：你是说你愿意娶一个奇丑的女人?多么荒谬!"},{"label":"D","content":"正方：“距离产生美”这句话正确吗?<br>反方：那你说，如果距离不产生美，那能产生什么"}],"answer":"C","explanation":"稻草人谬误的定义要点：①偷换对方的论点；②然后把这个论点当作对方的论点加以推翻。<br>A项，正方论点为炒作是有益的，反方的论点为犯罪也有益，不符合要点①②。<br>B项，只涉及反方反驳正方论点为无稽之谈，不符合要点①。<br>C项，正方的论点是心灵美比外表美更重要。反方把正方的论点偷换为外表美不重要，然后加以反驳，符合定义。<br>D项，正方为提出一个疑问，反方的论点是围绕距离是否产生美展开论述，不符合要点①②。","no":152},{"id":"1718789647905","type":"single","material":"","stem":"遥感物探是指在距离相当遥远的位置上，用各种传感器探知地面物体辐射(或反射)的电磁波信息，以查明地质的或地学的各种情况的方法。<br>根据上述定义，下列属于遥感物探的是：","options":[{"label":"A","content":"科学家通过“天眼”系统观测外太空星体"},{"label":"B","content":"科学家用卫星对某沿海地区进行地质探测"},{"label":"C","content":"医生用X光透视检查病人身体器官的病变"},{"label":"D","content":"侦察兵利用探雷装置发现埋在地下的地雷"}],"answer":"B","explanation":"遥感物探的定义要点：①在距离相当遥远的位置上；②探知地面物体辐射或反射的电磁波信息；③查明地质的或地学的各种情况。<br>A项，外太空星体不属于地面物体，不符合要点②。<br>B项，科学家用卫星(在距离相当遥远的位置上)对某沿海地区进行地质探测(探知地面物体辐射或反射的电磁波信息),符合定义。<br>C项，医生用X光透视不符合相当遥远的位置，病人身体器官的病变不属于地质或地学领域，不符合要点①③。<br>D项，侦察兵利用探雷装置不符合相当遥远的位置，埋在地下的地雷不属于地质或地学领域，不符合要点①③。","no":153},{"id":"1718789647906","type":"single","material":"","stem":"柏金赫现象，是指人眼在低照明水平时，会产生视感觉的敏感性向光谱蓝端迁移的现象。<br>根据上述定义，下列利用了柏金赫现象的是：","options":[{"label":"A","content":"将同样的红玫瑰花，印制在薄尼龙纱窗及粗厚的沙发织物上，可以形成既配套又独具材质变化魅力的装饰效果"},{"label":"B","content":"面积较大的房间，使用奶黄、浅咖啡色等暖色调来装修，既可以使人感到温馨愉快，又可以避免给人以空旷感"},{"label":"C","content":"创作一幅用于悬挂在较暗室内环境中的磨漆画时，在色彩构成方面，选用蓝、绿等冷色调优于红、橙等暖色调"},{"label":"D","content":"医院手术室环境及医护人员工作服都选用蓝绿色，可以使医生注视了蓝绿色后，更易看清细小的血管、神经等"}],"answer":"C","explanation":"柏金赫现象的定义要点：①人眼在低照明水平时；②产生视感觉的敏感性向光谱蓝端迁移的现象。<br>A项，红玫瑰花印制在薄尼龙纱窗及粗厚的沙发织物上，未体现低照明水平，不符合要点①。<br>B项，面积较大的房间，使用奶黄、浅咖啡色等暖色调来装修未体现低照明水平，不符合要点①。<br>C项，创作悬挂在较暗室内环境中的磨漆画(低照明水平),选用蓝、绿等冷色调优于红、橙等暖色调(产生视感觉的敏感性向光谱蓝端迁移的现象),符合定义。<br>D项，医院手术室环境属于高照明水平，不符合要点①。","no":154},{"id":"1718789647907","type":"single","material":"","stem":"艺术直觉是人们在艺术活动中，对事物的特征、本质、意义，不经过逻辑推理和分析而直接地感受和领悟。<br>根据上述定义，下列属于艺术直觉的是：","options":[{"label":"A","content":"某技术工人在一次技术操作中突然发现合理的操作方法"},{"label":"B","content":"某歌手经多次演出找到适合自己的歌唱方式和表演方式"},{"label":"C","content":"某游客在欣赏毕加索的画时突然领悟到作品的独特内涵"},{"label":"D","content":"某艺术鉴赏家通过多次对比发现了凡·高绘画作品的特征"}],"answer":"C","explanation":"艺术直觉的定义要点：①在艺术活动中；②对事物的特征、本质、意义，不经过逻辑推理和分析而直接地感受和领悟。<br>A项，某技术工人在一次技术操作中，这种行为不属于艺术活动，不符合要点①。<br>B项，某歌手多次演出总结的方式，不属于直接领悟，不符合要点②。<br>C项，某游客在欣赏毕加索的画时(在艺术活动中),突然领悟到作品的独特内涵(直接领悟),符合定义。<br>D项，某艺术鉴赏家通过多次对比，不属于直接领悟，不符合要点②。","no":155},{"id":"1718789647908","type":"single","material":"","stem":"反应性相倚是指在沟通过程中，沟通双方都以对方的行为作为自己行为的依据，做出相应的反应，而并不按照原来的计划进行沟通。<br>根据上述定义，下列属于反应性相倚的是：","options":[{"label":"A","content":"小何计划出国读博，申请几所学校都收到了录取通知，他反复研究，并征求导师的意见，做出了最终决定"},{"label":"B","content":"方某通过房产中介看中了黄某的房子，与黄某沟通后发现其房屋的产权证尚未取得，于是方某决定推迟购买"},{"label":"C","content":"小李报名参加演讲比赛，初赛晋级后进入复赛，但复赛时间和小李的外语考试冲突，于是小李改变计划，选择退赛"},{"label":"D","content":"某公司计划推行新考核制度，各部门负责人希望按部门情况分别拟定，后公司决定先保留原制度，针对个别情况逐步调整，各部门表示同意"}],"answer":"D","explanation":"反应性相倚定义的关键信息：沟通双方都以对方的行为作为自己行为的依据，并不按照原来的计划进行沟通。<br>A项，小何自己反复研究，征求了导师的意见，然后做出了决定，未体现出小何与导师以对方的行为作为自己行为的依据，不符合定义。<br>B项，方某在发现黄某房屋的产权证尚未取得后决定推迟购买，是以黄某的行为作为自己行为的依据，做出了相应的反应，但黄某并未以方某的行为作为依据做出反应，不符合定义。<br>C项，因演讲比赛复赛时间与外语考试冲突，小李选择退赛，未体现沟通双方以对方的行为作为自己行为的依据，不符合定义。<br>D项，各部门负责人因公司要推行新制度而提出按部门调整的建议，公司因各部门负责人提出的建议而决定保留原制度、针对个别情况调整，并未按照原本的计划进行，公司和各部门负责人都以对方的行为作为自己行为的依据并作出了相应的反应，符合定义。","no":156},{"id":"1718789647909","type":"single","material":"","stem":"法条竞合犯是指一个犯罪行为同时触犯数个具有包容关系的刑法条文，依法只适用其中一条定罪量刑的情况。<br>根据上述定义，下列属于法条竞合犯的是：","options":[{"label":"A","content":"王某醉酒驾驶致伤三人"},{"label":"B","content":"张某拦路抢劫致人死亡"},{"label":"C","content":"李某生产销售价值百万的假药"},{"label":"D","content":"周某组织多人制造假币"}],"answer":"C","explanation":"：法条竞合犯定义的关键信息：一个犯罪行为同时触犯数个具有包容关系的刑法条文。<br>A项，王某醉驾致伤三人，触犯交通肇事罪、危险驾驶罪，在最新刑法中，两项罪名为同一刑法条文，并非“数个具有包容关系的刑法条文”,不符合定义。<br>B项，张某拦路抢劫致人死亡只涉及抢劫罪，不符合“同时触犯数个具有包容关系的刑法条文”,不符合定义。<br>C项，生产销售假药，触犯《中华人民共和国刑法》第一百四十条关于生产、销售伪劣产品罪的规定，又触犯《中华人民共和国刑法》第一百四十一条生产、销售假药罪的规定。对于同时构成生产、销售假药罪和生产、销售伪劣产品罪的，根据《中华人民共和国刑法》第一百四十九条第二款规定的精神，应按处罚较重的生产、销售假药罪定罪处罚。符合定义。<br>D项，制造假币只涉及伪造货币罪，不符合“同时触犯数个具有包容关系的刑法条文”,不符合定义。","no":157},{"id":"1718789647910","type":"single","material":"","stem":"营业外收入是指企业确认与企业生产经营活动没有直接关系的各种收入。这一收入实际上是一种纯收入，不是由企业经营资金耗费所产生的，不需要企业付出代价，不需要与有关费用进行配比。换言之，除企业营业执照中规定的主营业务以及附属的其他业务之外的所有收入都视为营业外收入。<br>根据上述定义，下列关于营业外收入的说法哪项不正确?","options":[{"label":"A","content":"某旅游景区服务公司获得的门票收入属于营业外收入"},{"label":"B","content":"某高分子材料公司从当地政府获得的高薪技术企业的政策补贴属于营业外收入"},{"label":"C","content":"甲、乙两公司是合作企业，后乙公司违反国家有关行政管理法规，按照规定支付给甲公司一定数量的罚款，该罚款属于甲公司的营业外收入"},{"label":"D","content":"甲公司购入一批环保设备，5年后将这些设备进行报废处理并获得相应的报废款，这一款项扣除资产账面价值、清理费用、处置相关税费后的净收益属于营业外收入"}],"answer":"A","explanation":"营业外收入的定义要点：①与企业生产经营活动没有直接关系的收入；②不由企业经营资金耗费产生；③不需要企业付出代价；④除主营业务以及附属其他业务之外的收入。<br>A项，售卖门票是景区的主营业务，不符合要点④。<br>B项，高分子材料公司获得当地政府的政策补贴，与其生产经营活动没有直接关系，公司未消耗资金、付出代价，是主营业务以及附属其他业务之外的收入，符合定义。<br>C项，乙公司违反法律支付给甲公司的罚款，与甲公司的业务活动无关，甲公司未消耗资金、付出代价，是主营业务以及附属其他业务之外的收入，符合定义。<br>D项，甲公司获得的报废款是在扣除了账面价值、清理费用、相关税费后的净收益，<br>与公司生产经营活动没有直接关系，公司未付出代价，是主营业务以及附属其他业务之外的收入，符合定义。","no":158},{"id":"1718789647911","type":"single","material":"","stem":"瑕疵担保责任是指依法律规定，在交易活动中当事人一方移转财产(或权利)给另一方时，应担保该财产(或权利)无瑕疵，若移转的财产(或权利)有瑕疵，则应向对方当事人承担相应的责任。<br>根据上述定义，下列选项中乙公司不需要承担瑕疵担保责任的是：","options":[{"label":"A","content":"甲公司从乙公司购买了四台不锈钢水箱，后一台水箱发生爆裂，经鉴定水箱钢板厚度偏薄，焊接质量较差，与国家标准要求不符"},{"label":"B","content":"甲公司与乙公司签订协议，甲支付50万元获得乙公司旗下6个专利产品，后甲在使用过程中发现其中一个产品版权属于丙公司所有"},{"label":"C","content":"甲公司与乙公司签订《股权转让协议》,约定甲公司将名下的股权全额转让给乙公司，协议签订不久，乙公司资金发生问题，申请破产"},{"label":"D","content":"甲公司租赁乙公司的厂房开办化工厂，后房屋漏雨，甲公司安排工人杨某到屋顶更换石棉瓦，结果杨某在更换过程中因房屋大梁突然断裂从高处坠落受伤"}],"answer":"C","explanation":"瑕疵担保责任定义的关键信息：交易活动中，当事人一方转移给另一方有瑕疵的财产时，应向对方当事人承担相应的责任。<br>A项，乙公司由于钢板厚度偏薄导致水箱发生爆裂，是移转的财产有瑕疵，乙公司应向对方当事人承担相应的责任，符合定义。<br>B项，乙公司给甲公司的6个专利产品有一个版权属于丙公司，是移转的权利有瑕疵，应向对方当事人承担相应的责任，符合定义。<br>C项，乙公司资金发生问题申请破产，不属于转移给另一方的财产有瑕疵，不符合定义。<br>D项，乙公司的房屋漏雨且房屋大梁断裂导致甲公司的杨某受伤，是移转的财产有瑕疵，应向对方当事人承担相应的责任，符合定义。","no":159},{"id":"1718789647912","type":"single","material":"","stem":"埋伏营销是指企业利用媒体和公众对重大事件的关注，通过举办与重大事件相关的活动，使自己与重大事件产生关联，从而引起消费者的联想和媒体的注意。这类营销通常是隐蔽的、突发的，不以赞助者的身份出现，却对自己的品牌悄无声息地进行了宣传。<br>根据上述定义，下列不属于埋伏营销的是：","options":[{"label":"A","content":"某矿泉水公司邀请著名运动员为其代言，并将广告投放在电视媒体的黄金时段和一些大型酒店的视频媒体中"},{"label":"B","content":"地震发生后，某户外用品公司向灾区捐赠价值100万元的帐篷，并举行了捐赠仪式"},{"label":"C","content":"某市举办中小学生知识竞赛，一出版集团在现场向参与者免费发放其出版的图书"},{"label":"D","content":"世界一级方程式锦标赛比赛期间，观众席中时不时会有人挥舞着印有某轮胎企业商标的彩色旗帜"}],"answer":"A","explanation":"埋伏营销的定义要点：①通过举办与重大事件相关的活动，使自己与重大事件产生关联；②隐蔽的、突发的，不以赞助者的身份出现。<br>A项，邀请著名运动员代言并投放广告，既未与重大事件相关联，又很明显地打广告，不具有隐蔽性和突发性，不符合定义。<br>B项，地震发生后向灾区捐赠帐篷，和地震这一重大事件相关联，具有隐蔽性和突发性，符合定义。<br>C项，在知识竞赛现场免费发放图书，和知识竞赛这一事件相关联，具有隐蔽性和突发性，符合定义。<br>D项，和世界一级方程式锦标赛这一重大事件相关联，具有隐蔽性和突发性，符合定义。","no":160},{"id":"1718789647913","type":"single","material":"","stem":"著名科学家、科学史学家普赖斯提出：如果K代表参与某一专业领域的人数，那么这个数字的平方根大致等于为这个领域做出一半贡献的排名在前的那部分人的人数。<br>根据上述定义，下列符合普赖斯观点的是：","options":[{"label":"A","content":"某国出版协会统计了本国的期刊，发现与经济有关的期刊大约有150种，所有与经济有关的科研论文中，有一半发表在其中的13种期刊上"},{"label":"B","content":"某县有20万农业人口，统计发现，过去一年全县的粮食总产量中，大约一半粮食产量是由450位左右的种粮大户贡献的"},{"label":"C","content":"某组织统计过去一年全世界公开举办的音乐会的演奏曲目，发现所有演奏曲目是由大约250位作曲家完成的，其中大约一半的曲目来自16位作曲家"},{"label":"D","content":"某销售奢侈品的网店过去一年的访问量为10万人次，但去年全部的销售额中，大约一半的销售额是由其中大约300位固定客户提供的"}],"answer":"C","explanation":"普赖斯观点的关键信息：某一专业领域总人数的平方根≈为这个领域做出一半贡献的排名在前的那部分人的人数。<br>A项，说的是期刊的种类数，不涉及参与其中的人数，不符合定义。<br>B项，20万农业人口不一定都从事种粮，总参与人数不确定，不符合定义。<br>C项，所有演奏曲目由大约250位作曲家完成，其中大约一半的曲目来自16位作曲家，16²=256≈250,符合普赖斯观点。<br>D项，访问网站的顾客和购买商品的顾客不是同一概念，两个群体不是同一范畴，不符合定义。","no":161},{"id":"1718789647914","type":"single","material":"","stem":"小推车管理法是指服务提供者通过把服务对象纳入服务系统中，并挖掘服务对象潜在资源，与其共同提高管理服务水平的创新管理模式，该模式对服务提供者和服务接受者来说是一种双赢策略。<br>根据上述定义，下列选项属于小推车管理法的是：","options":[{"label":"A","content":"学生家长群安排家长轮流给班级免费做清洁，学校为此节省了开支"},{"label":"B","content":"老张辞掉保姆，自己做起了家务，既锻炼了身体又节约了一笔开销"},{"label":"C","content":"某书店鼓励来购书和阅读的顾客自带小折叠凳，顾客感觉很贴心，书店的销售业绩有很大提升"},{"label":"D","content":"超市为了树立“环保、节能、负责”的企业形象，对自带环保包装袋的消费者发放电子红包"}],"answer":"C","explanation":"小推车管理法的定义要点：①把服务对象纳入服务系统，挖掘服务对象的潜在资源；②对服务提供者和服务接受者来说是一种双赢策略。<br>A项，仅学校节省开支，未体现双赢，不符合要点②。<br>B项，解聘保姆未涉及把服务对象纳入服务系统，挖掘服务对象的潜在资源，同时也不是双赢，不符合要点①②。<br>C项，某书店鼓励来购书和阅读的顾客自带小折叠凳，属于把服务对象纳入服务系统，挖掘服务对象的潜在资源，顾客觉得贴心，书店销售业绩上升属于双赢，符合定义。<br>D项，超市对自带环保袋的消费者发放电子红包，增加了自己的成本，不符合要点②。","no":162},{"id":"1718789647915","type":"single","material":"","stem":"机器视觉是指通过光学的装置和非接触的传感器自动地接收和处理一个真实物体的图像，获得所需信息或用于控制机器人运动的装置。<br>根据上述定义，下列选项涉及机器视觉的是：","options":[{"label":"A","content":"扁平化的摄像头通过暗光拍摄，发现沙发底部灰尘很多，向主人发出需要清洗的红色警报"},{"label":"B","content":"车载智能设备在路上通过定位系统、导航系统等语音提醒司机行车路线、各路段车速限制及前方天气情况等"},{"label":"C","content":"新型眼镜在主人探险进入黑暗洞穴后捕捉到大量蝙蝠发出的超声波，立刻启动了面部保护模式"},{"label":"D","content":"带有拍摄装置的迷你智能机器人进入考古人员难以到达的墓穴深处，拍摄到许多珍贵图像，并同步传输给计算机"}],"answer":"A","explanation":"机器视觉的定义要点：①通过光学装置和非接触的传感器；②自动接收和处理真实物体图像；③获得信息或控制机器人运动。<br>A项，通过摄像头拍摄图像并进行处理判断，进而获得信息(有灰尘)且发出了指令(需要清洗),符合定义。<br>B项，车载智能设备提醒司机路况等，不符合要点②。<br>C项，超声波不是光学装置和非接触的传感器，不符合要点①。<br>D项，机器人拍摄照片后仅是传输给计算机，并未涉及图像的处理，也没有获得所需信息或发出指令，不符合要点②③。","no":163},{"id":"1718789647916","type":"single","material":"","stem":"供给侧改革就是从提高供给质量出发，用改革的办法推进结构调整，矫正要素配置扭曲，扩大有效供给，提高供给结构对需求变化的适应性和灵活性，提高全要素(劳动力、土地、资本、创新)生产率，更好地满足广大人民群众的需求，促进经济社会持续健康发展。<br>根据上述定义，下列不符合供给侧改革要求的是：","options":[{"label":"A","content":"减免企业税负，提升企业盈利"},{"label":"B","content":"增大政府投资，建设各种基础设施"},{"label":"C","content":"推进产学研相结合，为企业提供技术支撑"},{"label":"D","content":"改革户籍制度，促进劳动力跨地区、跨部门流动"}],"answer":"B","explanation":"供给侧改革的定义要点：①推进结构调整，矫正要素配置扭曲；②提高全要素(劳动力、土地、资本、创新)生产率；③满足广大人民群众的需要，促进经济社会持续健康发展。<br>A项，减免企业税负，体现了资本要素，符合定义。<br>B项，增大政府投资属于需求侧改革，而不是供给侧改革，不符合要点①。<br>C项，推进产学研相结合，体现了创新要素，符合定义。<br>D项，改革户籍制度，体现了劳动力要素，符合定义。","no":164},{"id":"1718789647917","type":"single","material":"","stem":"C2C是指消费者(Consumer)与消费者(Consumer)之间以信息网络技术为手段、以商品交换为中心的商务活动。<br>根据上述定义，下列活动属于C2C的是：","options":[{"label":"A","content":"某小区推出“旧物置换”服务，业主可将家中不用的物品放到门卫室，与其他业主置换"},{"label":"B","content":"大学生小李以2000元的价格在网上拍卖掉了自己的旧笔记本电脑，没想到买家居然是自己的同班同学小方"},{"label":"C","content":"每到毕业季，学校广场上的跳蚤市场都异常火爆，“甩卖”的学长学姐和“淘宝”的学弟学妹都各取所需，满载而归"},{"label":"D","content":"小梅逛街时在某品牌服装专卖店相中了一款风衣，便记下衣服吊牌上的信息，回来后从该品牌的官方网站上买了一件，省了不少钱"}],"answer":"B","explanation":"C2C的定义要点：①以信息网络技术为手段；②以商品交换为中心；<br>③消费者与消费者之间的商务活动。<br>A项，将家中不用的物品放到门卫室，与其他业主置换，没有运用信息网络技术，不符合要点①。<br>B项，以2000元的价格在网上拍卖掉了自己的旧笔记本电脑，符合定义。<br>C项，跳蚤市场没有运用信息网络技术，不符合要点①。<br>D项，从该品牌的官方网站上买了一件，官方网站不是消费者，不符合要点③。","no":165},{"id":"1718789647918","type":"single","material":"","stem":"拟态是指某些生物在进化过程中具有与另一种生物或周围自然界物体相似的形态，这种相似性很高，几乎难以分辨，可以保护某一物种或两个物种。<br>根据上述定义，下列选项属于拟态的是：","options":[{"label":"A","content":"海豚、企鹅和带鱼虽然分别属于鲸类、鸟类和鱼类，但为了适应海洋生活，都进化出了流线型的身体"},{"label":"B","content":"北极熊生活在白雪皑皑的北极，为了掩护自己捕食时不被猎物过早发现，皮毛逐渐变成与环境相似的白色"},{"label":"C","content":"杜鹃会将与宿主卵酷似的卵产在宿主巢内，其雏鸟在孵出后不久就会将宿主雏鸟挤出巢外，独享体型只有自己一半大小的宿主父母的喂食"},{"label":"D","content":"大鲵，俗名娃娃鱼，已在地球上生活了数亿年，其受到刺激时的叫声酷似人类婴儿的哭声，让人听到不忍心伤害，对一些猎食动物也有威慑作用"}],"answer":"C","explanation":"拟态的定义要点：①具有与另一种生物或周围自然界物体相似的形态；②相似性很高，难以分辨；③可以保护某一物种或两个物种。<br>A项，只是身体形态都是流线型，不符合要点②③。<br>B项，北极熊的皮毛逐渐变成与环境相似的白色，变化的仅是颜色，不符合要点①③。<br>C项，杜鹃的卵与宿主的卵相似，不易被察觉，是一种宿主拟态，符合定义。<br>D项，大鲵的叫声酷似人类婴儿的哭声，哭声不属于形态，不符合要点①②③。","no":166},{"id":"1718789647919","type":"single","material":"","stem":"木椅子效应是指将成绩相等的两组学生分别安排坐在舒适的沙发椅和很不舒服的木椅子上学习，不久之后，坐木椅子的学生学习成绩要比坐沙发椅的学生成绩高出许多。原因是坐木椅子的学生因为不舒服而不断调整坐姿，表面看来好像不安而好动，实质却因此给脑部供应了更多的血液和营养；而坐沙发椅的学生，由于舒适而一动不动，致使血液循环相对减慢，脑部得到的血液和营养相对减少，学习效果因此就差了一些。<br>根据上述定义，下列选项最能体现木椅子效应的是：","options":[{"label":"A","content":"某学生从小到大饱受责罚，学习成绩一直不理想"},{"label":"B","content":"小刚每天步行上学和回家，风雨无阻却学得很好"},{"label":"C","content":"某家长为鼓励孩子暑天学习，每天为其提供冷饮"},{"label":"D","content":"搬入新书房一个月后，小明的成绩名次一路攀升"}],"answer":"B","explanation":"木椅子效应的定义要点：①学习好是因为木椅子不舒服，表面看来不安而好动，却因此给脑部供应了更多的血液和营养；②学习不好是因为舒适而一动不动，致使血液循环相对减慢，脑部得到的血液和营养相对减少。<br>A项，虽然环境不舒适，但是没有促进学习，不符合要点②。<br>B项，步行上学、回家，风雨无阻体现环境艰苦，结果是学得很好，符合定义。<br>C项，暑天提供冷饮，营造了舒适的环境，没有提到孩子学习的效果，不符合要点①。<br>D项，搬入新书房，环境舒适，成绩提高，不符合要点①。","no":167},{"id":"1718789647920","type":"single","material":"","stem":"心理会计是指人们在心里无意识地把财富划归不同的账户进行管理，并对结果(尤其是经济结果)加以编码、分类和估价的过程，且不同的心理账户有不同的记账方式和心理运算规则。小到个体、家庭，大到企业集团，都有一套或隐或显的心理账户系统，其心理记账方式与经济学和数学的运算方式都不相同，因此经常以非预期的方式影响着决策，使个体的决策违背最简单的理性经济法则。<br>根据上述定义，下列选项最能体现心理会计现象的是：","options":[{"label":"A","content":"整日忧心忡忡的小李将自己全部存款的四分之三用于购买人寿保险"},{"label":"B","content":"小陈已经攒够购买相机的钱，但他一定要等领到年底奖金再买相机"},{"label":"C","content":"小王在两家不同银行都有储蓄卡，但他总是去离家更近的银行取款"},{"label":"D","content":"小刘因公司奖励出游某地感觉不错，后来自费重游此地却感觉不佳"}],"answer":"B","explanation":"心理会计的定义要点：①把财富划归不同的账户进行管理，并加以编码分类；②使个体的决策违背最简单的理性经济法则。<br>A项，将全部存款的四分之三用于购买保险，不符合要点①。<br>B项，小陈已经有了买相机的钱，但还是要等领到年底奖金后再买，即在心里把现在的钱和奖金进行了划分和分类，现在钱已经足够但不买，符合定义。<br>C项，小王去银行取款，不涉及心理会计，不符合要点①②。<br>D项，两次旅游没有体现出不同的心理账户，不符合要点①②。","no":168},{"id":"1718789647921","type":"single","material":"","stem":"数据挖掘(Datamining)是指从大量的存储数据中利用统计、情报检索、模式识别、在线分析处理和专家系统(依靠过去的经验)等方法或技术，发现隐含在其中、事先不知道但又是潜在有用的信息和知识的信息处理过程。<br>根据上述定义，下列选项不属于数据挖掘应用的是：","options":[{"label":"A","content":"某高校要求教师使用网上教学管理系统，录入学生的期末考试成绩，以便借助短信群发软件告知学生成绩"},{"label":"B","content":"某国际快递和物流公司使用RFID(无线射频识别)技术在不同时间点跨境全程监控和调整药品装运的温度"},{"label":"C","content":"某大型网上书店在客户选购一种图书时，推出“购买该商品的用户还购买了”等栏目，从而增加可观收益"},{"label":"D","content":"某全球零售企业在分析上一年度消费者购物行为后推出“尿布+啤酒”促销举措，使得二者销售量大幅增加"}],"answer":"A","explanation":"数据挖掘的定义要点：①从大量的存储数据中利用统计、情报检索、模式识别、在线分析处理和专家系统(依靠过去的经验)等方法或技术；②发现隐含在其中、事先不知道但又是潜在有用的信息和知识。<br>A项，录入期末考试成绩是为了群发短信，不是为了发现什么潜在有用的信息，不符合要点②。<br>B项，使用RFID(无线射频识别)技术监控温度，属于模式识别且对温度数据进行在线分析，调整药品装运的温度，属于发现潜在有用的合适温度，符合定义。<br>C项，网上书店推出“购买该商品的用户还购买了”栏目，属于利用数据统计、情报检索，以此增加了可观收益，说明发现了潜在有用的信息，符合定义。<br>D项，分析上一年度消费者购物行为，属于对数据统计分析，推出“尿布+啤酒”促销举措，属于发现了潜在有用的销售信息，符合定义。","no":169},{"id":"1718789647922","type":"single","material":"","stem":"心理人类学是介于文化人类学与心理学之间的交叉学科，主要研究并了解文化对所属社会成员产生影响的心理机制，发现在个体水平上的心理变量与在总体水平上的文化、社会、经济、生态和生物变量之间的关系。<br>根据上述定义，下列选项属于心理人类学研究范畴的是：","options":[{"label":"A","content":"“五四”前后诗歌风格的比较"},{"label":"B","content":"当代流行话语下的社会主流价值"},{"label":"C","content":"草原文明与蒙古民族性格的养成"},{"label":"D","content":"从《背影》看作者对父亲态度的变化"}],"answer":"C","explanation":"心理人类学的定义要点：①文化对所属社会成员产生影响的心理机制；②发现在个体水平上的心理变量与在总体水平上的文化、社会、经济、生态和生物变量之间的关系。<br>A项，只是简单比较诗歌风格，没有体现文化对社会成员的影响，不符合要点①。<br>B项，研究的是当下的主流价值观，不是文化对社会成员的影响，不符合要点①。<br>C项，体现了草原文化对所属的社会成员(蒙古民族)产生影响的心理机制(民族性格的养成),符合定义。<br>D项，仅涉及个体，没有体现总量，不符合要点②。","no":170},{"id":"1718789647923","type":"single","material":"","stem":"“休眠效果”是指由信息源可信性带来的说服效果并不是一成不变的。学者霍夫兰等人发现，随着时间的推移，高可信度信源的说服效果会出现衰减，而低可信度信源的说服效果则有上升的趋势。低可信度信源发出的可靠信息，由于信源可信性的负影响，其内容本身的说服力不能得以马上发挥，处于一种“睡眠”状态，经过一段时间，可信性的负影响减弱或消失以后，其效果才能充分表现出来。<br>下列最符合上述研究结论的是：","options":[{"label":"A","content":"虚假的消息即使通过权威报刊发布也不能获得很强的说服力"},{"label":"B","content":"不实的报道经过多重传播后也会有不少人相信"},{"label":"C","content":"真实的消息不论其发布渠道是哪种，最终都会被信任"},{"label":"D","content":"权威报刊发布的消息具有更好的可靠性"}],"answer":"C","explanation":"休眠效果的定义要点：①由信息源可信性带来的说服效果并不是一成不变的；②随着时间的推移，高可信度信源的说服效果会出现衰减，低可信度信源说服效果与之相反。③低可信度信源说服效果，在经过一段时间“睡眠”状态，才能表现出来。<br>A项，虚假的消息即使通过权威报刊发布也不能获得很强的说服力，没有体现受到了高可信度信源的影响，不符合要点①②。<br>B项，不实的报道经过多重传播后也会有不少人相信，这里的“不实的报道”是说信息是虚假的、不可靠的，但并不清楚信息源的可靠性高低，因此无法判断该项是否符合题干的研究结论。<br>C项，真实的消息即使是经过低可信度信源发布的，那么经过一段时间也最终会被信任，符合定义。<br>D项，权威报刊发布的消息属于高可信度信源发布的消息，具有更好的可靠性，不符合要点②。","no":171},{"id":"1718789647924","type":"single","material":"","stem":"牵连犯是指以实施某一犯罪为目的，但其方法行为或结果行为又触犯其他罪名的情况。<br>根据上述定义，下列不属于牵连犯的是：","options":[{"label":"A","content":"甲趁小王不在，潜入他家行窃，窃得财物后遇小王返回，甲遂杀小王灭口"},{"label":"B","content":"乙为骗取保险金，给妻子投了巨额人身保险，后将妻子杀害"},{"label":"C","content":"丙私刻一枚公章，用盖了公章的授权书骗取小张的信任，签订合同，共骗得3万元"},{"label":"D","content":"丁为了谋害小李，通过非法渠道购买了枪支弹药，随后依计划杀死了小李"}],"answer":"A","explanation":"牵连犯定义的关键信息：以实施某一犯罪为目的，但其方法行为或结果行为又触犯其他罪名。<br>A项，甲开始的目的是“非法占有财物”,而杀人并非其进行盗窃的方法或者结果，后来的目的是“非法剥夺他人生命”,目的发生了变化，不符合定义。<br>B项，乙为了骗取保险金，杀害妻子，符合定义。<br>C项，丙为了骗取3万元，私刻公章，符合定义。<br>D项，丁为了杀害小李，购买枪支弹药，符合定义。","no":172},{"id":"1718789647925","type":"single","material":"","stem":"地方保护主义，是指地方政府利用其手中的行政权力，对本地企业和外地企业在经济上实行差别待遇，以维护或扩大该地方局部利益的倾向。<br>根据上述定义，以下情况属于地方保护主义的是：","options":[{"label":"A","content":"南方某山区县为保护本地稀有野生动植物资源，拒绝外地游客进入山区参观"},{"label":"B","content":"某地政府为保证本地品牌的市场占有率，在宣传报道中夸大外地同类产品的缺陷"},{"label":"C","content":"某地为保护当地连锁超市利益，通过收取高额税费限制某跨国超市集团发展"},{"label":"D","content":"某市政府盲目发展本地经济，对大型化工厂的重度污染问题不理睬不治理"}],"answer":"C","explanation":"地方保护主义定义的关键信息：对本地企业和外地企业在经济上实行差别待遇。<br>A项，拒绝外地游客进入山区参观，并不涉及外地企业，不符合定义，排除。<br>B项，夸大外地同类产品的缺陷，并非在经济上实行差别待遇，不符合定义，排除。<br>C项，通过收取高额税费限制某跨国超市发展，是对本地企业和外地企业在经济上实行差别待遇，符合定义的关键信息。<br>D项，对大型化工厂的污染问题不理睬不治理，并不涉及外地企业，不符合定义，排除。","no":173},{"id":"1718789647926","type":"single","material":"","stem":"同群效应，是指处于社会中的个体的行为不仅会受个体自身特质的影响，同时也会受周围与他具有相同或相似的地位、经历或背景的人的影响，从而改变个体单独存在时可能采取的行为。<br>根据上述定义，以下属于同群效应的是：","options":[{"label":"A","content":"小江在超市看到很多人在排队购买打折的鸡蛋，她想起家里的鸡蛋快要吃完了，于是跟别人一起去排队了"},{"label":"B","content":"小娜原计划大学毕业就参加工作，但宿舍同学都积极准备考研，小娜认为考研也不错，也加入了考研的行列"},{"label":"C","content":"小赵腿部有残疾，但他并不消沉，他用张海迪等人的事迹鼓励自己，身体残疾的人通过努力也可以为社会创造价值"},{"label":"D","content":"小方认为人都应该建立家庭、生儿育女，后来她认识了一些独身主义者，认识到人有多种生活方式可以选择"}],"answer":"B","explanation":"同群效应的定义要点：①个体的行为会受到自身特质和周围的人影响；②具有相同的地位、经历或背景；③改变个体单独存在时可能采取的行为。<br>A项，并未体现周围的人与她具有相同或相似的地位、经历或背景，不符合要点②,排除。<br>B项，小娜受到宿舍同学的影响，也加入考研行列，符合定义。<br>C项，有残疾但并没有受到自身特质的影响，不符合要点①,排除。<br>D项，小方受到独身主义者观点的影响，只是认识到有多重生活方式可以选择，并未改变生活方式，不符合要点③。","no":174},{"id":"1718789647927","type":"single","material":"","stem":"牧童经济，是指牧童在放牧时，只管放牧不顾对草原的破坏。经济学中以此来比喻，为追求高生产量(消耗自然资源)和高消费量(商品转化为污染物),大量迅速地消耗自然资源，造成废物累积和环境污染的情况。<br>根据上述定义，以下属于牧童经济的是：","options":[{"label":"A","content":"宇宙飞船中乘客的排泄物经过处理净化，变成氧气、水和盐回收，再给乘客使用"},{"label":"B","content":"猪粪和部分秸秆被用作沼气池的原料，产生的沼气可供做饭、照明"},{"label":"C","content":"某地投入大量资金组织村民种植苹果树，因销路不畅导致苹果成熟后落地，大量腐烂"},{"label":"D","content":"某地为提高农作物产量，大量消耗水资源、化肥和农药，造成土壤、地下水的污染"}],"answer":"D","explanation":"牧童经济的定义要点：①追求高生产量和高消费量；②大量迅速消耗自然资源进而造成废物积累和环境污染。<br>A项，体现的是废物再利用，并没有追求高生产量、高消费量，也没有迅速消耗自然资源造成严重后果，不符合要点①②,排除。<br>B项，体现的是废物再利用，并没有追求高生产量、高消费量，也没有迅速消耗自然资源造成严重后果，不符合要点①②,排除。<br>C项，投资种植苹果树销路不畅而腐烂，并没有体现追求高生产量、高消费量，也没有体现迅速消耗自然资源造成严重后果，不符合要点①②,排除。<br>D项，为了追求高生产量而大量消耗自然资源，造成严重后果，符合定义。","no":175},{"id":"1718789647928","type":"single","material":"","stem":"有位姑娘想要学习绣花作为谋生手艺，但她买不起针线和布料，也无师可拜。她花了十年时间，免费为他人绣花。用他人提供的绣花材料，练就出色的绣花技艺，打出了名声，也积累了大量图样。十年后她以高于市场的价格为人绣花，仍然有很多顾客。有学者由此提出绣花理论，即一个人的职业生涯开始时，可以借助他人的“资源”,义务或以低于市场的价格为提供资源者工作，借此完成自己技能、关系、资金及<br>其他资源的积累，获取职业发展的成功。<br>根据上述定义，以下符合绣花理论的是：","options":[{"label":"A","content":"小江专营户外运动服装批发，他采用薄利多销策略，主动制定比同市场其他商户略低的价格，所经营店铺逐渐成为该批发市场最大的户外运动服装店"},{"label":"B","content":"小齐从事过工程师、教师等多个职位，读研究生时学习了管理工程、人事管理等课程。人力资源管理工作融会了他过去学到的所有知识，他毕业后在此领域大获成功"},{"label":"C","content":"小刘是人力资源专业研究生，上学期间他为多家企业免费做过策划和项目设计，毕业时，由于经验丰富，他顺利进入一家全球500强企业的人力资源部"},{"label":"D","content":"小李是化学专业本科生，大二时他利用学校为其安排的勤工助学计划，给多名高中生进行家教，后来以专业第一的成绩考上了化学系的研究生"}],"answer":"C","explanation":"绣花理论的定义要点：①借助他人的资源；②义务或低于市场价格为提供资源者工作；③获得职业发展的成功。<br>A项，说的是小江的营销策略，并未体现借助他人资源，也没有体现义务或低于市场价格为提供资源者工作，不符合要点①②,排除。<br>B项，说的是小齐从事过多个职位，学习了某些课程，并未体现他义务或低于市场价格为提供资源者工作，不符合要点②,排除。<br>C项，曾为多家企业免费工作，积累经验，最后获得职业发展的成功，符合定义。<br>D项，给高中生做家教是勤工俭学计划，并非为提供资源者工作，不符合要点②;考上研究生也并非获得职业发展的成功，不符合要点③。","no":176},{"id":"1718789647929","type":"single","material":"","stem":"分享经济指个人、组织或企业借助现代化的信息交流手段，盘活闲置资源的经济活动。通过这种活动，供给方能够获得额外收益，需求方能够以更低成本获得产品和服务。<br>根据上述定义，下列属于分享经济的是：","options":[{"label":"A","content":"某小区业委会建立了一个业主微信群，业主家中如果有闲置物品，就可以拍照发到群里，供其他家庭根据需要选用，业主们对业委会的这一做法非常满意"},{"label":"B","content":"每年到毕业季，将要离开校园的大学生们就会在校园的各个角落摆摊设点，甩卖不打算带走的生活用品，低年级的学弟学妹们往往能从中淘到不少“宝贝”"},{"label":"C","content":"某快递公司通过手机软件把用户需求推送给自由快递人，自由快递人选择就近订单，顺路把大大小小的包裹及时、准确地送到客户手中。公司投送费用大幅下降"},{"label":"D","content":"小钟建立网站专门发布来自厂家的技术难题，有偿征集网友设计的解决方案，经过技术处理再行转让，厂家们虽然并未节省研发费用，却很喜欢这种方式"}],"answer":"C","explanation":"分享经济的定义要点：①借助现代化的信息交流手段；②盘活闲置资源；③供方获得额外收益，需求方降低成本。<br>A项，只是说闲置物品供其他家庭根据需要选用，并未体现供方获得额外收益，不符合要点③,排除。<br>B项，在校园的各个角落摆摊设点，并没有利用现代化的信息交流手段，不符合要点①,排除。<br>C项，通过手机软件推送用户需求，符合要点①;有效利用自由快递人，符合要点②;公司投送费用大幅下降，符合要点③。因此该项符合定义。<br>D项，厂家并未节省研发费用，不符合要点③,排除。","no":177},{"id":"1718789647930","type":"single","material":"","stem":"影子工作指消费者使已购商品变为可用物品所付出的任何劳动。根据上述定义，下列属于影子工作的是：","options":[{"label":"A","content":"小孙到饭店就餐，老板告诉他，这几天大部分服务员都已经放假，顾客需要自助点餐，并递给他一支笔和一张菜单"},{"label":"B","content":"小李的儿子快出生了，他赶紧抽时间将同事老王给的婴儿车拿出来修理一番，车子焕然一新，十分好用"},{"label":"C","content":"经不住软磨硬泡，爸爸终于答应给小明买两条金鱼，小明高兴坏了，连夜在网上收集了十几页的金鱼养殖攻略"},{"label":"D","content":"将拼板餐桌从商场运回家后，老冯忙乎了半天，对照安装说明，拆了装，装了拆，终于组装成功，中午就派上了用场"}],"answer":"D","explanation":"影子工作的定义要点：①已购商品；②变为可用物品；③所付出的任何劳动。<br>A项，只是需要自助点餐，所点的东西并非已购商品，不符合要点①,排除。<br>B项，婴儿车是同事给的，而非自己购买的，不符合要点①,排除。<br>C项，小明的爸爸答应给小明买两条金鱼，于是小明连夜收集金鱼养殖攻略，说明金鱼还没有买，并非已购商品，自然也就没有变为可用物品，不符合要点①②,排除。<br>D项，将购买回来的并不能直接使用的拼板餐桌组装完成，变为可用物品，符合定义。","no":178},{"id":"1718789647931","type":"single","material":"","stem":"随机试验指在同一条件下会出现多种可能结果且可以重复进行的试验；试验的所有可能结果虽预先可知，但每次具体实验的结果却无法预知。<br>根据上述定义，下列属于随机试验的是：","options":[{"label":"A","content":"将一壶淡水加热到沸腾，观察其状态变化的实验"},{"label":"B","content":"在狮子身上安装定位设备了解其生活习性的实验"},{"label":"C","content":"为检测某辆新款汽车的安全性能所做的撞击实验"},{"label":"D","content":"抛一枚硬币观察带有数字的一面朝上次数的实验"}],"answer":"D","explanation":"随机试验的定义要点：①在同一条件下会出现多种可能结果；②所有可能结果预先可知；③每次具体实验的结果无法预知。<br>A项，在同一条件下将淡水加热到沸腾，并不会出现多种可能结果，且每次具体实验的结果也是可以预知的，不符合要点①③,排除。<br>B项，了解狮子生活习性的实验确实会出现多种可能结果，但所有可能结果并非预先可知的，不符合要点②,排除。<br>C项，为了解汽车的安全性能所做的撞击实验确实会出现多种可能结果，但所有可能结果并非预先可知的，不符合要点②,排除。<br>D项，抛硬币的实验出现的可能结果包括带数字的一面和不带数字的一面，但是每次出现哪一面无法预知，符合定义。","no":179},{"id":"1718789647932","type":"single","material":"","stem":"临时救助指家庭或个人遭遇突发事件、意外伤害、重大疾病等变故，基本生活陷入困境时，政府有关部门提供的应急性、过渡性救助。<br>根据上述定义，下列属于临时救助的是：","options":[{"label":"A","content":"80岁的李大爷无儿无女，独自生活，社区工作人员定期到他家中探望，把每月的养老金交到他手上，还时不时地送来一些生活用品"},{"label":"B","content":"老张患上了强直性脊柱炎，巨额医疗费花光了积蓄，夫妻名下的房子也变卖了，一家三口只得暂住在街道办为他们租来的小房子里"},{"label":"C","content":"地震发生后，社会各界积极响应市政府号召，通过多种渠道捐款捐物，很快就筹集了大批物资并分发到了灾民手中"},{"label":"D","content":"老赵在几年前的一次车祸中失去了左腿，从那以后再也不能外出工作，每月数百元的低保金就成了家里主要的经济来源"}],"answer":"B","explanation":"临时救助的定义要点：①家庭或个人遭遇突发事件、意外伤害、重大疾病等变故；②政府有关部门；③提供应急性、过渡性救助。<br>A项，李大爷并没有遭遇变故，不符合要点①;社区工作人员定期到李大爷家探望他，每个月交给他养老金，属于长期的救助，不是应急性、过渡性的，不符合要点③。<br>B项，老张患上强直性脊柱炎，即遭遇了重大疾病的变故，符合要点①;一家三口暂住在街道办为他们租来的小房子里，即政府有关部门提供了应急性、过渡性救助，符合要点②③。<br>C项，社会各界捐款捐物，并非政府有关部门提供救助，不符合要点②。<br>D项，老赵在车祸中失去左腿，几年来政府每月给他发放低保金，属于长期的救助，不是应急性、过渡性的，不符合要点③。","no":180},{"id":"1718789647933","type":"single","material":"","stem":"订单式培养指用人单位提出用人申请后，由劳动保障部门委托培训机构根据用工需求组织实施的明确就业岗位去向的人才培养模式。<br>根据上述定义，下列属于订单式培养的是：","options":[{"label":"A","content":"某职业技术学院调研后发现，烹饪即将成为未来数年的紧俏职业，当年就开设了烹饪专业，果不其然，毕业生很抢手，很多餐饮名店都登门签约"},{"label":"B","content":"某民办托儿所急需几名保育员，主管部门接到申请后马上找到一家资深代培机构组织培训，几名合格的保育员很快到岗"},{"label":"C","content":"某市每年都会根据各乡镇上报的用人需求，在全省高校中聘请一批科研人员，然后分派到各地担任科技副镇长"},{"label":"D","content":"某物业公司最近被多个小区选中，需要补充大批保安，为了顺利接手各个小区的安保工作，公司急招了数十名新手，正委托专业保安公司强化培养"}],"answer":"B","explanation":"订单式培养的定义要点：①用人单位根据需求提出申请；②劳动保障部门根据需求委托培训机构培养定向人才。<br>A项，开设烹饪专业是该职业技术学院调研后的结果，并非用人单位根据需求提出的申请，没有体现要点①。<br>B项，某民办托儿所根据需求提出申请，符合要点①;主管部门根据需求委托培训机构定向培养保育员，符合要点②。<br>C项，该市根据各乡镇的用人需求直接聘请科研人员，再分派到各地，并未委托培训机构培养定向人才，没有体现要点②。<br>D项，某物业公司自己招聘了数十名新手，再委托其他公司进行培养，并非用人单位向劳动保障部门提出申请，劳动保障部门再根据申请委托培训机构，没有体现要点①②。","no":181},{"id":"1718789647934","type":"single","material":"","stem":"评论式营销指商家借助对商品、服务的评论引导客户消费倾向，推动产品推广和销售的营销模式。<br>根据上述定义，下列属于评论式营销的是：","options":[{"label":"A","content":"某中药研究所举办了中药膏方的系列公益讲座，许多膏方受益者现身说法，引起了很多市民关注，药店膏方热销"},{"label":"B","content":"某购物网站建立起对买家的信誉评价机制，帮助卖家筛选恶意差评的顾客并列入黑名单，很快提高了店铺的营业额"},{"label":"C","content":"某饭店推出“集赞换龙虾”活动后，有近两千粉丝质疑它的活动规则和龙虾品质，营业额急剧下滑"},{"label":"D","content":"某知名家电企业推出了一款新产品，外包装上醒目地印着行内专家的专业评价，该产品一投放市场就很抢手"}],"answer":"D","explanation":"评论式营销的定义要点：①借助对商品、服务的评论引导客户消费倾向；②推动产品推广和销售。<br>A项，中药研究所举办公益讲座不是为了引导客户消费，不符合要点①。<br>B项，购物网站建立对买家的信誉评价机制是为了筛选恶意差评顾客，并非引导客户消费倾向，不符合要点①。<br>C项，“集赞换龙虾”活动是为了扩大该饭店的知名度，并没有借助对商品、服务的评论引导消费，不符合要点①。<br>D项，借助专家对商品的评论引导客户消费倾向，符合要点①;“很抢手”说明推动了产品推广和销售，符合要点②。","no":182},{"id":"1718789647935","type":"single","material":"","stem":"覆盖竞争指在行业内部竞争已经十分激烈的阶段，行业外部的生产经营者强势介入该行业领域，导致业内竞争进一步加剧的现象。<br>根据上述定义，下列属于覆盖竞争的是：","options":[{"label":"A","content":"从事电子产品设计与开发的某公司进入刚刚开始兴起的无人机研制领域"},{"label":"B","content":"鉴于去年各个分公司的销售业绩都实现了快速增长，公司高层经研究决定今年再成立几家分公司"},{"label":"C","content":"某房地产公司在市区中心地带的大型购物广场开业后，周边五六家大型商场的客流量明显减少"},{"label":"D","content":"某汽车零部件销售商为了进一步满足客户需求，决定新增汽车维修保养业务"}],"answer":"C","explanation":"覆盖竞争定义的关键信息：业内竞争激烈，行业外部的生产经营者强势介入，业内竞争进一步加剧。<br>A项，“刚刚开始兴起”说明业内竞争并不激烈，不符合定义。<br>B项，公司高层决定今年再成立几家分公司，并非行业外部的生产经营者介入，不符合定义。<br>C项，某房地产公司的大型购物广场开业后，周边其他几家大型商场受影响，竞争加剧，符合定义。<br>D项，汽车零部件销售商新增汽车维修保养业务，没有体现业内竞争是否激烈，不符合定义。","no":183},{"id":"1718789647936","type":"single","material":"","stem":"价值自认，指人们常常高估自己行为的价值，并从中获得快乐和美感。根据上述定义，下列属于价值自认的是：","options":[{"label":"A","content":"小张毕业后刚到工作单位，幸运地分到了一套单身公寓。他花了半个月把房间布置得像新房一样，每天一走进去，心里就乐开了花"},{"label":"B","content":"小星在校园机器人竞赛中获得一等奖后，他的父亲老吴整天乐呵呵的，逢人就夸儿子多么多么优秀"},{"label":"C","content":"谢先生的成名曲一夜走红后，很快就跨入影视圈出演了多部电视剧，虽然观众反响平平，他却一直对自己的演技充满自信"},{"label":"D","content":"老赵的作品获得了省书法协会二等奖，同事们纷纷前来向他表示祝贺，他暗下决<br>心：明年一定争取拿到更高的奖项"}],"answer":"C","explanation":"价值自认定义的关键信息：人们常常高估自己行为的价值，并从中获得快乐和美感。<br>A项，小张把房间布置得像新房一样，并未体现他高估自己行为的价值，不符合定义。<br>B项，小星在竞赛中获得一等奖，小星的父亲夸儿子优秀，并未体现他高估自己行为的价值，不符合定义。<br>C项，观众对谢先生出演的电视剧反响平平，但是他却一直对自己的演技充满自信，明显高估了自己行为的价值，并从中获得快乐，符合定义。<br>D项，老赵的作品获得二等奖，他决心明年争取拿到更高的奖项，并未体现他高估自己行为的价值，不符合定义。","no":184},{"id":"1718789647937","type":"single","material":"","stem":"地块经济，指大量的同质化制造加工业小企业集中在一个相对小的区域内，形成比较完整的产业链的区域经济发展模式。<br>根据上述定义，下列不属于地块经济的是：","options":[{"label":"A","content":"义乌小商品闻名遐迩，是国内规模最大的小商品生产和批发基地之一。在那里，各种各样的小商品可以说应有尽有"},{"label":"B","content":"桂林一年四季都挤满了来自全国各地的游客，当地的饭店宾馆、旅游品商店、出租车公司一个个都赚得盆满钵满"},{"label":"C","content":"嵊州堪称“中国领带之乡”,每年生产领带3亿条，出口1.6亿条，在国内、国际市场分别占了90%、60%以上的份额"},{"label":"D","content":"亳州素有“药都”的美誉，每天都有无数商家从四面八方来到这里，运送药材的车队常常是一眼望不到头"}],"answer":"B","explanation":"地块经济定义的关键信息：大量的同质化制造加工业小企业集中在一个相对小的区域内。<br>A项，大量生产小商品的企业集中在义乌，符合大量同质化制造加工业小企业集中在一个相对小的区域内，属于地块经济。<br>B项，桂林当地的饭店宾馆、旅游品商店、出租车公司并不是同质化制造加工业，不符合定义。<br>C项，大量生产领带的企业集中在嵊州，符合大量同质化制造加工业小企业集中在一个相对小的区域内，属于地块经济。<br>D项，大量生产药材的企业集中在亳州，符合大量同质化制造加工业小企业集中在一个相对小的区域内，属于地块经济。","no":185},{"id":"1718789647938","type":"single","material":"","stem":"危机公关是指由于企业管理不善、同行竞争甚至遭遇恶意破坏或者是外界特殊事件的影响，而给企业或者品牌带来危机，企业针对危机所采取的一系列自救行动，包括消除影响、恢复形象等。<br>根据上述定义，下列属于危机公关的是：","options":[{"label":"A","content":"某智能手机制造商在行业竞争中失去领先地位，利润大幅下滑，公司高层决定转向新的领域"},{"label":"B","content":"由于国际原油价格大幅上涨，使得汽油生产成本提高，公司领导召开会议研究对策"},{"label":"C","content":"某智能手机制造商生产的一款手机电池缺陷被曝光后，该智能手机生产商通过媒体向公众道歉，并主动将问题手机召回"},{"label":"D","content":"台风将某公司的户外广告牌吹倒了，公司派人前去修复"}],"answer":"C","explanation":"危机公关定义的关键信息：企业针对所遭受的危机采取的一系列自救行动，包括消除影响、恢复形象等。<br>A项，公司高层决定转向新的领域，并没有针对所遭受的危机采取“消除影响、恢复形象”等措施，不符合定义。<br>B项，公司领导召开会议研究对策，并没有针对所遭受的危机采取“消除影响、恢复形象”等措施，不符合定义。<br>C项，智能手机制造商针对产品质量受到质疑这一危机，采取了道歉和将问题手机召回的行动，体现了“消除影响、恢复形象”,符合定义。<br>D项，广告牌被台风吹倒并不会给企业或者品牌带来危机，不符合定义。","no":186},{"id":"1718789647939","type":"single","material":"","stem":"表象是指事物不在面前时，人们的头脑中出现的关于事物的形象，具有直观性、概括性、可操作性等特点，在形象思维中具有重要作用。<br>根据上述定义，下列属于表象的是：","options":[{"label":"A","content":"没有见过北方冬日的人们，通过诵读毛泽东诗词《沁园春·雪》,可在头脑中形成北国风光的情景"},{"label":"B","content":"猪八戒是吴承恩先生抽象出来的一个人物形象"},{"label":"C","content":"当一个孩子盯着一幅画看上几分钟，闭上眼睛，依然能够清楚地记得这幅画的每一个细节"},{"label":"D","content":"当人们读到《红楼梦》中关于林黛玉生动的外貌描写时，似乎能看到林黛玉就站在眼前"}],"answer":"C","explanation":"表象定义的关键信息：事物不在面前时，头脑中出现事物的形象。由此说明该事物是之前感知过的，只是现在不在面前。<br>A项，没有见过北方冬日的人们在头脑中形成北国风光的情景，也就是对客观事物不曾感知过，是一种想象，不符合定义。<br>B项，猪八戒是文学创作抽象出来的形象，并不是之前感知过的事物，不符合定义。<br>C项，盯着一幅画看上几分钟，即感知过该事物，闭上眼睛相当于画已经不在面前，此时头脑中出现这幅画的细节，符合定义。<br>D项，林黛玉是文学创作抽象出来的形象，并不是之前感知过的事物，不符合定义。","no":187},{"id":"1718789647940","type":"single","material":"","stem":"典范借鉴是指从他人(或对方)那里发现、学习并应用最佳做法的过程，以达到帮助改善自身业绩的目的。<br>根据上述定义，下列属于典范借鉴的是：","options":[{"label":"A","content":"小王刚学打扑克时总是输，后来掌握了打扑克的一些规则和技巧，他打扑克就经常赢"},{"label":"B","content":"张三看见李四在某企业工作收入颇丰，随后他也应聘到该企业上班"},{"label":"C","content":"小刚在同桌小红的帮助下，学习成绩大幅提高"},{"label":"D","content":"某国企吸取国外著名企业生产同类产品的先进经验，降低成本，提高效益"}],"answer":"D","explanation":"典范借鉴的定义要点：①从他人那里发现、学习并应用最佳做法；②改善自身的业绩。<br>A项，打扑克是一种消遣，并非为了改善自身业绩，不符合要点②。<br>B项，张三也应聘到李四所在的企业上班，并不是发现、学习并应用他人的最佳做法，不符合要点①。<br>C项，小刚是在别人的帮助下提高了学习成绩，并非自己主动从他人那里发现、学习并应用最佳做法，不符合要点①。<br>D项，主动吸取其他企业的先进经验，并且提高了效益，符合定义。","no":188},{"id":"1718789647941","type":"single","material":"","stem":"商业秘密是指不为公众所知悉、能为权利人带来经济利益，具有实用性并经权利人采取保密措施的技术信息和经营信息。<br>根据上述定义，下列属于商业秘密的是：","options":[{"label":"A","content":"云南白药的配方"},{"label":"B","content":"淘宝网“双十一”活动的具体细则"},{"label":"C","content":"某军分区的管理规定"},{"label":"D","content":"三七片的功效和作用"}],"answer":"A","explanation":"商业秘密的定义要点：①不为公众所知悉；②采取保密措施。<br>A项，云南白药的配方是权利人采取保密措施不为公众所知悉、且能为权利人带来经济利益的信息，属于商业秘密，符合定义。<br>B项，淘宝“双十一”活动的具体细则是需要公众知悉的，并不会采取保密措施，不符合定义。<br>C项，管理规定需要公众知悉才能遵守，并不会采取保密措施，不符合定义。<br>D项，三七片的功效和作用是需要公众知悉的，并不会采取保密措施，不符合定义。","no":189},{"id":"1718789647942","type":"single","material":"","stem":"三级价格歧视即对于同一商品或相似的商品，垄断厂商根据不同市场上顾客的需求量对价格变动的反应程度的差别，而实施不同的价格，以攫取更多的利益。<br>根据上述定义，下列企业的行为与实施三级价格歧视无关的是：","options":[{"label":"A","content":"某房地产企业对农村户口的客户有更大的优惠"},{"label":"B","content":"高铁设置了特等座、一等座和二等座"},{"label":"C","content":"大多数旅游景点设置了成人票、儿童票、老人票和学生票"},{"label":"D","content":"电信公司根据客户每月上网时间的不同，采取不同的资费标准"}],"answer":"D","explanation":"三级价格歧视定义的关键信息：对于同一商品或相似的商品，垄断厂商根据不同市场上顾客的需求量对价格变动的反应程度的差别，而实施不同的价格。<br>A项，某房地产企业对农村户口的客户有更大的优惠，对同样的房子实施了不同的价格，符合定义。<br>B项，高铁设置了特等座、一等座和二等座，对同样的运输服务收取不同的票价，实施了不同的价格，符合定义。<br>C项，大多数旅游景点设置了成人票、儿童票、老人票和学生票，对不同的客户收取不同的票价，实施了不同的价格，符合定义。<br>D项，电信公司实施不同价格的原因是因为上网时间不同，而非对价格变动反应程度的差别，不符合定义。","no":190},{"id":"1718789647943","type":"single","material":"","stem":"时间综合症指由于对时间的紧迫感而造成心理上的烦恼、紧张，以及生理上的活动改变等导致的病症。下列属于时间综合症的是：","options":[{"label":"A","content":"张先生与李小姐约定下午3点在某公园首次见面，结果李小姐没来，张先生回去后给李小姐发了一条短信：第一次约会就不守时，这样的人不值得交往"},{"label":"B","content":"韩女士经常出差，由于在赶往机场、车站的途中经常发生交通拥堵，所以她后来每次出发都要留出机动时间，并以此告诫家人，做任何事情都要赶早"},{"label":"C","content":"小明上小学五年级，酷爱玩滑板，但他不耽误作业，每天下午放学回家，总是争分夺秒，飞快地把作业做完，然后约同伴一起去玩滑板"},{"label":"D","content":"雷先生办事总是急匆匆的，常唠叨时间紧，偶尔带孩子出去游玩，也是不停地看表，孩子要多玩一会，他就很不耐烦，甚至对孩子大发脾气"}],"answer":"D","explanation":"时间综合症的一个重要特点是造成心理上的烦恼、紧张，只有D项体现了这个特点。故选D。","no":191},{"id":"1718789647944","type":"single","material":"","stem":"审美境界：指从人生境界中升华出来的超越了自然境界、功利境界和道德境界的愉悦情怀和情景。<br>根据上述定义，下列选项中，不属于审美境界的是：","options":[{"label":"A","content":"欣赏名画《蒙娜丽莎》感觉优雅"},{"label":"B","content":"读“采菊东篱下，悠然见南山”产生逍遥感"},{"label":"C","content":"听二胡演奏曲《二泉映月》使人宁静"},{"label":"D","content":"看《炒股指南》从而对股票产生兴趣"}],"answer":"D","explanation":"D项看《炒股指南》从而对股票产生兴趣和从人生境界中升华出来的愉悦情怀和情景无关，不符合审美境界；A项的优雅、B项的逍遥感和C项的宁静均属于超越了自然境界、功利境界和道德境界的愉悦情怀和情景，符合定义。故答案选D。","no":192},{"id":"1718789647945","type":"single","material":"","stem":"孕妇效应，指某一偶然因素因为自己的特别关注而觉得是普遍现象。<br>根据上述定义，下列除了（   ）均属于孕妇效应。","options":[{"label":"A","content":"刘董事长乐观大度，最善于发现员工的优点并发挥他们的潜力"},{"label":"B","content":"小红听说城南菜市场有很多小偷，一天她去那里买菜，果然发现了许多“小偷”"},{"label":"C","content":"李经理到一爱好石头收藏的朋友家后，也喜欢上了石头收藏，从此无论去哪儿都能发现有收藏价值的石头"},{"label":"D","content":"春天换季时，孟晓有一天看见两个人穿的跟她一样，她觉得好多人买了跟自己相同的衣服"}],"answer":"A","explanation":"孕妇效应的定义要点是：某一偶然因素因自己的特别关注而觉得是普遍现象。B、C、D三项均是在特别关注某一偶然因素后认为是普遍现象，符合定义；A项并未涉及任何偶然因素，不符合定义要点。故答案选A。","no":193},{"id":"1718789647946","type":"single","material":"","stem":"合作共赢，是指交易双方或共事双方或多方在完成一项交易活动或共担一项任务的过程中互惠互利、相得益彰，能够实现双方或多方的共同收益。<br>根据上述定义，下列属于合作共赢的是：","options":[{"label":"A","content":"小王打败了竞争对手小李，获得了难得的培训机会，但是小李因祸得福获得了另一个很好的工作机会"},{"label":"B","content":"单位里有个难做的项目，没有人愿意承担，小亮主动请缨，并出色完成任务，公司利润增长，他也获得了晋升"},{"label":"C","content":"宏丰公司和玉源公司五年前合作了一个大项目，这几年宏丰公司的利润在快速增长"},{"label":"D","content":"小秦和小龙一直是很有默契的一对花样游泳组合，在国内外比赛中多次获奖"}],"answer":"D","explanation":"合作共赢的定义要点是：①交易双方或共事双方或多方；②实现双方或多方的共同收益。A项两人是竞争关系，不符合要点①；B项也不符合要点①；C项未体现要点②；只有D项符合定义。故答案选D。","no":194},{"id":"1718789647947","type":"single","material":"","stem":"强迫劳动罪，是指自然人或者单位以暴力、威胁或者限制人身自由的方法强迫他人劳动的行为。所谓限制他人人身自由的方法，是指采取监视、禁止出入等方法而将其限制在一定的场所、区域内劳动。<br>根据上述定义，下列不构成强迫劳动罪的是：","options":[{"label":"A","content":"赵某雇佣民工私自采矿，要求民工不得随意进出工地，起居作息都有固定的时间和场所"},{"label":"B","content":"李某非法雇佣童工在地下工厂工作，要求每天至少工作12个小时以上，否则得不到工钱"},{"label":"C","content":"某组织专门拐卖儿童行乞，每个被拐儿童行乞的地点均有人看守，一旦儿童逃跑被发现便遭毒打"},{"label":"D","content":"某超市为了防止员工私藏超市物品，每次上下班均对员工进行搜身，员工一旦反抗就会被解雇"}],"answer":"D","explanation":"强迫劳动罪的定义要点是以暴力、威胁或者限制人身自由的方法强迫他人劳动。A、C两项属于限制人身自由的方法强迫他人劳动，B项是威胁的方式。D项不构成强迫劳动罪。故本题答案选D。","no":195},{"id":"1718789647948","type":"single","material":"","stem":"角色冲突是当一个人扮演一个角色或同时扮演几个角色时，由于不能胜任，造成不合时宜的冲突和矛盾。角色间冲突是指一个人所担任的不同角色之间发生的冲突。主要表现为两个情形：一是空间和时间上的冲突；二是行为模式内容上的冲突。<br>根据上述定义，下列不属于角色间冲突的是：","options":[{"label":"A","content":"小强放学回家要做家务并给弟弟辅导功课，直到凌晨才能完成学习任务"},{"label":"B","content":"王林结婚之后，妻子和母亲关系不和，忙于工作的同时还要在两人之间斡旋"},{"label":"C","content":"李红高考想报临床医学专业，父母要她报考经济类专业，老师建议她报英文专业"},{"label":"D","content":"杨明最近由普通员工被提升为部门副总监，新的挑战使他忙得焦头烂额"}],"answer":"C","explanation":"根据角色间冲突的定义，A、B两项都是因为同时担任不同的角色产生的冲突；D项是不同角色的转换产生的冲突，属于行为模式内容上的冲突，都符合定义。C项只有高考考生一个角色，因此不属于角色间冲突。故答案为C。","no":196},{"id":"1718789647949","type":"single","material":"","stem":"“劣币驱逐良币”是经济学中的一个著名定律，也称格雷欣法则。该定律是这样一种历史现象的归纳：在铸币时代，当那些低于法定重量或者成色的铸币“劣币”进入流通流域之后，人们就倾向于将那些足值货币“良币”收藏起来。最后，良币将被驱逐，市场上流通的就只剩下劣币了。根据以上定义，下列不属于劣币驱逐良币现象的是：","options":[{"label":"A","content":"在国际交换职能中，强势货币普遍被接受为交换的价值尺度和流通手段，实现国家之间的财富转移。比如：美元、欧元就比卢布更被广为接受，信誉不佳的货币在国际贸易中的地位就愈加下降"},{"label":"B","content":"在香港流通的港币中，同时有十元纸币和十元硬币。由于十元硬币较容易伪造，而且较重，携带较不方便，因此如果一个人同时有十元硬币和十元纸币，他会优先使用硬币"},{"label":"C","content":"平日乘坐公共汽车或地铁上下班，规矩排队者总是被挤得东倒西歪，几趟车也上不去，而不守秩序的人倒常常能够捷足先登，争得座位或抢得时间。最后按秩序排队上车的人越来越少，车辆一来，众人都争先恐后，搞得每次乘车如同打仗，人们苦不堪言"},{"label":"D","content":"工厂为了精简员工，提高效率，要求双职工中的一个必须下岗，工厂的本意是希望能力强的留下，但事实上往往是比较弱势的留在工厂，而有能力的人离开，因为他找到新工作的机率更大"}],"answer":"A","explanation":"定义的关键信息是：劣币留下，良币被驱逐，即差的占优势好的占劣势。A项，强势货币在普遍被接受，信誉不佳的货币地位下降，不符合定义的关键信息。其他三项均符合定义。故答案选A。","no":197},{"id":"1718789647950","type":"single","material":"","stem":"哥伦布大交换是一场东半球与西半球之间生物、农作物、人种、文化、传染病甚至思想观念的突发性交流。它是人类历史上的跨越种族的一件重要事件，引发各种生态上的巨大转变。<br>根据上述定义，下列不属于哥伦布大交换的是：","options":[{"label":"A","content":"来自非洲的可可及亚洲的甘蔗成为拉丁美洲最主要的商业农作物"},{"label":"B","content":"西班牙人带去的天花，成为美洲原住民人口大幅缩减的主要原因"},{"label":"C","content":"北美早期的种植园引进的大量黑奴构成了现在的非裔美国人群体"},{"label":"D","content":"东印度群岛出产的香料因为可以制作腌制食品而改变了欧洲人的饮食习惯"}],"answer":"D","explanation":"哥伦布大交换的定义要点为：①发生在东半球与西半球之间；<br>②生物、农作物、人种、文化、传染病等的突发性交流。D项东印度群岛和欧洲同属于东半球，不符合①。","no":198},{"id":"1718789647951","type":"single","material":"","stem":"国家指导价：指由县级以上（含县级）各级人民政府物价部门、业务主管部门按照国家规定权限，通过规定基准价和浮动幅度、差率、利润率、最高限价和最低保护价等，指导企业制定的商品价格和收费标准。<br>根据上述定义，下列情况属于国家指导价的是：","options":[{"label":"A","content":"某国营商店从外地购进了一批皮大衣，尽管皮大衣市场紧俏，其他个体商店的定价远远高于大衣的价值，但为了维护商店的信誉，商店经理决定皮大衣定价以不高出50%的利润为原则"},{"label":"B","content":"由于生猪出栏率下降，猪肉价格不断上扬，引起市场波动，为此市场物价部门宣布猪肉的最高售价不得高于16元/公斤"},{"label":"C","content":"某厂家生产了一批高质量的水龙头，由于生产原料价格上涨了许多，因此厂里决定把出厂价由原来的3元/个提高到5元/个"},{"label":"D","content":"由于汽油原料物价上涨，市公共汽车公司一直亏损经营，为此公司提出了提高车票价格的请求，经市政府研究同意，公共汽车票价在原来的基础上全部提高2倍"}],"answer":"B","explanation":"国家指导价的主体是县级以上（含县级）各级人民政府物价部门、业务主管部门，A项的商店经理和C项的水龙头厂均不符合定义的主体；D项涉及具体票价的更改，并不是“通过规定基准价和浮动幅度、差率、利润率、最高限价和最低保护价”来指导，不符合定义的手段。故选B。","no":199},{"id":"1718789647952","type":"single","material":"","stem":"碎片化阅读是随着电子设备、移动终端等新技术而出现的一种阅读新趋势。与碎片化阅读联袂而至的，是这种阅读的无处不在与无时不在。但是我们需要警惕，警惕阅读的碎片化会同时带来思想的碎片化，换言之，碎片化阅读正在逐渐改变人们的阅读习惯乃至思维习惯。<br>根据上述定义，下列不属于碎片化阅读的是：","options":[{"label":"A","content":"小甲正在阅读QQ空间里的一篇精彩日志"},{"label":"B","content":"小乙正在品读今天最热的一条微博"},{"label":"C","content":"小丙正在欣赏微信公众号推发的一条广告"},{"label":"D","content":"小丁正在阅读《求是》杂志上的一篇文章"}],"answer":"D","explanation":"碎片化阅读的定义要点是：随着电子设备、移动终端等新技术而出现的一种阅读新趋势。A项QQ空间、B项微博、C项微信都符合定义要点；D项阅读杂志，不符合定义。故答案选D。","no":200},{"id":"1718789647953","type":"single","material":"","stem":"公众参与，是指社会群众、社会组织、单位或个人作为主体，在其权利义务范围内有目的的社会行动。它是一种有计划的行动，通过政府部门和开发行动负责单位与公众之间双向交流，使公民们能参加决策过程并且防止和化解公民和政府机构与开发单位之间、公民与公民之间的冲突。<br>根据上述定义，下列不属于公众参与范畴的是：","options":[{"label":"A","content":"某高速公路选线经过一个自然保护区的外围保护地带，在可行性研究阶段，该公路的建设方征求自然保护区管理机构的意见"},{"label":"B","content":"某工业园区定位为以制革行业为主，在开发过程中，园区开发单位为了获得当地居民对开发行动的支持，组织当地居民代表召开了座谈会"},{"label":"C","content":"某水泥厂建成投产后所产生的粉尘经常超标排放，对周边居民的身心造成了极大的影响，最终被投诉到了环境保护行政主管部门"},{"label":"D","content":"某企业准备新建一条危险化学品生产线，该生产线产生的废水可能会对下游村民的饮用水源水质造成一定的影响。为避免建成后可能引起的环境污染纠纷，该企业的项目负责人在项目初步设计阶段就该项目对下游村民进行了访谈，了解村民的意见和建议"}],"answer":"C","explanation":"公众参与的定义要点是为了防止和化解冲突。C项对居民产生影响，并且被投诉，说明该水泥厂没有为了防止冲突而采取行动，不符合该定义；A项征求管理机构的意见，B项为了获取支持召开座谈会，D项为了避免纠纷而在初期设计时对村民进行调查，均符合定义要点。故答案选C。","no":201},{"id":"1718789647954","type":"single","material":"","stem":"行政强制措施：指行政机关在行政管理过程中，为制止违法行为、防止证据销毁、避免危害发生、控制危险扩大等情形，依法对公民的人身自由实施暂时性限制，或者对公民、法人或者其他组织的财物实施暂时性控制的行为。<br>根据上述定义，下列属于行政强制措施的是：","options":[{"label":"A","content":"公安机关在刑事诉讼中限令犯罪嫌疑人在规定的期限内不得离开住处或者指定的居所"},{"label":"B","content":"交通管理部门对某货车散落在高速公路上的西瓜进行及时清理"},{"label":"C","content":"公安消防部门为了阻止火势蔓延而拆除与着火处相连的房屋"},{"label":"D","content":"医疗机构为防止某精神病人病情发作伤害他人而将其强制约束"}],"answer":"C","explanation":"行政强制措施的定义要点是：①行政机关；②行政管理过程中；③暂时性限制或控制行为。A项是刑事诉讼过程，不符合②；B项不符合③；C项符合定义；D项医疗机构不符合①。故答案选C。","no":202},{"id":"1718789647955","type":"single","material":"","stem":"蚂蚁效应是指一只蚂蚁的力量是微不足道的，但上百万只蚂蚁团结起来，组成一个蚂蚁军团，则可以在几分钟之内将豺狼虎豹啃噬得只剩一堆骨头。懒蚂蚁效应指一些蚂蚁东张西望，把大部分时间用在了侦查和研究上，能观察到组织的薄弱之处，同时保持对新的食物的探索状态，但不像大多数蚂蚁那样忙碌地、搬运食物。在缺少懒蚂蚁的情况下，蚁群会失去寻找食物的能力，而当懒蚂蚁挺身而出时，就能迅速带领蚁群找到食物。<br>根据上述说法，下列哪项体现了懒蚂蚁效应？","options":[{"label":"A","content":"一方有难，八方支援。汶川地震后，全国人民纷纷捐款捐物、领养受灾儿童，以不同的形式支持灾后重建工作"},{"label":"B","content":"红蚂蚁很懒，不愿意寻找食物，衣食住行都要靠黑蚂蚁替它们完成，而且常抢黑蚂蚁的蛹，运回自己的窝里"},{"label":"C","content":"有两个人要去寻找大海，一个人有一根鱼竿，另一个人有一个鱼篓。他们没有各奔东西，而是一起商量怎么去"},{"label":"D","content":"王某是营销部门的主管，很多事情他都只是向下属交代一声，告诉他们怎么做，然后放手让他们去干"}],"answer":"D","explanation":"懒蚂蚁效应的关键点是：①少数蚂蚁；②不像多数蚂蚁那样忙碌；③缺少懒蚂蚁的情况下，组织会失去某些能力。D项王某作为主管，很多事情他都只是向下属交代一声，然后放手让他们去干，不像别人一样忙忙碌碌，符合①②③。其余选项均不符合定义。故答案为D。","no":203},{"id":"1718789647956","type":"single","material":"","stem":"意见领袖是指在人际传播网络中经常为他人提供信息，同时对他人施加影响的“活跃分子”，他们在大众传播效果的形成过程中起着重要的中介或过滤作用，由他们将信息扩散给受众，形成信息传递的两级传播。<br>下列属于意见领袖的是：","options":[{"label":"A","content":"小张是小宋的闺蜜，小张不仅在旅游方面听从小宋的建议，在流行时尚方面更是把她当做老师"},{"label":"B","content":"夏红对化妆品一窍不通，她在咨询了一些美妆用品导购员以后，购买了一支口红和一支睫毛膏"},{"label":"C","content":"在夏令营期间，学生们任何事情都听老师的意见，大家都认为老师的指导是正确的"},{"label":"D","content":"某品牌汽车车友俱乐部的成员都喜欢上该品牌汽车的论坛，他们认为这个论坛提供的消息最准确"}],"answer":"A","explanation":"意见领袖的定义要点是：①人际传播网络中；②经常为他人提供信息，同时对他人施加影响的“活跃分子”。D项不是“活跃分子”；B、C两项不符合①；A项正确。","no":204},{"id":"1718789647957","type":"single","material":"","stem":"气象服务经济包含两层意义，一是指利用气象服务来防灾、抗灾以避免风险和损失；二是指利用有利的气象条件来创造效益。人们可以利用气象信息作为从事经济活动的决策依据之一，可以根据气象服务提供的信息，安排生产经营活动，减少经济损失，提高经济效益。<br>根据上述定义，下列属于气象服务经济的是：","options":[{"label":"A","content":"渔民根据台风警报取消出海作业"},{"label":"B","content":"大学生根据气象预报选择旅行时间"},{"label":"C","content":"电信服务商发布收费天气预报短信"},{"label":"D","content":"根据地球公转周期选择卫星最佳发射时机"}],"answer":"A","explanation":"气象服务经济的意义有：①利用气象服务来防灾、抗灾以避免风险和损失；②利用有利的气象条件创造效益。A项明显符合定义；B、C、D三项均不是利用气象信息安排生产经营活动，排除。故答案选A。","no":205},{"id":"1718789647958","type":"single","material":"","stem":"代表性启发式是指人们在做判断时，如果某人符合既定类别的原型，即得一套属性特征加诸其身的倾向。<br>下列不属于代表性启发式的是：","options":[{"label":"A","content":"贾某主张大学生假期应该参加公益服务活动，记者问他，有多少大学生会和他做出相同的选择，他回答，多数人"},{"label":"B","content":"李某在老师心目中是一个愚蠢、懒惰、成绩差的学生，有一次语文考试李某考出了95分的好成绩，老师认为他的成绩是考试作弊所得"},{"label":"C","content":"当你走进教室，你可能会很快地认出教授，因为他就是那个时装感颇值得商榷和头发有点凌乱的人"},{"label":"D","content":"你负责接待某公司的老总，从车上下来一高一矮两个男人，你会把那位高大、气度不凡的男性认定为总经理"}],"answer":"A","explanation":"代表性启发式的定义要点是：“某人符合既定类别的原型即得一套属性特征加诸其身”，A项不符合，故选A。","no":206},{"id":"1718789647959","type":"single","material":"","stem":"网络文学，是一种新近出现的文学样式，它是指以互联网为发表平台和传播媒介，借助超文本链接和多媒体演绎的手段来表现主题，在网上创作发表，供网民阅读的文学作品、类文学文本及含有一部分文学成分的网络艺术品，其中以网络文学原创作品为主。<br>根据以上定义，下列不属于网络文学的是：","options":[{"label":"A","content":"赵某是某省公务员论坛的管理员，负责在论坛中管理帖子，也发表一些关于考公务员的经验帖子供大家参考"},{"label":"B","content":"张某在自己的博客上创作的诗歌连载"},{"label":"C","content":"李某是某门户网站儿童文学的专业写手，负责每个星期在网站发表连载"},{"label":"D","content":"王某是一名教师，业余时间在个人空间写游记，得到很多网站的转载和网民的跟帖"}],"answer":"A","explanation":"网络文学的定义要点是：①以互联网为发表平台和传播媒介；<br>②文学作品、类文学文本及含有一部分文学成分的网络艺术品。A项只是管理帖子和发表帖子，不符合要点②；B、C、D三项都属于网络文学。故答案选A。","no":207},{"id":"1718789647960","type":"single","material":"","stem":"灵感思维：是指凭借直觉而进行的快速、顿悟性的思维。它不是一种简单逻辑或非逻辑的单向思维运动，而是逻辑性与非逻辑性相统一的理性思维整体过程。灵感思维具有突发性和模糊性、独创性、非自觉性、思维灵活活动等特点。<br>下列属于灵感思维的是：","options":[{"label":"A","content":"侯振挺送朋友上火车排队，一年多来梦寐以求的符号竟然清晰地出现在脑际，写成了《排队论中的巴尔姆断言的证明》，引起数学界的重视"},{"label":"B","content":"达尔文读马尔萨斯的《人口论》，大脑一道闪光，促成了生物进化论的形成"},{"label":"C","content":"熟悉的可口可乐瓶设计来源于设计者的女朋友穿的一件下口收紧的紧身裙子形象"},{"label":"D","content":"生物学DNA双螺旋结构的发现者沃森在谈到一次构想时说：“我的手指冻得没法写字，只能蜷缩在炉火边，胡思乱想，想到一些DNA链怎样美妙地蜷缩起来，而且可能以很科学的方式排列起来。果然这个美妙的难以使人置信的模型，开创了分子生物学的新篇章。”"}],"answer":"B","explanation":"灵感思维具有突发性和模糊性、独创性、非自觉性、思维灵活活动等特点。A项清晰不符合模糊性，C项不符合独创性，D项胡思乱想不符合突发性。故答案选B。","no":208},{"id":"1718789647961","type":"single","material":"","stem":"社会福利是指国家依法为所有公民普遍提供旨在保证一定生活水平和尽可能提高生活质量的资金和服务的社会保障制度。广义的社会福利是指提高广大社会成员生活水平的各种政策和社会服务，旨在解决广大社会成员在各个方面的福利待遇问题。狭义的社会福利是指对生活能力较弱的儿童、老人、母子家庭、残疾人、慢性精神病人等的社会照顾和社会服务。<br>下列选项不属于社会福利的是：","options":[{"label":"A","content":"工伤保险"},{"label":"B","content":"政府为老年人提供老年福利"},{"label":"C","content":"城市兴建公园为市民提供休息纳凉好去处"},{"label":"D","content":"某公司为其职工及家属提供职业福利"}],"answer":"D","explanation":"社会福利的主体是国家，D项的主体是某公司，不符合定义。故答案选D。","no":209},{"id":"1718789647962","type":"single","material":"","stem":"专家系统，是指一个电脑系统具有某专业领域的特定知识，可以解决该专业领域的问题或给出建议，是人工智能领域较成功的例子。<br>下列属于专家系统的是：","options":[{"label":"A","content":"网上银行系统，通过该系统，用户可以在网上管理其账户"},{"label":"B","content":"办公自动化系统，以电子计算机为中心，把文字处理机、传真、打印机等办公设备有机的结合起来，用作日常办公"},{"label":"C","content":"深蓝系统，IBM公司专门为国际象棋竞赛所开发的电脑系统"},{"label":"D","content":"公交查询系统，通过该系统，用户可以查询到各路公交汽车的停靠站点、交汇转车站等信息"}],"answer":"C","explanation":"专家系统的关键信息是：具有专业领域的特定知识。对选项进行分析，A、B、D三项都不符合该定义的关键信息，只有C项具有国际象棋的专业知识，属于专家系统。故答案选C。","no":210},{"id":"1718789647963","type":"single","material":"","stem":"概念混淆，是指由于自然语言的多义性和模糊性而产生的非形式谬误。构型歧义，是指由于句子语法结构的不确定而产生的歧义性谬误。<br>根据上述定义，下列属于构型歧义的是：","options":[{"label":"A","content":"一人去算命，问家庭，算命先生掐指一算，说：“父在母先亡。”"},{"label":"B","content":"问：如果你哥哥有五个苹果，你拿走三个，结果怎样？答：结果他会揍我一顿"},{"label":"C","content":"三个秀才问考试结果，算命先生伸出一个手指头，说了个“一”，便再不出声"},{"label":"D","content":"元宵夜，一女子想要去观灯，丈夫说：“家中不是已点灯了吗？”"}],"answer":"A","explanation":"构型歧义是由句子结构不确定而产生的歧义。A项中“父在母先亡”，有两种理解：父在/母先亡（父健在，母先亡）；父在母先/亡（父在母之前亡，即父先亡）。这是由于句子结构不同造成的歧义；B、C、D三项均不符合构型歧义。故答案选A。","no":211},{"id":"1718789647964","type":"single","material":"","stem":"埋伏营销是指企业利用媒体和公众对重大事件的关注，通过举办与重大事件相关的活动，使自己与重大事件产生关联，从而引起消费者的联想和媒体的注意。这类营销通常是隐蔽的、突发的，不以赞助者的身份出现，却对自己的品牌悄无声息地进行了宣传。<br>根据上述定义，下列不属于埋伏营销的是：","options":[{"label":"A","content":"某矿泉水公司邀请著名运动员为其代言，并将广告投放在电视媒体的黄金时段和一些大型酒店的视频媒体中"},{"label":"B","content":"地震发生后，某户外用品公司向灾区捐赠价值100万元的帐篷，并举行了捐赠仪式"},{"label":"C","content":"某市举办中小学生知识竞赛，一出版集团在现场向参与者免费发放其出版的图书"},{"label":"D","content":"世界一级方程式锦标赛比赛期间，观众席中时不时会有人挥舞着印有某轮胎企业商标的彩色旗帜"}],"answer":"A","explanation":"埋伏营销的定义要点为：①通过举办与重大事件相关的活动，使自己与重大事件产生关联；②隐蔽的、突发的，不以赞助者的身份出现。A项邀请著名运动员代言并投放广告，既未与重大事件相关联，又很明显地打广告，不符合定义要点；B项和地震事件关联、C项和知识竞赛关联、D项和方程式锦标赛关联，并且都是相对较隐蔽的方式，均符合定义。故答案选A。","no":212},{"id":"1718789647965","type":"single","material":"","stem":"积极的财政政策，又称扩张性财政政策，是指通过财政分配活动来增加和刺激社会的总需求的一系列措施的总称，其实现途径有减税、增加财政补贴、扩大财政支出等。<br>根据上述定义，下列不属于积极的财政政策的是：","options":[{"label":"A","content":"为降低房地产库存量，国家出台措施将房产交易中的契税税率由3%调整到1.5%"},{"label":"B","content":"为降低房地产库存量，央行下发通知要求各商业银行放松信贷控制"},{"label":"C","content":"为促进创新创业，国家出台文件要求各级政府加大支持力度，增加对石墨烯材料研发及其应用的补贴"},{"label":"D","content":"为落实生态文明建设，国家出台文件要求各地政府扩大用于环保工作的支出"}],"answer":"B","explanation":"积极的财政政策的主要途径有：减税、增加财政补贴、扩大财政支出。A项属于减税，C项属于增加财政补贴，D项属于扩大财政支出，均符合定义；B项放松信贷控制属于金融政策里的货币政策，不符合定义。故答案选B。","no":213},{"id":"1718789647966","type":"single","material":"","stem":"创新是指以现在的思维模式提出有别于常规或常人思路的见解为导向，利用现有的知识和物质，在特定的环境中，本着理想化需要或为满足社会需求，而改进或创造新的事物（包括产品、方法、元素、路径、环境），并能获得一定有益效果的行为。<br>根据上述定义，下列不属于创新的是：","options":[{"label":"A","content":"国内建成首台散裂中子源"},{"label":"B","content":"某农林场主在网上销售“无尘农业”种植的果蔬"},{"label":"C","content":"某超市为缓解购物拥挤增设收银台"},{"label":"D","content":"马云创办的阿里巴巴旗下的“淘宝"}],"answer":"C","explanation":"创新定义的要点：改进或创造新的事物并能获得一定有益效果。A、B、D三项均符合定义的要点。C项增设收银台不是改进或创造新事物，只是对原有事物数量上的改变，不符合定义的要点。故本题选C。","no":214},{"id":"1718789647967","type":"single","material":"","stem":"劳动者报酬是指劳动者从其所在单位通过各种渠道得到的所有货币形式或实物形式的劳动收入。<br>下列属于劳动者报酬的是：<br>①小平购买所在企业股票获得2000元的收益<br>②小张被选为某区五一劳动奖章获得者，得到奖金1000元<br>③小李在本单位获得夏季高温补贴500元<br>④小陈所在单位为其每月缴纳社会保险金300元","options":[{"label":"A","content":"①②④"},{"label":"B","content":"①③④"},{"label":"C","content":"①③"},{"label":"D","content":"③④"}],"answer":"D","explanation":"①中股票为小平个人购买，而非企业作为员工福利发放，属于个人行为而非企业行为，不属于劳动报酬，故排除A、B、C。且五一劳动奖的奖金不是单位发放，也不属于劳动报酬。故本题选D。","no":215},{"id":"1718789647968","type":"single","material":"","stem":"有意想象指事先有预定目的的想象，可分为再造想象和创造想象。前者指根据别人的描述或图样，在头脑中形成新形象的过程；后者指不根据现成的描述，而在大脑中独立的产生新形象的过程。<br>根据上述定义，下列属于创造想象的是：","options":[{"label":"A","content":"老刘故地重游时脑海里浮现了一些往事"},{"label":"B","content":"公安人员根据受害者的描述画出犯罪嫌疑人的肖像"},{"label":"C","content":"人们在听评书《三国演义》时仿佛身临其境来到了古战场"},{"label":"D","content":"小明在他创作的科幻小说中描绘了未来人类在月球上的生活图景"}],"answer":"D","explanation":"创造想象是不根据现成的描述，而在大脑中独立产生新形象。D项符合定义。A项中的往事不是新形象。B、C两项是根据别人的描述形成形象，属于再造想象。故本题选D。","no":216}]};
